const mac = global.get("gatewayEui");       // MAC Gateway
const zones = global.get("zones") || [];    // Tableau des zones

const dns = "10.1.xx.150";
const siteId = xxxx;

// nbZone = max(numero) si cohérent, sinon zones.length
let nbZone = 0;

if (Array.isArray(zones) && zones.length > 0) {
    let maxNumero = 0;

    for (let i = 0; i < zones.length; i++) {
        const n = Number(zones[i]?.numero);
        if (Number.isFinite(n) && n > maxNumero) maxNumero = n;
    }

    const count = zones.length;
    const tol = Math.max(2, Math.round(count * 0.10)); // tolérance 10% mini 2
    const ok =
        maxNumero > 0 &&
        (Math.abs(maxNumero - count) <= tol || Math.abs(maxNumero - (count - 1)) <= tol);

    nbZone = ok ? maxNumero : count;
} else {
    nbZone = global.get("nbZone") || 17; // fallback
}

global.set("mac", mac);
global.set("nbZone", nbZone);
global.set("dns", dns);
global.set("siteId", siteId);

node.status({
    fill: "blue",
    shape: "dot",
    text: `MAC:${mac} | Zones:${nbZone} | DNS:${dns} | Site:${siteId}`
});

return msg;

// Code à mettre dans un nouveau node Function

const handleApiResponse = global.get('handleApiResponse');

// Récupérer le topic depuis le message ou déduire du contexte
let apiTopic = null;

// 1. Essayer d'abord le topic du message
if (msg.topic) {
    apiTopic = msg.topic;
}
// 2. Si pas de topic, essayer de déduire de l'URL
else if (msg.req && msg.req.url) {
    const url = msg.req.url;
    if (url.includes('/api/internal/login')) {
        apiTopic = 'gateway_auth';
    } else if (url.includes('/api/packet-forwarder/network-servers')) {
        apiTopic = 'gateway_mac';
    }
}
// 3. Si toujours pas de topic, regarder les headers d'autorisation
else if (msg.headers && msg.headers.Authorization) {
    // C'est probablement une requête Semlink, regarder les paramètres
    if (msg.mac && msg.siteId) {
        // Extraire le topic des paramètres de requête si possible
        const payload = msg.payload;
        if (typeof payload === 'object' && payload !== null) {
            // Le topic peut être déterminé par le contenu de la réponse
            if (payload.statut === 'success' && payload.data) {
                // Regarder la structure des données pour deviner le topic
                if (Array.isArray(payload.data)) {
                    const firstItem = payload.data[0];
                    if (firstItem) {
                        if (firstItem.hasOwnProperty('planningId')) apiTopic = 'zones';
                        else if (firstItem.hasOwnProperty('day1')) apiTopic = 'plannings';
                        else if (firstItem.hasOwnProperty('startDate')) apiTopic = 'events';
                        else if (firstItem.hasOwnProperty('deveui')) apiTopic = 'materiels';
                    }
                } else if (typeof payload.data === 'object') {
                    if (payload.data.hasOwnProperty('codePostalSITE')) apiTopic = 'params';
                }
            }
        }
    }
}

// Validation de la réponse API
if (handleApiResponse && msg.statusCode && apiTopic) {
    handleApiResponse(apiTopic, msg.statusCode, msg.payload);
    node.warn(`🔗 API Validated: ${apiTopic} → Status ${msg.statusCode}`);
} else if (handleApiResponse && msg.statusCode) {
    node.warn(`⚠️ Topic API non identifié pour validation - Status ${msg.statusCode} - URL: ${msg.req?.url || 'N/A'}`);
}

return msg; // Passer le message au node suivant

const CFG = {
    initialWait: 5000,     // 5s
    retryInterval: 10000,  // 10s
    maxDuration: 60000,    // 60s
    maxAttempts: 5,
    // Configuration du retry global
    globalRetryEnabled: true,    // Active le retry global en cas d'échec
    maxGlobalRetries: 20,        // Nombre max de relances complètes
    globalRetryDelay: 30000,    // 30s entre chaque relance
    variables: ['meteo', 'params', 'zones', 'plannings', 'materiels', 'plannings_e', 'events'],
    requiredParams: ['mac', 'nbZone', 'dns', 'siteId'],
    outputs: {
        'INITIALISATION FILE - OBLIGATOIRE': 0,
        'Variables to read': 1,
        'Variables to write': 2,
        'Initialisation API GATEWAY': 3,
        'request mac gateway': 4,
        'RENSEIGNER PARAMS - OBLIGATOIRE': 5,
        'Inject params': 6,
        'Inject zones': 7,
        'Inject plannings': 8,
        'Inject materiels': 9,
        'Inject events': 10,
        'Inject plannings_e': 11,
        'Recup. Conditions Meteo': 12,
        'Inject INIT des Flows': 13
    }
};

// Gestion du retry global
function getGlobalRetryState() {
    return global.get('__global_retry_state') || {
        attempt: 0,
        lastAttempt: 0,
        totalAttempts: 0
    };
}

function updateGlobalRetryState(state) {
    global.set('__global_retry_state', state);
}

function resetGlobalRetryState() {
    const state = {
        attempt: 0,
        lastAttempt: 0,
        totalAttempts: 0
    };
    updateGlobalRetryState(state);
    node.warn('🔄 État de retry global réinitialisé');
}

// Fonction pour relancer l'exécution complète
function scheduleGlobalRetry(reason) {
    if (!CFG.globalRetryEnabled) {
        node.warn('❌ Retry global désactivé dans la configuration');
        return false;
    }

    const retryState = getGlobalRetryState();

    // Vérifier si on a atteint le maximum
    if (retryState.attempt >= CFG.maxGlobalRetries) {
        status('🚨 ÉCHEC DÉFINITIF - Max retries atteint', 'red', 'dot');
        node.warn(`🚨 ÉCHEC DÉFINITIF: ${CFG.maxGlobalRetries} tentatives complètes effectuées`);
        return false;
    }

    // Éviter les relances trop rapprochées
    const timeSinceLastAttempt = Date.now() - retryState.lastAttempt;
    if (timeSinceLastAttempt < 10000) { // 10s minimum entre tentatives
        node.warn('⏳ Retry ignoré: délai insuffisant depuis la dernière tentative');
        return false;
    }

    retryState.attempt++;
    retryState.lastAttempt = Date.now();
    retryState.totalAttempts++;
    updateGlobalRetryState(retryState);

    const delaySeconds = Math.round(CFG.globalRetryDelay / 1000);
    status(`🔄 Retry ${retryState.attempt}/${CFG.maxGlobalRetries} dans ${delaySeconds}s`, 'yellow', 'ring');
    node.warn(`🔄 Programmation retry global: ${reason}`);
    node.warn(`   └─ Tentative ${retryState.attempt}/${CFG.maxGlobalRetries} (Total: ${retryState.totalAttempts})`);

    // Programmer la relance automatique
    setTimeout(() => {
        node.warn('🔄 Relance automatique de l\'initialisation...');
        // Relancer en appelant directement la fonction principale
        executeMainSequence();
    }, CFG.globalRetryDelay);

    return true;
}

// Politique de déclenchement améliorée
if (msg.payload === 'reset_global_retry') {
    resetGlobalRetryState();
    return null;
} else if (msg.payload !== 'manual_check' && msg.payload !== 'check_variables') {
    return null;
}

let run = global.get('__checkV3_retry') || { running: false, last: 0 };
if (run.running) {
    node.warn('Processus déjà en cours');
    return null;
}
run.running = true;
run.last = Date.now();
global.set('__checkV3_retry', run);

// État de validation des requêtes API
let apiValidation = global.get('__api_validation') || {};

function mkBase() { return { timestamp: Date.now(), checkId: run.last }; }
function status(text, color = 'yellow', shape = 'ring') { node.status({ fill: color, shape, text }); }
function sleep(ms) { return new Promise(res => setTimeout(res, ms)); }

function pulse(name, extra = {}) {
    const i = CFG.outputs[name];
    if (i === undefined) { node.warn(`❌ Sortie inconnue: ${name}`); return false; }

    let m = null;
    if (name === 'INITIALISATION FILE - OBLIGATOIRE') {
        m = { payload: '', filename: 'lora.json', file: { format: 'utf8', encoding: 'utf8' }, ...mkBase() };
    } else if (name === 'Variables to read') {
        m = { payload: 'read_variables', ...mkBase() };
    } else if (name === 'Variables to write') {
        m = { payload: 'write_variables', ...mkBase() };
    } else if (name === 'Initialisation API GATEWAY') {
        m = { payload: { username: 'admin', password: '9WsHVTRClkEqO0XXH1l1bpJ8nQgXEWjNeTjTJbkDHzM=' }, rejectUnauthorized: false, apiTopic: 'gateway_auth', ...mkBase() };
    } else if (name === 'request mac gateway') {
        const api = global.get('apikey_gateway');
        if (api) m = { headers: { Authorization: 'Bearer ' + api }, payload: null, apiTopic: 'gateway_mac', ...mkBase() };
    } else if (name === 'RENSEIGNER PARAMS - OBLIGATOIRE') {
        m = { payload: 'params_required', ...mkBase() };
    } else if (name === 'Recup. Conditions Meteo') {
        m = { topic: 'meteo', payload: global.get('params.codePostalSITE'), ...mkBase() };
    } else if (name.startsWith('Inject ')) {
        const t = name.split(' ')[1];
        const mac = global.get('mac');
        const siteId = global.get('siteId');
        if (mac && siteId) m = { topic: t, mac, siteId, originalTopic: t, ...mkBase() };
    }

    if (!m) { node.warn(`⚠️ Pulse ignoré (conditions non remplies) → ${name}`); return false; }

    const msgs = new Array(14).fill(null);
    msgs[i] = { ...m, ...extra };
    node.send(msgs);
    node.warn(`📤 Pulse → sortie ${i}: ${name}`);
    return true;
}

// Fonction pour valider le succès d'une requête API
function isApiCallSuccessful(topic) {
    const validation = apiValidation[topic];
    if (!validation) return false;

    const isRecent = (Date.now() - validation.timestamp) < 30000;

    // Vérifier que ce n'est pas une erreur de connexion
    const isConnectionError = typeof validation.statusCode === 'string' &&
        (validation.statusCode.includes('ECONNREFUSED') ||
            validation.statusCode.includes('ETIMEDOUT') ||
            validation.statusCode.includes('ENOTFOUND') ||
            validation.statusCode.includes('EHOSTUNREACH'));

    // Succès = status code 200 ET pas d'erreur de connexion
    const isSuccess = validation.statusCode === 200 && !isConnectionError;

    return isRecent && isSuccess;
}

// Fonction pour marquer une requête API comme réussie/échouée
function markApiSuccess(topic, statusCode = 200, responseData = null) {
    // Détecter les erreurs de connexion
    const isConnectionError = typeof statusCode === 'string' &&
        (statusCode.includes('ECONNREFUSED') ||
            statusCode.includes('ETIMEDOUT') ||
            statusCode.includes('ENOTFOUND') ||
            statusCode.includes('EHOSTUNREACH'));

    apiValidation[topic] = {
        timestamp: Date.now(),
        statusCode: statusCode,
        success: statusCode === 200 && !isConnectionError,
        isConnectionError: isConnectionError,
        responseData: responseData
    };
    global.set('__api_validation', apiValidation);

    // Log différencié selon le type d'erreur
    if (isConnectionError) {
        node.warn(`🔗 API Connection Error - Topic: ${topic}, Error: ${statusCode}`);
    } else if (statusCode !== 200) {
        node.warn(`🔗 API HTTP Error - Topic: ${topic}, Status: ${statusCode}`);
    } else {
        node.warn(`🔗 API Success - Topic: ${topic}, Status: ${statusCode}`);
    }
}

// Helper amélioré avec validation API
async function waitUntilWithApiValidation(desc, checkerFn, apiTopics = []) {
    const start = Date.now();
    let attempts = 0;

    await sleep(CFG.initialWait);

    while (true) {
        const dataOk = !!checkerFn();

        let apiOk = true;
        if (apiTopics.length > 0) {
            apiOk = apiTopics.every(topic => isApiCallSuccessful(topic));
        }

        const allOk = dataOk && apiOk;

        if (allOk) {
            node.warn(`✅ ${desc} - Données: ${dataOk ? 'OK' : 'KO'}, API: ${apiOk ? 'OK' : 'KO'}`);
            return true;
        }

        attempts++;
        const elapsed = Date.now() - start;
        const statusMsg = `${desc} ⏳ ${attempts}/${CFG.maxAttempts} • ${Math.round(elapsed / 1000)}s`;
        const detailMsg = `(Data: ${dataOk ? '✓' : '✗'}, API: ${apiOk ? '✓' : '✗'})`;

        status(`${statusMsg} ${detailMsg}`, 'yellow', 'ring');

        if (attempts >= CFG.maxAttempts || elapsed >= CFG.maxDuration) {
            node.warn(`❌ Timeout: ${desc} après ${attempts} tentatives et ${Math.round(elapsed / 1000)}s`);
            node.warn(`   └─ État final - Données: ${dataOk ? 'OK' : 'KO'}, API: ${apiOk ? 'OK' : 'KO'}`);
            return false;
        }
        await sleep(CFG.retryInterval);
    }
}

function handleApiResponse(topic, statusCode, responseData) {
    markApiSuccess(topic, statusCode, responseData);
    // Le log est maintenant dans markApiSuccess
}

// ===== FONCTION PRINCIPALE D'EXÉCUTION =====
async function executeMainSequence() {
    try {
        const retryState = getGlobalRetryState();

        // Log du démarrage
        if (retryState.attempt > 0) {
            status(`🔄 Retry ${retryState.attempt}/${CFG.maxGlobalRetries} en cours...`, 'yellow');
            node.warn(`🔄 Tentative de retry global ${retryState.attempt}/${CFG.maxGlobalRetries}`);
        } else {
            status('🚀 Lancement initial...', 'yellow');
        }

        // Réinitialiser l'état de validation des API
        apiValidation = {};
        global.set('__api_validation', apiValidation);

        // Step 1: Chargement des variables
        status('📂 Lecture fichiers…', 'yellow');
        pulse('Variables to read');
        const varsOk = await waitUntilWithApiValidation(
            'Chargement variables',
            () => {
                for (const v of CFG.variables) {
                    if (typeof global.get(v) === 'undefined') return false;
                }
                return true;
            }
        );
        if (!varsOk) {
            pulse('INITIALISATION FILE - OBLIGATOIRE');
            throw new Error('Variables non chargées');
        }
        status('✅ Variables chargées', 'green', 'dot');

        // Step 2: Synchronisation des variables
        pulse('Variables to write');
        await sleep(500);

        // Step 3: Initialisation API Gateway
        status('🔑 Authentification Gateway…', 'yellow');
        pulse('Initialisation API GATEWAY');

        const apiOk = await waitUntilWithApiValidation(
            'Initialisation API Gateway',
            () => !!global.get('apikey_gateway'),
            ['gateway_auth']
        );
        if (!apiOk) throw new Error('API Gateway non initialisée');
        status('🔑 API Gateway OK', 'green', 'dot');

        // Step 4: Récupération MAC Gateway
        status('🆔 Récupération MAC Gateway…', 'yellow');
        pulse('request mac gateway');

        const macOk = await waitUntilWithApiValidation(
            'Récupération MAC Gateway',
            () => !!global.get('gatewayEui'),
            ['gateway_mac']
        );
        if (!macOk) throw new Error('MAC Gateway non reçue');
        status(`🆔 MAC OK (${global.get('gatewayEui')})`, 'green', 'dot');

        // Step 5: Vérification paramètres obligatoires
        const missP = [];
        for (const p of CFG.requiredParams) {
            const v = global.get(p);
            if (v === null || typeof v === 'undefined') missP.push(p);
        }
        if (missP.length) {
            pulse('RENSEIGNER PARAMS - OBLIGATOIRE', { missingParams: missP });
        }
        const paramsOk = await waitUntilWithApiValidation(
            'Paramètres obligatoires',
            () => {
                for (const p of CFG.requiredParams) {
                    const v = global.get(p);
                    if (v === null || typeof v === 'undefined') return false;
                }
                return true;
            }
        );
        if (!paramsOk) throw new Error('Paramètres obligatoires manquants');
        status('✅ Paramètres OK', 'green', 'dot');

        // Step 6: Injections Semlink
        status('📡 Requêtes Semlink…', 'yellow');
        const semlinkTopics = ['params', 'zones', 'plannings', 'materiels', 'events', 'plannings_e'];

        for (const topicName of semlinkTopics) {
            const pulseName = `Inject ${topicName}`;
            pulse(pulseName);
            await sleep(250);
        }

        const semlinkOk = await waitUntilWithApiValidation(
            'Synchronisation Semlink',
            () => true,
            semlinkTopics
        );

        if (!semlinkOk) {
            node.warn('⚠️ Certaines requêtes Semlink ont échoué, mais on continue...');
        }

        // Step 7: Récupération météo
        pulse('Recup. Conditions Meteo');
        await sleep(250);

        // Step 8: Initialisation finale
        if (global.get('params') !== null && typeof global.get('params') !== 'undefined') {
            const msgs = new Array(14).fill(null);
            msgs[13] = { payload: Date.now(), ...mkBase() };
            node.send(msgs);
            node.warn('📤 Pulse → sortie 13: Init-PARAM-Flow');
        } else {
            node.warn('⚠️ Pulse Init-PARAM-Flow non envoyé : params absent');
        }

        // ✅ SUCCÈS COMPLET - Réinitialiser les compteurs
        resetGlobalRetryState();
        status('🎉 Initialisation RÉUSSIE !', 'green', 'dot');

        const validationSummary = Object.entries(apiValidation)
            .map(([topic, data]) => `${topic}: ${data.success ? '✓' : '✗'}`)
            .join(', ');
        node.warn(`📊 Résumé API: ${validationSummary}`);
        node.warn('🎉 Système complètement initialisé avec succès !');

    } catch (e) {
        const errorMsg = e.message || e;
        status(`❌ Erreur: ${errorMsg}`, 'red', 'dot');
        node.warn(`❌ Échec d'initialisation: ${errorMsg}`);

        // 🔄 PROGRAMMATION DU RETRY GLOBAL EN CAS D'ÉCHEC
        const retryScheduled = scheduleGlobalRetry(`Échec: ${errorMsg}`);
        if (retryScheduled) {
            const delaySeconds = Math.round(CFG.globalRetryDelay / 1000);
            status(`🔄 Retry programmé dans ${delaySeconds}s`, 'yellow', 'ring');
        } else {
            status('🚨 Échec définitif - Max retries atteint', 'red', 'dot');
        }
    } finally {
        run.running = false;
        run.last = Date.now();
        global.set('__checkV3_retry', run);
    }
}

// ===== LANCEMENT INITIAL =====
executeMainSequence();

// Fonctions utilitaires globales
global.set('handleApiResponse', handleApiResponse);
global.set('forceGlobalRetry', () => scheduleGlobalRetry('Retry forcé par utilisateur'));
global.set('resetGlobalRetry', resetGlobalRetryState);

return null;

msg.topic = 'gateway_auth'; // Identifier le topic pour la validation

// Dans vos nodes HTTP Response
const handleApiResponse = global.get('handleApiResponse');
if (handleApiResponse && msg.statusCode) {
    handleApiResponse(msg.topic, msg.statusCode, msg.payload);
}

global.set("apikey_gateway", "Bearer "+msg.payload.jwt);

msg.jwt = global.get("apikey_gateway");
return msg;

// Dans vos nodes HTTP Response
const handleApiResponse = global.get('handleApiResponse');
if (handleApiResponse && msg.statusCode) {
    handleApiResponse(msg.topic, msg.statusCode, msg.payload);
}

var result = {};

if (msg.statusCode == 200) {
    result.tempext = msg.payload.main.temp;
    result.humidityext = msg.payload.main.humidity;
    result.clouds = msg.payload.clouds.all;
    result.windSpeed = msg.payload.wind.speed;
    result.dateValue = Date.now();
    result.date = getDateString();
    result.longitude = msg.payload.coord.lon;
    result.latitude = msg.payload.coord.lat;

    global.set("meteo", result);
} else {
    result.error = "Erreur dans la récupération des données météo : " + msg.statusCode;
    node.warn(result.error);
}

function getDateString() {
    let now = new Date();

    // Formater la date et l'heure au format "YYYY-MM-DD HH:mm:ss"
    let year = now.getFullYear();
    let month = String(now.getMonth() + 1).padStart(2, '0'); // Les mois commencent à 0
    let day = String(now.getDate()).padStart(2, '0');
    let hours = String(now.getHours()).padStart(2, '0');
    let minutes = String(now.getMinutes()).padStart(2, '0');
    let seconds = String(now.getSeconds()).padStart(2, '0');

    // Concaténer les parties pour obtenir le format final
    let date = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;

    // Retourner le résultat
    return date;
}

return result;

// --- Partie principale avec normalisation numérique + SLC_E + lastReceive éclairage ---

let zones = global.get("zones") || [];
let materiels = global.get("materiels") || [];
let gestionEclairage = global.get("gestionEclairage") || {};
let messageLora = msg.object; // ancienne FW (déjà décodée)
let nbMaxSaveDataRead = global.get("nbMaxSaveDataRead");
let newObject = [];
let keyZones = -1;
let nameSwitch = "";

// Helper pour forcer les états / valeurs en Number quand c'est possible
function toNumericState(val) {
    if (val === undefined || val === null) return val;
    if (typeof val === "number") return val;

    // Booléens
    if (val === true || val === "true") return 1;
    if (val === false || val === "false") return 0;

    // Chaînes ON/OFF
    if (val === "ON" || val === "on") return 1;
    if (val === "OFF" || val === "off") return 0;

    // Chaînes numériques
    if (typeof val === "string") {
        const n = Number(val.trim());
        if (!Number.isNaN(n)) return n;
    }

    return val;
}

function ensureLastReceive(m) {
    if (!m.lastReceive) {
        m.lastReceive = {
            "timestampLastReceive": 0,
            "dateLastReceive": "1970-01-01 00:00:00",
            "pilotageTorLastReceive": 0
        };
    }
}

function ensureEclairage(m) {
    if (!m.eclairage) m.eclairage = {};
    if (!m.eclairage.lastReceive) {
        m.eclairage.lastReceive = {
            "timestampLastReceive": 0,
            "dateLastReceive": "1970-01-01 00:00:00",
            "statutValue": null,
            "lastPayload": "",
            "lastUpdate": ""
        };
    }
}

function updateZoneTor(keyZones, etat) {
    if (keyZones === -1) return;
    if (!zones[keyZones] || !zones[keyZones].data) return;

    // statusAllumage
    if (zones[keyZones].data.statusAllumage) {
        zones[keyZones].data.statusAllumage.value = toNumericState(etat);
        zones[keyZones].data.statusAllumage.timestamp = Date.now();
        zones[keyZones].data.statusAllumage.date = getDateString();
    }

    // statusConsigne
    if (zones[keyZones].data.statusConsigne) {
        zones[keyZones].data.statusConsigne.value = toNumericState(zones[keyZones].data.consigneTorZone);
        zones[keyZones].data.statusConsigne.timestamp = Date.now();
        zones[keyZones].data.statusConsigne.date = getDateString();
    }
}

function findKeyZoneByNumero(numero) {
    let kz = -1;
    for (let y = 0; y < zones.length; y++) {
        if (zones[y].numero == numero) kz = y;
    }
    return kz;
}

// =====================================================
// =============== ANCIENNE VERSION FW =================
// =====================================================
if (typeof messageLora !== "undefined") {

    for (let x = 0; x < materiels.length; x++) {
        if (materiels[x].deveui.toLowerCase() === messageLora.devEUI.toLowerCase()) {

            // --- Boutons
            if (materiels[x].type == "SB_CH") {
                if (messageLora.button == 1) global.set("actionMaintenance", 1);
                else if (messageLora.button == 2) global.set("actionMaintenance", 0);
            }
            else if (materiels[x].type == "SB_E") {
                if (messageLora.button == 1) {
                    global.set("gestionEclairage", {
                        "deactivateGestionEclairage": 1,
                        "lastDeactivateEclairageDate": getDateString(),
                        "lastDeactivateEclairageTimestamp": Date.now()
                    });
                }
                else if (messageLora.button == 2) {
                    global.set("gestionEclairage", {
                        "deactivateGestionEclairage": 0,
                        "lastDeactivateEclairageDate": gestionEclairage.lastDeactivateEclairageDate,
                        "lastDeactivateEclairageTimestamp": gestionEclairage.lastDeactivateEclairageTimestamp
                    });
                }
            }
            else {

                // zone
                keyZones = findKeyZoneByNumero(materiels[x].numero);

                // --- SLC (historique)
                if (keyZones != -1 && materiels[x].type == "SLC") {
                    nameSwitch = "switch_" + materiels[x].sortie;
                    updateZoneTor(keyZones, messageLora[nameSwitch]);
                }

