function getDateString() {
    let now = new Date();
    let year = now.getFullYear();
    let month = String(now.getMonth() + 1).padStart(2, '0');
    let day = String(now.getDate()).padStart(2, '0');
    let hours = String(now.getHours()).padStart(2, '0');
    let minutes = String(now.getMinutes()).padStart(2, '0');
    let seconds = String(now.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

function decodeTHX(bytes) {
    var decoded = {};
    for (var i = 0; i < bytes.length;) {
        var channel_id = bytes[i++];

        // BATTERY
        if (channel_id === 0x81) {
            i += 2;
            decoded.battery = readUInt16LETHX(bytes.slice(i, i + 2)) / 1000;
            i += 2;
        }
        else if (channel_id === 0xA0) {

        }
        // TEMPERATURE
        else if (channel_id === 0x08) {
            // ℃
            var valuetemp = readUInt16LETHX(bytes.slice(i, i + 2)) / 100;
            if (valuetemp > 600) {
                valuetemp = (valuetemp * 100 - 65535) / 100;
            }
            decoded.temperature = valuetemp
            i += 2;
        }
        // HUMIDITY
        else if (channel_id === 0x09) {
            var valuehumid = readUInt16LETHX(bytes.slice(i, i + 2)) / 100;
            if (valuehumid > 600) {
                valuehumid = (valuehumid * 100 - 65535) / 100;
            }
            decoded.humidity = valuehumid
            i += 2;
        }
        else {
            break;
        }
    }
    return decoded;
}

function decodeSLC(bytes) {
    var decoded = {};
    for (var i = 0; i < bytes.length;) {
        var channel_id = bytes[i++];
        var channel_type = bytes[i++];
        // VOLTAGE
        if (channel_id === 0x03 && channel_type === 0x74) {
            decoded.voltage = readUInt16LE(bytes.slice(i, i + 2)) / 10;
            i += 2;
        }
        // ACTIVE POWER
        else if (channel_id === 0x04 && channel_type === 0x80) {
            decoded.active_power = readUInt32LE(bytes.slice(i, i + 4));
            i += 4;
        }
        // POWER FACTOR
        else if (channel_id === 0x05 && channel_type === 0x81) {
            decoded.power_factor = bytes[i] / 100;
            i += 1;
        }
        // POWER CONSUMPTION
        else if (channel_id === 0x06 && channel_type === 0x83) {
            decoded.power_consumption = readUInt32LE(bytes.slice(i, i + 4));
            i += 4;
        }
        // TOTAL CURRENT
        else if (channel_id === 0x07 && channel_type === 0xC9) {
            decoded.current = readUInt16LE(bytes.slice(i, i + 2));
            i += 2;
        }
        // SWITCH STATUS
        else if (channel_id === 0x08 && channel_type === 0x31) {
            var switchFlags = bytes[i + 1];

            for (var idx = 0; idx < 8; idx++) {
                var switchTag = "switch_" + (idx + 1);
                decoded[switchTag] = (switchFlags >> idx) & 1;
            }

            i += 2;
        } else {
            break;
        }
    }
    return decoded;
}

function decodeWS202(bytes) {
    var decoded = {};
    for (var i = 0; i < bytes.length;) {
        var channel_id = bytes[i++];
        var channel_type = bytes[i++];
        // BATTERY
        if (channel_id === 0x01 && channel_type === 0x75) {
            decoded.battery = bytes[i];
            i += 1;
        }
        // PIR (0: Not Triggered, 1: Trigger)
        else if (channel_id === 0x03 && channel_type === 0x00) {
            decoded.pir_trigger = bytes[i];
            i += 1;
        }
        // LIGHT STATUS (0: Light State, 1: Dark State)
        else if (channel_id === 0x04 && channel_type === 0x00) {
            decoded.light_status = bytes[i];
            i += 1;
        } else {
            break;
        }
    }
    return decoded;
}

function decodeWT101(bytes) {
    var decoded = {};

    for (var i = 0; i < bytes.length;) {
        var channel_id = bytes[i++];
        var channel_type = bytes[i++];
        // BATTERY
        if (channel_id === 0x01 && channel_type === 0x75) {
            decoded.battery = bytes[i];
            i += 1;
        }
        // TEMPERATURE
        else if (channel_id === 0x03 && channel_type === 0x67) {
            decoded.temperature = readInt16LE(bytes.slice(i, i + 2)) / 10;
            i += 2;
        }
        // TEMPERATURE TARGET
        else if (channel_id === 0x04 && channel_type === 0x67) {
            decoded.temperature_target = readInt16LE(bytes.slice(i, i + 2)) / 10;
            i += 2;
        }
        // VALVE OPENING
        else if (channel_id === 0x05 && channel_type === 0x92) {
            decoded.valve_opening = readUInt8(bytes[i]);
            i += 1;
        }
        // INSTALLATION STATUS
        else if (channel_id === 0x06 && channel_type === 0x00) {
            decoded.tamper_status = bytes[i] === 0 ? "installed" : "uninstalled";
            i += 1;
        }
        // FEENSTRATION STATUS
        else if (channel_id === 0x07 && channel_type === 0x00) {
            decoded.window_detection = bytes[i] === 0 ? "normal" : "open";
            i += 1;
        }
        // MOTOR STORKE CALIBRATION STATUS
        else if (channel_id === 0x08 && channel_type === 0xe5) {
            decoded.motor_calibration_result = readMotorCalibration(bytes[i]);
            i += 1;
        }
        // MOTOR STROKE
        else if (channel_id === 0x09 && channel_type === 0x90) {
            decoded.motor_storke = readUInt16LE(bytes.slice(i, i + 2));
            i += 2;
        }
        // FROST PROTECTION
        else if (channel_id === 0x0a && channel_type === 0x00) {
            decoded.freeze_protection = bytes[i] === 0 ? "normal" : "triggered";
            i += 1;
        }
        // MOTOR CURRENT POSTION
        else if (channel_id === 0x0b && channel_type === 0x90) {
            decoded.motor_position = readUInt16LE(bytes.slice(i, i + 2));
            i += 2;
        } else {
            break;
        }
    }
    return decoded;
}

function readMotorCalibration(type) {
    switch (type) {
        case 0x00:
            return "success";
        case 0x01:
            return "fail: out of range";
        case 0x02:
            return "fail: uninstalled";
        case 0x03:
            return "calibration cleared";
        case 0x04:
            return "temperature control disabled";
        default:
            return "unknown";
    }
}

function decodeWS101(bytes) {
    var decoded = {};
    for (var i = 0; i < bytes.length;) {
        var channel_id = bytes[i++];
        var channel_type = bytes[i++];
        // BATTERY
        if (channel_id === 0x01 && channel_type === 0x75) {
            decoded.battery = bytes[i];
            i += 1;
        }
        // BUTTON PRESS STATE
        else if (channel_id === 0xff && channel_type === 0x2e) {
            var msg_id = getRandomIntInclusive(100000, 999999);
            decoded.button = bytes[i];
            switch (decoded.button) {
                case 1:
                    decoded.button_single_msgid = msg_id;
                    break;
                case 2:
                    decoded.button_long_msgid = msg_id;
                    break;
                case 3:
                    decoded.button_double_msgid = msg_id;
                    break;
            }
            i += 1;
        } else {
            break;
        }
    }
    return decoded;
}

function getRandomIntInclusive(min, max) {
    min = Math.ceil(min);
    max = Math.floor(max);
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function decodeMCLIMATE_FCT(bytes) {
    var decoded = {};

    if (bytes[0] == 1) {
        decoded = handleKeepaliveMCLIMATE_FCT(bytes, decoded);
    } else {
        decoded = handleResponseMCLIMATE_FCT(bytes, decoded);
        bytes = bytes.slice(-11);
        decoded = handleKeepaliveMCLIMATE_FCT(bytes, decoded);
    }
    return decoded;
}

function toBool(value) {
    if (value == '1') {
        return true;
    }
    else {
        return false;
    }
}
function calculateTemperature(rawData) { return (rawData - 400) / 10 };
function calculateHumidity(rawData) { return (rawData * 100) / 256 };
function decbin(number) {
    if (number < 0) {
        number = 0xFFFFFFFF + number + 1
    }
    number = number.toString(2);
    return "00000000".substr(number.length) + number;
}

function handleKeepaliveMCLIMATE_FCT(bytes, data) {

    var decbin1Res = decbin(bytes[1]);
    var decbin2Res = decbin(bytes[2]);
    var tempDec = parseInt("" + decbin1Res + "" + decbin2Res, 2);
    var temperatureValue = calculateTemperature(tempDec);
    var humidityValue = calculateHumidity(bytes[3]);
    var decbin4Res = decbin(bytes[4]);
    var decbin5Res = decbin(bytes[5]);
    var targetTemperature = parseInt("" + decbin4Res + "" + decbin5Res, 2) / 10;
    var operationalMode = bytes[6];
    var displayedFanSpeed = bytes[7];
    var actualFanSpeed = bytes[8];
    var valveStatus = bytes[9];
    var deviceStatus = bytes[10];

    data.sensorTemperature = Number(temperatureValue.toFixed(2));
    data.relativeHumidity = Number(humidityValue.toFixed(2));
    data.targetTemperature = targetTemperature;
    data.operationalMode = operationalMode;
    data.displayedFanSpeed = displayedFanSpeed;
    data.actualFanSpeed = actualFanSpeed;
    data.valveStatus = valveStatus;
    data.deviceStatus = deviceStatus;
    return data;
}

function handleResponseMCLIMATE_FCT(bytes, data) {
    var commands = bytes.map(function (byte) {
        return ("0" + byte.toString(16)).substr(-2);
    });
    commands = commands.slice(0, -11);
    var command_len = 0;

    //commands.map(function (command, i) {
    for (var i = 0; i < +commands.length; i++) {
        if (commands == '04') {
            command_len = 2;
            var hardwareVersion = commands[i + 1];
            var softwareVersion = commands[i + 2];
            data.deviceVersions = { hardware: Number(hardwareVersion), software: Number(softwareVersion) };
        }
        else if (commands == '05') {
            command_len = 1;
            data.targetTemperatureStep = parseInt(commands[i + 1], 16) / 10;
        }
        else if (commands == '12') {
            command_len = 1;
            data.keepAliveTime = parseInt(commands[i + 1], 16);
        }
        else if (commands == '14') {
            command_len = 1;
            data.keysLock = toBool(parseInt(commands[i + 1], 16));
        }
        else if (commands == '15') {
            command_len = 2;
            data.temperatureRangeSettings = { min: parseInt(commands[i + 1], 16), max: parseInt(commands[i + 2], 16) };
        }
        else if (commands == '19') {
            command_len = 1;
            var commandResponse = parseInt(commands[i + 1], 16);
            var periodInMinutes = commandResponse * 5 / 60;
            data.joinRetryPeriod = periodInMinutes;
        }
        else if (commands == '1b') {
            command_len = 1;
            data.uplinkType = parseInt(commands[i + 1], 16);
        }
        else if (commands == '1d') {
            command_len = 2;
            var deviceKeepAlive = 5;
            var wdpC = commands[i + 1] == '00' ? false : commands[i + 1] * deviceKeepAlive + 7;
            var wdpUc = commands[i + 2] == '00' ? false : parseInt(commands[i + 2], 16);
            data.watchDogParams = { wdpC: wdpC, wdpUc: wdpUc };
        }
        else if (commands == '2f') {
            command_len = 1;
