        }
        else if (commands == '5b') {
            command_len = 2;
            data.tempSensorCompensation = { compensation: parseInt(commands[i + 1], 16), temperature: parseInt(commands[i + 2], 16) };
        }
        else if (commands == '5d') {
            command_len = 1;
            data.fanSpeedNotOccupied = parseInt(commands[i + 1], 16);
        }
        else if (commands == '5f') {
