            data.occFunction = parseInt(commands[i + 1], 16);
        }
        else if (commands == '65') {
            command_len = 2;
            data.automaticChangeoverThreshold = { coolingThreshold: parseInt(commands[i + 1], 16), heatingThreshold: parseInt(commands[i + 2], 16) };
        }
        else if (commands == '69') {
            command_len = 1;
            data.returnOfPowerOperation = parseInt(commands[i + 1], 16);
        }
        else if (commands == '6b') {
            command_len = 1;
            data.deltaTemperature1 = parseInt(commands[i + 1], 16) / 10;
        }
        else if (commands == '6d') {
            command_len = 2;
            data.deltaTemperature2and3 = { deltaTemperature2: parseInt(commands[i + 1], 16) / 10, deltaTemperature3: parseInt(commands[i + 2], 16) / 10 };
        }
        else if (commands == '6e') {
            command_len = 1;
            data.frostProtectionStatus = parseInt(commands[i + 1], 16);
        }
        else if (commands == '70') {
            command_len = 1;
            data.occupancySensorStatusSetPoint = parseInt(commands[i + 1], 16);
        }
        else if (commands == '71') {
            command_len = 1;
            data.occupancySensorStatus = parseInt(commands[i + 1], 16);
        }
        else if (commands == '72') {
            command_len = 1;
            data.dewPointSensorStatus = parseInt(commands[i + 1], 16);
        }
        else if (commands == '73') {
            command_len = 1;
            data.filterAlarm = parseInt(commands[i + 1], 16);
        }
        else if (commands == 'a0') {
            command_len = 4;
            var commandsVal1 = commands[i + 1];
            var commandsVal2 = commands[i + 2];
            var commandsVal3 = commands[i + 3];
            var commandsVal4 = commands[i + 4];
            var fuota_address = parseInt("" + commandsVal1 + commandsVal2 + commandsVal3 + commandsVal4 + "", 16);
            var fuota_address_raw = "" + commandsVal1 + commandsVal2 + commandsVal3 + commandsVal4 + "";
            data.fuota = { fuotaAddr: fuota_address, fuotaAddrRaw: fuota_address_raw };
        }
        i = i + command_len;
    }
    return data;
}

function Decode(port, bytes) {
    var decoded = decodeMCLIMATE_16A(bytes);
    return decoded;
}

function decodeMCLIMATE_16A(bytes) {
    var decoded = {};

    // Determine device type based on message length
    var deviceType = (bytes.length < 8 ) ? '16ADS' : '16ASPM';
    decoded.deviceType = deviceType;

    if (bytes[0] == 1) {
        decoded = handleKeepalive(bytes, decoded, deviceType);
    } 
    else {
        decoded = handleResponse(bytes, decoded);
        // Slice appropriate number of bytes based on device type
        bytes = deviceType === '16ADS' ? bytes.slice(-3) : bytes.slice(-11);
        decoded = handleKeepalive(bytes, decoded, deviceType);
    }
    return decoded;
}

function handleKeepalive(bytes, data, deviceType) {
    if (deviceType === '16ADS') {
        // 16ADS keepalive handling
        var isNegative = (bytes[1] & 0x80) !== 0;
        var temperature = bytes[1] & 0x7F;
        data.internalTemperature = isNegative ? -temperature : temperature;
        data.relayState = bytes[2] === 0x01 ? "ON" : "OFF";
    } else {
        // 16ASPM keepalive handling
        data.internalTemperature = bytes[1];

        // Energy data
        var energy = (bytes[2] << 24) | (bytes[3] << 16) | (bytes[4] << 8) | bytes[5];
        data.energy_kWh = energy / 1000;

        // Power data
        var power = (bytes[6] << 8) | bytes[7];
        data.power_W = power;

        // AC voltage
        data.acVoltage_V = bytes[8];

        // AC current data
        var acCurrent = (bytes[9] << 8) | bytes[10];
        data.acCurrent_mA = acCurrent;

        // Relay state
        data.relayState = bytes[11] === 0x01 ? "ON" : "OFF";
    }
    return data;
}

function handleResponse(bytes, data, deviceType) {
    var commands = bytes.map(function (byte) {
        return ("0" + byte.toString(16)).substr(-2);
    });
    var commandsLength = commands.length;
    commands = commands.slice(0, commandsLength - (deviceType === '16ADS' ? 3 : 12));
    var command_len = 0;

    commands.forEach(function (command, i) {
        switch (command) {
            case '04':
                command_len = 2;
                var hardwareVersion = commands[i + 1];
                var softwareVersion = commands[i + 2];
                data.deviceVersions = {
                    hardware: Number(hardwareVersion),
                    software: Number(softwareVersion)
                };
                break;
            case '12':
                command_len = 1;
                data.keepAliveTime = parseInt(commands[i + 1], 16);
                break;
            case '19':
                command_len = 1;
                var commandResponse = parseInt(commands[i + 1], 16);
                var periodInMinutes = (commandResponse * 5) / 60;
                data.joinRetryPeriod = periodInMinutes;
                break;
            case '1b':
                command_len = 1;
                data.uplinkType = parseInt(commands[i + 1], 16);
                break;
            case '1d':
                command_len = 2;
                var wdpC = commands[i + 1] === '00' ? false : parseInt(commands[i + 1], 16);
                var wdpUc = commands[i + 2] === '00' ? false : parseInt(commands[i + 2], 16);
                data.watchDogParams = { wdpC: wdpC, wdpUc: wdpUc };
                break;
            case '1f':
                command_len = 2;
                data.overheatingThresholds = {
                    trigger: parseInt(commands[i + 1], 16),
                    recovery: parseInt(commands[i + 2], 16)
                };
                break;
            case '21':
                command_len = 3;
                data.overvoltageThreshold = {
                    trigger: (parseInt(commands[i + 1], 16) << 8) | parseInt(commands[i + 2], 16),
                    recovery: parseInt(commands[i + 3], 16)
                };
                break;
            case '23':
                command_len = 1;
                data.overcurrentThreshold = parseInt(commands[i + 1], 16);
                break;
            case '25':
                command_len = 2;
                data.overpowerThreshold = (parseInt(commands[i + 1], 16) << 8) | parseInt(commands[i + 2], 16);
                break;
            case '5a':
                command_len = 1;
                data.afterOverheatingProtectionRecovery = parseInt(commands[i + 1], 16);
                break;
            case '5c':
                command_len = 1;
                data.ledIndicationMode = parseInt(commands[i + 1], 16);
                break;
            case '5d':
                command_len = 1;
                data.manualChangeRelayState = parseInt(commands[i + 1], 16) === 0x01;
                break;
            case '5f':
                command_len = 1;
                data.relayRecoveryState = parseInt(commands[i + 1], 16);
                break;
            case '60':
                command_len = 2;
                data.overheatingEvents = {
                    events: parseInt(commands[i + 1], 16),
                    temperature: parseInt(commands[i + 2], 16)
                };
                break;
            case '61':
                command_len = 3;
                data.overvoltageEvents = {
                    events: parseInt(commands[i + 1], 16),
                    voltage: (parseInt(commands[i + 2], 16) << 8) | parseInt(commands[i + 3], 16)
                };
                break;
            case '62':
                command_len = 3;
                data.overcurrentEvents = {
                    events: parseInt(commands[i + 1], 16),
                    current: (parseInt(commands[i + 2], 16) << 8) | parseInt(commands[i + 3], 16)
                };
                break;
            case '63':
                command_len = 3;
                data.overpowerEvents = {
                    events: parseInt(commands[i + 1], 16),
                    power: (parseInt(commands[i + 2], 16) << 8) | parseInt(commands[i + 3], 16)
                };
                break;
            case '70':
                command_len = 2;
                data.overheatingRecoveryTime = (parseInt(commands[i + 1], 16) << 8) | parseInt(commands[i + 2], 16);
                break;
            case '71':
                command_len = 2;
                data.overvoltageRecoveryTime = (parseInt(commands[i + 1], 16) << 8) | parseInt(commands[i + 2], 16);
                break;
            case '72':
                command_len = 1;
                data.overcurrentRecoveryTemp = parseInt(commands[i + 1], 16);
                break;
            case '73':
                command_len = 1;
                data.overpowerRecoveryTemp = parseInt(commands[i + 1], 16);
                break;
            case 'b1':
                command_len = 1;
                data.relayState = parseInt(commands[i + 1], 16) === 0x01 ? "ON" : "OFF";
                break;
            case 'a0':
                command_len = 4;
                var fuota_address = parseInt(commands[i + 1] + commands[i + 2] + commands[i + 3] + commands[i + 4], 16);
                var fuota_address_raw = commands[i + 1] + commands[i + 2] + commands[i + 3] + commands[i + 4];
                data.fuota = {
                    fuota_address: fuota_address,
                    fuota_address_raw: fuota_address_raw
                };
                break;
            case 'a4':
                command_len = 1;
                data.region = parseInt(commands[i + 1], 16);
                break;
            default:
                break;
        }
        if (command_len > 0) {
            commands.splice(i + 1, command_len);
        }
    });

    return data;
}

function decodeUC300(bytes) {
    var decoded = {};
    var gpio_in_chns = [0x03, 0x04, 0x05, 0x06];
    var gpio_out_chns = [0x07, 0x08];
    var pt100_chns = [0x09, 0x0a];
    var ai_chns = [0x0b, 0x0c];
    var av_chns = [0x0d, 0x0e];

    for (var i = 0; i < bytes.length;) {
        var channel_id = bytes[i++];
        var channel_type = bytes[i++];
        // PROTOCOL VESION
        if (channel_id === 0xff && channel_type === 0x01) {
            decoded.protocol_version = bytes[i];
            i += 1;
        }
        // POWER ON
        else if (channel_id === 0xff && channel_type === 0x0b) {
            decoded.power = "on";
            i += 1;
        }
        // SERIAL NUMBER
        else if (channel_id === 0xff && channel_type === 0x16) {
            decoded.sn = readString(bytes.slice(i, i + 8));
            i += 8;
        }
        // HARDWARE VERSION
        else if (channel_id === 0xff && channel_type === 0x09) {
            decoded.hardware_version = readHardwareVersion(bytes.slice(i, i + 2));
            i += 2;
        }
        // FIRMWARE VERSION
        else if (channel_id === 0xff && channel_type === 0x0a) {
            decoded.firmware_version = readFirmwareVersion(bytes.slice(i, i + 2));
            i += 2;
        }
        // GPIO INPUT
        else if (includes(gpio_in_chns, channel_id) && channel_type === 0x00) {
            var id = channel_id - gpio_in_chns[0] + 1;
            var gpio_in_name = "gpio_in_" + id;
            decoded[gpio_in_name] = bytes[i] === 0 ? "off" : "on";
            i += 1;
        }
        // GPIO OUTPUT
        else if (includes(gpio_out_chns, channel_id) && channel_type === 0x01) {
            var id = channel_id - gpio_out_chns[0] + 1;
            var gpio_out_name = "gpio_out_" + id;
            decoded[gpio_out_name] = bytes[i] === 0 ? "off" : "on";
            i += 1;
        }
        // GPIO AS COUNTER
        else if (includes(gpio_in_chns, channel_id) && channel_type === 0xc8) {
            var id = channel_id - gpio_in_chns[0] + 1;
            var counter_name = "counter_" + id;
            decoded[counter_name] = readUInt32LE(bytes.slice(i, i + 4));
            i += 4;
        }
        // PT100
        else if (includes(pt100_chns, channel_id) && channel_type === 0x67) {
            var id = channel_id - pt100_chns[0] + 1;
            var pt100_name = "pt100_" + id;
            decoded[pt100_name] = readInt16LE(bytes.slice(i, i + 2)) / 10;
            i += 2;
        }
        // ADC CHANNEL
        else if (includes(ai_chns, channel_id) && channel_type === 0x02) {
            var id = channel_id - ai_chns[0] + 1;
            var adc_name = "adc_" + id;
            decoded[adc_name] = readUInt32LE(bytes.slice(i, i + 4)) / 100;
            i += 4;
            continue;
        }
        // ADC CHANNEL FOR VOLTAGE
        else if (includes(av_chns, channel_id) && channel_type === 0x02) {
            var id = channel_id - av_chns[0] + 1;
            var adv_name = "adv_" + id;
            decoded[adv_name] = readUInt32LE(bytes.slice(i, i + 4)) / 100;
            i += 4;
            continue;
        }
        // MODBUS
        else if (channel_id === 0xff && channel_type === 0x19) {
            var modbus_chn_id = bytes[i++] + 1;
            var data_length = bytes[i++];
            var data_type = bytes[i++];
            var sign = (data_type >>> 7) & 0x01;
            var type = data_type & 0x7f; // 0b01111111
            var chn = "modbus_chn_" + modbus_chn_id;
            switch (type) {
                case 0:
                    decoded[chn] = bytes[i] ? "on" : "off";
                    i += 1;
                    break;
                case 1:
                    decoded[chn] = sign ? readInt8(bytes.slice(i, i + 1)) : readUInt8(bytes.slice(i, i + 1));
                    i += 1;
                    break;
                case 2:
                case 3:
                    decoded[chn] = sign ? readInt16LE(bytes.slice(i, i + 2)) : readUInt16LE(bytes.slice(i, i + 2));
                    i += 2;
                    break;
                case 4:
                case 6:
                    decoded[chn] = sign ? readInt32LE(bytes.slice(i, i + 4)) : readUInt32LE(bytes.slice(i, i + 4));
                    i += 4;
                    break;
                case 8:
                case 10:
                    decoded[chn] = sign ? readInt16LE(bytes.slice(i, i + 2)) : readUInt16LE(bytes.slice(i, i + 2));
                    i += 4;
                    break;
                case 9:
                case 11:
                    decoded[chn] = sign ? readInt16LE(bytes.slice(i + 2, i + 4)) : readUInt16LE(bytes.slice(i + 2, i + 4));
                    i += 4;
                    break;
                case 5:
                case 7:
                    decoded[chn] = readFloatLE(bytes.slice(i, i + 4));
                    i += 4;
                    break;
            }
        }
        // MODBUS READ ERROR
        else if (channel_id === 0xff && channel_type === 0x15) {
            var modbus_chn_id = bytes[i] + 1;
            var channel_name = "modbus_chn_" + modbus_chn_id + "_alert";
            decoded[channel_name] = "read error";
            i += 1;
        }
        // ANALOG INPUT STATISTICS
        else if (includes(ai_chns, channel_id) && channel_type === 0xe2) {
            var id = channel_id - ai_chns[0] + 1;
            var adc_name = "adc_" + id;
            decoded[adc_name] = readFloat16LE(bytes.slice(i, i + 2));
            decoded[adc_name + "_max"] = readFloat16LE(bytes.slice(i + 2, i + 4));
            decoded[adc_name + "_min"] = readFloat16LE(bytes.slice(i + 4, i + 6));
            decoded[adc_name + "_avg"] = readFloat16LE(bytes.slice(i + 6, i + 8));
            i += 8;
        }
        // ANALOG VOLTAGE STATISTICS
        else if (includes(av_chns, channel_id) && channel_type === 0xe2) {
            var id = channel_id - av_chns[0] + 1;
            var adc_name = "adv_" + id;
            decoded[adc_name] = readFloat16LE(bytes.slice(i, i + 2));
            decoded[adc_name + "_max"] = readFloat16LE(bytes.slice(i + 2, i + 4));
            decoded[adc_name + "_min"] = readFloat16LE(bytes.slice(i + 4, i + 6));
            decoded[adc_name + "_avg"] = readFloat16LE(bytes.slice(i + 6, i + 8));
            i += 8;
        }
        // PT100 ARGS
        else if (includes(pt100_chns, channel_id) && channel_type === 0xe2) {
            var id = channel_id - pt100_chns[0] + 1;
            var pt100_name = "pt100_" + id;
            decoded[pt100_name] = readFloat16LE(bytes.slice(i, i + 2));
            decoded[pt100_name + "_max"] = readFloat16LE(bytes.slice(i + 2, i + 4));
            decoded[pt100_name + "_min"] = readFloat16LE(bytes.slice(i + 4, i + 6));
            decoded[pt100_name + "_avg"] = readFloat16LE(bytes.slice(i + 6, i + 8));
            i += 8;
        }
        // CHANNEL HISTORICAL DATA
        else if (channel_id === 0x20 && channel_type === 0xdc) {
            decoded.channel_history_data = decoded.channel_history_data || [];

            var timestamp = readUInt32LE(bytes.slice(i, i + 4));
            var channel_mask = numToBits(readUInt16LE(bytes.slice(i + 4, i + 6)), 16);
            i += 6;

            var data = { timestamp: timestamp };
            for (var j = 0; j < channel_mask.length; j++) {
                // SKIP UNUSED CHANNELS
                if (channel_mask[j] !== 1) continue;

                // GPIO INPUT
                if (j < 4) {
                    var type_ = bytes[i++];
                    // AS GPIO INPUT
                    if (type_ === 0) {
                        var name = "gpio_in_" + (j + 1);
                        data[name] = readUInt32LE(bytes.slice(i, i + 4)) === 0 ? "off" : "on";
                        i += 4;
                    }
                    // AS COUNTER
                    else {
                        var name = "counter_" + (j + 1);
                        data[name] = readUInt32LE(bytes.slice(i, i + 4));
                        i += 4;
                    }
                }
                // GPIO OUTPUT
                else if (j < 6) {
                    var name = "gpio_out_" + (j - 4 + 1);
                    data[name] = bytes[i] ? "on" : "off";
                    i += 1;
                }
                // PT100
                else if (j < 8) {
                    var name = "pt100_" + (j - 6 + 1);
                    data[name] = readFloat16LE(bytes.slice(i, i + 2));
                    i += 2;
                }
                // ADC
                else if (j < 10) {
                    var name = "adc_" + (j - 8 + 1);
                    data[name] = readFloat16LE(bytes.slice(i, i + 2));
                    data[name + "_max"] = readFloat16LE(bytes.slice(i + 2, i + 4));
                    data[name + "_min"] = readFloat16LE(bytes.slice(i + 4, i + 6));
                    data[name + "_avg"] = readFloat16LE(bytes.slice(i + 6, i + 8));
                    i += 8;
                }
                // ADV
                else if (j < 12) {
                    var name = "adv_" + (j - 10 + 1);
                    data[name] = readFloat16LE(bytes.slice(i, i + 2));
                    data[name + "_max"] = readFloat16LE(bytes.slice(i + 2, i + 4));
                    data[name + "_min"] = readFloat16LE(bytes.slice(i + 4, i + 6));
                    data[name + "_avg"] = readFloat16LE(bytes.slice(i + 6, i + 8));
                    i += 8;
                }
                // CUSTOM MESSAGE
                else if (j < 13) {
                    data.text = readAscii(bytes.slice(i, 48));
                    i += 48;
                }
            }

            decoded.channel_history_data.push(data);
        }
        // MODBUS HISTORICAL DATA
        else if (channel_id === 0x20 && channel_type === 0xdd) {
            decoded.modbus_history_data = decoded.modbus_history_data || [];

            var timestamp = readUInt32LE(bytes.slice(i, i + 4));
            var modbus_chn_mask = numToBits(readUInt32LE(bytes.slice(i + 4, i + 8)), 32);
            i += 8;

            var data = { timestamp: timestamp };
            for (var j = 0; j < modbus_chn_mask.length; j++) {
                if (modbus_chn_mask[j] !== 1) continue;

                var chn = "modbus_chn_" + (j + 1);
                var data_type = bytes[i++];
                var sign = (data_type >>> 7) & 0x01;
                var type = data_type & 0x7f; // 0b01111111
                switch (type) {
                    case 0: // MB_COIL
                        decoded[chn] = bytes[i] ? "on" : "off";
                        break;
                    case 1: // MB_DISCRETE
                        data[chn] = sign ? readInt8(bytes.slice(i, i + 1)) : readUInt8(bytes.slice(i, i + 1));
                        break;
                    case 2: // MB_INPUT_INT16
                    case 3: // MB_HOLDING_INT16
                        data[chn] = sign ? readInt16LE(bytes.slice(i, i + 2)) : readUInt16LE(bytes.slice(i, i + 2));
                        break;
                    case 4: // MB_HOLDING_INT32
                    case 6: // MB_INPUT_INT32
                        data[chn] = sign ? readInt32LE(bytes.slice(i, i + 4)) : readUInt32LE(bytes.slice(i, i + 4));
                        break;
                    case 8: // MB_INPUT_INT32_AB
                    case 10: // MB_HOLDING_INT32_AB
                        data[chn] = sign ? readInt16LE(bytes.slice(i, i + 2)) : readUInt16LE(bytes.slice(i, i + 2));
                        break;
                    case 9: // MB_INPUT_INT32_CD
                    case 11: // MB_HOLDING_INT32_CD
                        data[chn] = sign ? readInt16LE(bytes.slice(i + 2, i + 4)) : readUInt16LE(bytes.slice(i + 2, i + 4));
                        break;
                    case 5: // MB_HOLDING_FLOAT
                    case 7: // MB_INPUT_FLOAT
                        data[chn] = readFloatLE(bytes.slice(i, i + 4));
                        break;
                }
                i += 4;
            }

            decoded.modbus_history_data.push(data);
        }
        // TEXT
        else {
            decoded.text = readAscii(bytes.slice(i - 2, bytes.length));
            i = bytes.length;
        }
    }
    return decoded;
}

/* ******************************************
 * bytes to number
 ********************************************/
function numToBits(num, bit_count) {
    var bits = [];
    for (var i = 0; i < bit_count; i++) {
        bits.push((num >> i) & 1);
    }
    return bits;
}

function readUInt8(bytes) {
    return bytes & 0xff;
}

function readInt8(bytes) {
    var ref = readUInt8(bytes);
    return ref > 0x7f ? ref - 0x100 : ref;
}

function readUInt8LE(bytes) {
    return (bytes & 0xFF);
}

function readInt8LE(bytes) {
    var ref = readUInt8LE(bytes);
    return (ref > 0x7F) ? ref - 0x100 : ref;
}

function readUInt16LE(bytes) {
    var value = (bytes[1] << 8) + bytes[0];
    return (value & 0xFFFF);
}

function readInt16LE(bytes) {
    var ref = readUInt16LE(bytes);
    return (ref > 0x7FFF) ? ref - 0x10000 : ref;
}


function readUInt32LE(bytes) {
    var value = (bytes[3] << 24) + (bytes[2] << 16) + (bytes[1] << 8) + bytes[0];
    return (value & 0xFFFFFFFF);
}

function readInt32LE(bytes) {
    var ref = readUInt32LE(bytes);
    return (ref > 0x7FFFFFFF) ? ref - 0x100000000 : ref;
}


function readUInt16LETHX(bytes) {
    var value = (bytes[0] << 8) + bytes[1];
    return value & 0xffff;
}

function readInt16LETHX(bytes) {
    var ref = readUInt16LETHX(bytes);
    return ref > 0x7fff ? ref - 0x10000 : ref;
}

function readFloatLE(bytes) {
    // JavaScript bitwise operators yield a 32 bits integer, not a float.
    // Assume LSB (least significant byte first).
    var bits = (bytes[3] << 24) | (bytes[2] << 16) | (bytes[1] << 8) | bytes[0];
    var sign = bits >>> 31 === 0 ? 1.0 : -1.0;
    var e = (bits >>> 23) & 0xff;
    var m = e === 0 ? (bits & 0x7fffff) << 1 : (bits & 0x7fffff) | 0x800000;
    var f = sign * m * Math.pow(2, e - 150);

    var n = Number(f.toFixed(2));
    return n;
}

function readFloat16LE(bytes) {
    var bits = (bytes[1] << 8) | bytes[0];
    var sign = bits >>> 15 === 0 ? 1.0 : -1.0;
    var e = (bits >>> 10) & 0x1f;
    var m = e === 0 ? (bits & 0x3ff) << 1 : (bits & 0x3ff) | 0x400;
    var f = sign * m * Math.pow(2, e - 25);

    var n = Number(f.toFixed(2));
    return n;
}

function readAscii(bytes) {
    var str = "";
    for (var i = 0; i < bytes.length; i++) {
        str += String.fromCharCode(bytes[i]);
    }
    return str;
}

function includes(datas, value) {
    var size = datas.length;
    for (var i = 0; i < size; i++) {
        if (datas[i] == value) {
            return true;
        }
    }
    return false;
}

function readHardwareVersion(bytes) {
    var major = bytes[0] & 0xff;
    var minor = (bytes[1] & 0xff) >> 4;
    return "v" + major + "." + minor;
}

function readFirmwareVersion(bytes) {
    var major = bytes[0] & 0xff;
    var minor = bytes[1] & 0xff;
    return "v" + major + "." + minor;
}

// bytes to string
function readString(bytes) {
    var temp = [];
    for (var idx = 0; idx < bytes.length; idx++) {
        temp.push(("0" + (bytes[idx] & 0xff).toString(16)).slice(-2));
    }
    return temp.join("");
}

// Fonction utilitaire : convertit récursivement les strings numériques en nombres
// ⚠️ Sauf pour les champs devEUI / deveui / devEui qui restent des strings quoi qu'il arrive.
function normalizeNumbersDeep(value) {
    // Fonction interne avec le contexte du nom de la propriété parente
    function _normalize(innerValue, parentKey) {

        // Si c'est un tableau, on traite chaque élément
        if (Array.isArray(innerValue)) {
            for (let i = 0; i < innerValue.length; i++) {
                innerValue[i] = _normalize(innerValue[i], parentKey);
            }
            return innerValue;
        }

        // Si c'est un objet, on traite chaque propriété
        if (innerValue !== null && typeof innerValue === "object") {
            for (let key in innerValue) {
                if (Object.prototype.hasOwnProperty.call(innerValue, key)) {
                    innerValue[key] = _normalize(innerValue[key], key);
                }
            }
            return innerValue;
        }

        // Si c'est une string, on teste si elle est numérique
        if (typeof innerValue === "string") {
            const trimmed = innerValue.trim();
            if (trimmed === "") return innerValue; // on laisse les chaînes vides

            // ⛔️ Exceptions : on NE convertit pas les champs devEUI / deveui / devEui
            if (parentKey && parentKey.toLowerCase().includes("deveui")) {
                return innerValue;
            }

            const num = Number(trimmed);
            // Si ce n'est pas un nombre (NaN), on garde la string (ex: IP, etc.)
            if (!Number.isNaN(num)) {
                return num;
            }
        }

        // Tous les autres types sont retournés tels quels
        return innerValue;
    }

    // Appel initial sans clé parente
    return _normalize(value, null);
}


