    shape: "dot",     // forme : "dot" ou "ring"
    text: `VERSION:   ${versionBox}`
});

let actionMaintenance = global.get("actionMaintenance");
if (actionMaintenance === undefined) {
    // Si la variable n'existe pas, on l'initialise
    actionMaintenance = 0;
    global.set("actionMaintenance", actionMaintenance);
}

let gestionEclairage = global.get("gestionEclairage");
if (gestionEclairage === undefined) {
    // Si la variable n'existe pas, on l'initialise
    const initialGestionEclairage = {
        "deactivateGestionEclairage": 0,
        "lastDeactivateEclairageDate": "1970-01-01 00:00:00",
        "lastDeactivateEclairageTimestamp": 0
    };
    global.set("gestionEclairage", initialGestionEclairage);
}

return msg;

let mac = global.get("mac");
let siteId = global.get("siteId");

if (!mac || !siteId) {
    return [null, {
        payload: { status: "error", message: "Paramètres globaux 'mac' ou 'siteId' manquants." },
        statusCode: 400
    }];
}

let topics = ["plannings", "events", "params", "zones", "materiels", "plannings_e"];

// Envoi individuel des messages
topics.forEach(t => {
    node.send([{ topic: t, mac: mac, siteId: siteId }, null]);
});

// Réponse HTTP immédiate
return [null, {
    payload: { status: "success", message: `Injection de ${topics.length} topics lancée.` },
    statusCode: 200
}];

msg.payload = {
    status: "success",
    message: "Injection lancée via API",
    datetime: new Date().toLocaleString() // Format local
};
return msg;

// On s'attend à recevoir un tableau JSON de ce type :
// [
//   {
//     "topic": "lightsControl",
//     "baseUrl": "https://super.api.local/device/",
//     "method": "POST",            // optionnel, défaut POST
//     "body": {"zone":3,"state":"on"}
//   }
// ]

if (!Array.isArray(msg.payload)) {
    msg.statusCode = 400;
    msg.payload = {
        error: "Body must be an array of request objects",
        example: [
            {
                topic: "lightsControl",
                baseUrl: "https://super.api.local/device/",
                method: "POST",
                body: { "zone": 3, "state": "on" }
            }
        ]
    };
    return [null, msg];
}

// OK, on continue
return [msg, null];

// msg.payload = un item du tableau d'entrée
// attendu : {
//   topic: "params",
//   baseUrl: "http://apidata.semlink.io/activity/semautomationapi.php?request=params&gateway=10.1.24.150&siteId=2574",
//   method: "GET",
//   body: {...} // optionnel
// }
//
// NOTE IMPORTANTE :
// On ne touche PLUS à baseUrl.
// On n'ajoute PLUS le topic à la fin.
// On considère baseUrl comme l'URL finale déjà prête à appeler.

const item = msg.payload || {};
const topic = item.topic;
const baseUrl = item.baseUrl;
const body = item.body || {};
const methodRaw = item.method || "POST";
const method = String(methodRaw).toUpperCase();

// meta pour la réponse finale
msg._meta = {
    topic: topic || null,
    finalUrl: baseUrl || null,      // maintenant on expose exactement ce qui a été demandé
    finalMethod: method
};

// Validation minimale
if (!topic || !baseUrl) {
    msg.statusCode = 400;
    msg.payload = {
        error: "Missing 'topic' or 'baseUrl' in request item",
        item: item
    };
    msg.skipHttp = true;
    return msg;
}

// Ici: pas de concat, pas de '/' en plus, pas de rajout de topic.
// C'est baseUrl tel quel.
const finalUrl = baseUrl;

// Prépare le http request
msg.method = method;
msg.url = finalUrl;

// Headers sortants
msg.headers = {
    "Content-Type": "application/json"
    // + "Authorization": global.get("apiTokenGateway") si tu l'as ajouté ailleurs
};

// Payload sortant selon la méthode
if (method === "GET" || method === "HEAD") {
    msg.payload = {};
} else {
    msg.payload = body;
}

// Status visuel pour debug
node.status({
    fill: "blue",
    shape: "dot",
    text: `${method} → ${finalUrl}`
});

return msg;

// Ici on rattrape les erreurs réseau/transport (DNS, timeout, refus...)
// msg contient encore msg._meta qu'on avait préparé dans build_request
// msg.error contient l'erreur Node-RED

const errDetails = msg.error && msg.error.message
    ? msg.error.message
    : (msg.error || "Unknown network error");

msg.statusCode = msg.statusCode || 500;
msg.payload = {
    error: "Request failed",
    details: errDetails,
    topic: msg._meta && msg._meta.topic,
    url: msg._meta && msg._meta.finalUrl,
    methodTried: msg._meta && msg._meta.finalMethod
};

return msg;

// On arrive ici dans deux cas :
// 1. Succès de la requête externe (depuis do_http_request)
//    - msg.payload = réponse de l'API distante (déjà en objet si JSON)
//    - msg.statusCode = code HTTP de l'API distante
//    - msg._meta = { topic, finalUrl, finalMethod }
// 2. Erreur réseau (depuis decorate_error_msg)
//    - msg.payload = { error, details, ... }
//    - msg.statusCode = 500 (par ex)
//    - msg._meta inchangé
// Ici on ne modifie pas le contenu, on fait juste en sorte que tout le monde passe ensuite au formateur final.

return msg;

// On prépare la réponse finale pour cet item individuel.
// Ça partira ensuite dans le join.
//
// msg.payload      = réponse de l'API distante OU objet d'erreur réseau OU erreur locale
// msg.statusCode   = code HTTP vu (200/400/500...)
// msg._meta        = { topic, finalUrl, finalMethod }

let out = {
    topic: msg._meta && msg._meta.topic,
    forwardedUrl: msg._meta && msg._meta.finalUrl,
    forwardedMethod: msg._meta && msg._meta.finalMethod,
    remoteStatus: msg.statusCode || 200,
    remoteResponse: msg.payload
};

msg.payload = out;
return msg;

// On récupère ce qui va être écrit dans le fichier
let newObject = msg.newObject || [];

// Helper générique pour sampler les types d'un enregistrement LoRa
function sampleLoraRecord(rec) {
    if (!rec || typeof rec !== "object") return rec;

    let out = {
        meta: {},
        data_fields: {}
    };

    // Partie "meta" (toujours présente)
    ["deveui", "payload", "timestamp", "date", "fport", "fcnt", "rssi"].forEach(k => {
        if (rec.hasOwnProperty(k)) {
            out.meta[k] = {
                value: rec[k],
                type: typeof rec[k]
            };
        }
    });

    // Partie "data" (cas des anciens firmware / messageLora)
    if (rec.data && typeof rec.data === "object") {
        let keys = Object.keys(rec.data).slice(0, 12); // on limite pour éviter un truc énorme
        keys.forEach(k => {
            out.data_fields[k] = {
                value: rec.data[k],
                type: typeof rec.data[k]
            };
        });
    }

    return out;
}

let resume = {
    nb_records: newObject.length,
    sample: {}
};

// On regarde le premier enregistrement
if (newObject.length > 0) {
    resume.sample.first = sampleLoraRecord(newObject[0]);
}

// Et le dernier (souvent le plus récent)
if (newObject.length > 1) {
    resume.sample.last = sampleLoraRecord(newObject[newObject.length - 1]);
}

// On renvoie ça dans le debug
msg.payload = resume;
return msg;

// Active les traces detaillees du noeud pour une ou plusieurs zones.
const DEBUG_ENABLED = false;
// Filtre d'affichage debug des zones.
// Exemple 1 : filtrage par numero de zone.
const ZONES_DEBUG = {
    by: "numero", // "numero" | "planningId" | "nom" | "index"
    values: [10], // liste des zones a afficher
    regex: null // ex. "Bureau|Salle" si by="nom"
};

/*
// Exemple 2 : filtrage par nom avec regex.
const ZONES_DEBUG = {
    by: "nom",
    values: null,
    regex: "Bureau|Salle"  // tous les noms contenant Bureau ou Salle
};
*/

// Fonction de calcul des pilotages et consignes.
let params = global.get("params") || {};
let meteo = global.get("meteo") || {};
let plannings = global.get("plannings") || [];
let events = global.get("events") || [];
let zones = global.get("zones") || [];

// Convertit les nombres stringifies sans casser les autres types.
function n(val) {
    if (val === null || val === undefined) return val;
    if (typeof val === "number") return val;
    if (typeof val === "string") {
        const num = Number(val.trim());
        if (!Number.isNaN(num)) return num;
    }
    return val;
}

// Contexte temporel courant pour resoudre le planning actif.
let now = new Date();
let currentHour = now.getHours();
let currentMinute = now.getMinutes();
let currentTime = currentHour * 60 + currentMinute;
let dayOfWeek = now.getDay(); // 0 = dimanche, 1 = lundi, ..., 6 = samedi

let indexPlannEteHiver = determinerPeriode(params);

// Parametres numeriques utilises dans les calculs.
const seuilBasModeCLIM = n(params.seuilbasModeCLIM);
const seuilHautModeCLIM = n(params.seuilHautModeCLIM);
const consigneHorsGel = n(params.consigneHorsGel);
const tempNonChauffe = n(params.tempNonChauffe);
const tempNonClim = n(params.tempNonClim);
const hysteresisRegulTOR = n(params.hysteresisRegulTOR);
const hysteresisRegulCLIM = n(params.hysteresisRegulCLIM);
const gestionModeCLIM = n(params.gestionModeCLIM);
const tempext = n(meteo.tempext);

// Resolution complete zone par zone : planning, priorites, consignes et pilotages.
for (let x = 0; x < zones.length; x++) {
    const zone = zones[x];
    let planningZone = null;
    let dataZones = {
        "temp": zone.data.temp,
        "humidity": zone.data.humidity,
        "light": zone.data.light,
        "presence": zone.data.presence,
        "statusAllumage": zone.data.statusAllumage,
        "statusConsigne": zone.data.statusConsigne,
        "statusMode": zone.data.statusMode,
        "pilotageClimZone": zone.data.pilotageClimZone,
        "consigneClimZone": zone.data.consigneClimZone,
        "modeClimZone": zone.data.modeClimZone,
        "pilotageTorZone": zone.data.pilotageTorZone,
        "consigneTorZone": zone.data.consigneTorZone,
        "resolution": {},
        "priorityTrace": []
    };

    // Normalise les mesures et etats issus des objets globaux avant calcul.
    if (dataZones.temp && dataZones.temp.hasOwnProperty("value")) {
        dataZones.temp.value = n(dataZones.temp.value);
    }
    if (dataZones.humidity && dataZones.humidity.hasOwnProperty("value")) {
        dataZones.humidity.value = n(dataZones.humidity.value);
    }
    if (dataZones.light && dataZones.light.hasOwnProperty("value")) {
        dataZones.light.value = n(dataZones.light.value);
    }
    if (dataZones.presence && dataZones.presence.hasOwnProperty("value")) {
        dataZones.presence.value = n(dataZones.presence.value);
        if (dataZones.presence.lastPresenceDetectedTimestamp !== undefined) {
            dataZones.presence.lastPresenceDetectedTimestamp = n(dataZones.presence.lastPresenceDetectedTimestamp);
        }
        if (dataZones.presence.timestamp !== undefined) {
            dataZones.presence.timestamp = n(dataZones.presence.timestamp);
        }
    }
    if (dataZones.statusAllumage && dataZones.statusAllumage.hasOwnProperty("value")) {
        dataZones.statusAllumage.value = n(dataZones.statusAllumage.value);
    }
    if (dataZones.statusConsigne && dataZones.statusConsigne.hasOwnProperty("value")) {
        dataZones.statusConsigne.value = n(dataZones.statusConsigne.value);
    }
    if (dataZones.statusMode && dataZones.statusMode.hasOwnProperty("value")) {
        dataZones.statusMode.value = n(dataZones.statusMode.value);
    }

    dataZones.pilotageClimZone = n(dataZones.pilotageClimZone);
    dataZones.consigneClimZone = n(dataZones.consigneClimZone);
    dataZones.modeClimZone = n(dataZones.modeClimZone);
    dataZones.pilotageTorZone = n(dataZones.pilotageTorZone);
    dataZones.consigneTorZone = n(dataZones.consigneTorZone);

    for (let y = 0; y < plannings.length; y++) {
        if (plannings[y].id == zone.planningId) {
            planningZone = plannings[y];
            break;
        }
    }
    if (!planningZone) {
        planningZone = {};
    }

    const consignesPlanningArray = buildConsignesArray({
        consigneHiverConfort: planningZone.consigneHiverConfort,
        consigneHiverReduit: planningZone.consigneHiverReduit,
        consigneHiverAbsence: planningZone.consigneHiverAbsence,
        consigneEteConfort: planningZone.consigneEteConfort,
        consigneEteReduit: planningZone.consigneEteReduit,
        consigneEteAbsence: planningZone.consigneEteAbsence
    }) || [
        [
            Number(planningZone.consigneHiverConfort),
            Number(planningZone.consigneHiverReduit),
            Number(planningZone.consigneHiverAbsence)
        ],
        [
            Number(planningZone.consigneEteConfort),
            Number(planningZone.consigneEteReduit),
            Number(planningZone.consigneEteAbsence)
        ]
    ];
    const zoneConsignesArray = buildConsignesArray(zone.consignes);

    // Calcule l'etat de base de la piece depuis le planning.
    let dayKeyToday = "day" + dayOfWeek;
    let dayKeyYesterday = (dayOfWeek == 0) ? "day6" : "day" + (dayOfWeek - 1);
    let dayKeyTwoDays = "day6";
    let todaySchedule = planningZone[dayKeyToday];
    let yesterdaySchedule = planningZone[dayKeyYesterday];

    let yesterdayEvents = parseSchedule(yesterdaySchedule, -1);
    let todayEvents = parseSchedule(todaySchedule, 0);

    let planningState = null;
    for (let i = 0; i < todayEvents.length; i++) {
        let currentEvent = todayEvents[i];
        let nextEvent = todayEvents[i + 1] || { time: Infinity, state: currentEvent.state };
        if (currentTime >= currentEvent.time && currentTime < nextEvent.time) {
            planningState = currentEvent.state;
            break;
        }
    }

    if (planningState === null) {
        if (!yesterdayEvents || yesterdayEvents.length === 0) {
            if (dayOfWeek == 0) {
                dayKeyTwoDays = "day5";
            } else if (dayOfWeek == 1) {
                dayKeyTwoDays = "day6";
            } else {
                dayKeyTwoDays = "day" + (dayOfWeek - 2);
            }
            let twoDaysEvents = parseSchedule(planningZone[dayKeyTwoDays], -2);
            if (!twoDaysEvents || twoDaysEvents.length === 0) {
                planningState = 2;
            } else {
                planningState = twoDaysEvents[twoDaysEvents.length - 1].state;
            }
        } else if (yesterdayEvents.length > 0 && "state" in yesterdayEvents[yesterdayEvents.length - 1]) {
            planningState = yesterdayEvents[yesterdayEvents.length - 1].state;
        } else {
            planningState = 2;
        }
    }

    if (planningState > 2) {
        planningState = 2;
        node.warn("Attention erreur dans les valeurs du planning. Le statut de la piece " + zone.numero + " a ete mis a 'Absent'");
    } else if (planningState < 0) {
        planningState = 0;
        node.warn("Attention erreur dans les valeurs du planning. Le statut de la piece " + zone.numero + " a ete mis a 'Confort'");
    }

    // Resolution des priorites : regime EVENT > PLANNING, consigne EVENT > PIECE > PLANNING.
    const zoneId = n(zone.id);
    let activeEvents = events.filter(event =>
        isEventActive(event, now) &&
        (event.zoneId === undefined || event.zoneId === null || n(event.zoneId) === zoneId)
    );
    const activeEvent = activeEvents.length > 0 ? activeEvents[0] : null;
    const eventId = activeEvent && activeEvent.id !== undefined ? activeEvent.id : null;
    const eventName = activeEvent && activeEvent.name !== undefined ? activeEvent.name : null;
    const eventRegime = activeEvent ? normalizeEventRegime(activeEvent.value) : null;
    const eventSeasonIndex = activeEvent ? getSeasonIndexFromPeriodType(activeEvent.periodType) : null;
    const eventSetPoint = activeEvent && activeEvent.temperatureSetPointValue !== undefined &&
        activeEvent.temperatureSetPointValue !== null &&
        activeEvent.temperatureSetPointValue !== ""
        ? n(activeEvent.temperatureSetPointValue)
        : null;
    let forcageArretEvent = activeEvent && n(activeEvent.value) == 4 ? 1 : 0;

    let currentState = planningState;
    let regimeSource = "PLANNING";
    let regimeNote = "planning";
    if (eventRegime !== null) {
        currentState = eventRegime;
        regimeSource = "EVENT";
        regimeNote = "event.value";
    }
    if (currentState === null || currentState === undefined) {
        currentState = 2;
    }
    if (currentState > 2) {
        currentState = 2;
    } else if (currentState < 0) {
        currentState = 0;
    }

    let resolvedSeasonIndex = indexPlannEteHiver;
    let seasonSource = "INITIAL_LOGIC";
    let seasonNote = "No PIECE seasonality defined, fallback to initial logic";
    if (eventSeasonIndex !== null) {
        resolvedSeasonIndex = eventSeasonIndex;
        seasonSource = "EVENT";
        seasonNote = "event.periodType";
    }

    // Calcule le mode clim effectivement applique sur la zone.
    const reportedMode = dataZones.statusMode && dataZones.statusMode.value !== undefined
        ? n(dataZones.statusMode.value)
        : 0;
    // Une saisonnalite forcee par evenement doit imposer le mode correspondant,
    // meme si la gestion automatique du mode est desactivee.
    if (seasonSource === "EVENT" && resolvedSeasonIndex == 1) {
        dataZones.modeClimZone = 1;
    } else if (seasonSource === "EVENT" && resolvedSeasonIndex == 2) {
        dataZones.modeClimZone = 2;
    } else if (gestionModeCLIM == 1) {
        if (dataZones.temp && typeof dataZones.temp.value === "number" && dataZones.temp.value < seuilBasModeCLIM) {
            dataZones.modeClimZone = 1;
        } else if (dataZones.temp && typeof dataZones.temp.value === "number" && dataZones.temp.value > seuilHautModeCLIM) {
            dataZones.modeClimZone = 2;
        } else if (resolvedSeasonIndex == 1) {
            dataZones.modeClimZone = 1;
        } else if (resolvedSeasonIndex == 2) {
            dataZones.modeClimZone = 2;
        } else {
            dataZones.modeClimZone = 0;
        }
    } else {
        dataZones.modeClimZone = reportedMode;
    }
    const effectiveMode = n(dataZones.modeClimZone);

    // Determine les consignes finales a partir de la source retenue.
    let valueModulationConsigne = 0;
    if (
        dataZones.presence &&
        dataZones.presence.timestamp > 0 &&
        dataZones.presence.lastPresenceDetectedTimestamp > 0
    ) {
        if (compareTimestamp(Date.now(), dataZones.presence.timestamp, 1440) === false) {
            if (
                dataZones.presence.value == 0 &&
                currentState == 0 &&
                compareTimestamp(Date.now(), dataZones.presence.lastPresenceDetectedTimestamp, 60) === true
            ) {
                valueModulationConsigne = 1;
                if (params.hasOwnProperty("valueModulationConsigne")) {
                    valueModulationConsigne = Number(params.valueModulationConsigne);
                }
            }
        }
    }

    let selectedConsignesArray = zoneConsignesArray || consignesPlanningArray;
    let consigneSource = zoneConsignesArray ? "PIECE" : "PLANNING";
    let consigneNote = zoneConsignesArray ? "zone.consignes" : "planning";
    let resolvedBaseSetPointTor = null;
    let resolvedBaseSetPointClim = null;
    const winterSetPoints = selectedConsignesArray[0];
    const summerSetPoints = selectedConsignesArray[1];

    if (typeof eventSetPoint === "number" && !isNaN(eventSetPoint)) {
        consigneSource = "EVENT";
        consigneNote = "event.temperatureSetPointValue";
        resolvedBaseSetPointTor = eventSetPoint;
        resolvedBaseSetPointClim = eventSetPoint;
    } else {
        resolvedBaseSetPointTor = winterSetPoints[currentState];

        if (effectiveMode == 1) {
            resolvedBaseSetPointClim = winterSetPoints[currentState];
        } else if (effectiveMode == 2) {
            resolvedBaseSetPointClim = summerSetPoints[currentState];
        } else if (effectiveMode == 0 || effectiveMode == 3) {
            if (resolvedSeasonIndex == 1) {
                resolvedBaseSetPointClim = winterSetPoints[currentState];
            } else if (resolvedSeasonIndex == 2) {
                resolvedBaseSetPointClim = summerSetPoints[currentState];
            } else if (
                dataZones.statusConsigne &&
                dataZones.statusConsigne.value !== undefined &&
                dataZones.statusConsigne.value !== null &&
                dataZones.statusConsigne.value !== ""
            ) {
                resolvedBaseSetPointClim = Number(dataZones.statusConsigne.value);
                consigneSource = "STATUS";
                consigneNote = "statusConsigne.value used in interseason";
            } else {
                resolvedBaseSetPointClim = winterSetPoints[currentState];
            }
        } else {
            resolvedBaseSetPointClim = winterSetPoints[currentState];
        }
    }

    dataZones.consigneTorZone = Number(resolvedBaseSetPointTor) - valueModulationConsigne;
    if (effectiveMode == 2) {
        dataZones.consigneClimZone = Number(resolvedBaseSetPointClim) + valueModulationConsigne;
    } else {
        dataZones.consigneClimZone = Number(resolvedBaseSetPointClim) - valueModulationConsigne;
    }

    // Applique les regles de pilotage finales a partir des valeurs resolues.
    if (forcageArretEvent == 1) {
        dataZones.pilotageTorZone = 0;
        dataZones.pilotageClimZone = 0;
    } else if (n(zone.allumageManuel) == 1) {
        dataZones.pilotageTorZone = dataZones.statusAllumage.value;
        dataZones.pilotageClimZone = dataZones.statusAllumage.value;
    } else if (n(zone.activationRegul) == 1) {
        if (resolvedSeasonIndex == 1) {
            if (tempext > tempNonChauffe && params.activTempNonChauffe == 1) {
                dataZones.pilotageTorZone = 0;
            } else if (dataZones.temp.value < consigneHorsGel) {
                dataZones.pilotageTorZone = 1;
            } else if (n(zone.occupationPermanente) == 0) {
                dataZones.pilotageTorZone = 0;
            } else if (dataZones.temp.value >= (dataZones.consigneTorZone + (hysteresisRegulTOR / 2))) {
                dataZones.pilotageTorZone = 0;
            } else if (dataZones.temp.value <= (dataZones.consigneTorZone - (hysteresisRegulTOR / 2))) {
                dataZones.pilotageTorZone = 1;
            }
        } else {
            dataZones.pilotageTorZone = 0;
        }

        if (resolvedSeasonIndex == 0) {
            dataZones.pilotageClimZone = 0;
        } else if (effectiveMode == 1) {
            if (tempext > tempNonChauffe && params.activTempNonChauffe == 1) {
                dataZones.pilotageClimZone = 0;
            } else if (dataZones.temp.value < consigneHorsGel) {
                dataZones.pilotageClimZone = 1;
            } else if (n(zone.occupationPermanente) == 0) {
                dataZones.pilotageClimZone = 0;
            } else if (dataZones.temp.value >= (dataZones.consigneClimZone + hysteresisRegulCLIM)) {
                dataZones.pilotageClimZone = 0;
            } else if (currentState == 2 && dataZones.temp.value > dataZones.consigneClimZone) {
                dataZones.pilotageClimZone = 0;
            } else {
                dataZones.pilotageClimZone = 1;
            }
        } else if (effectiveMode == 2) {
            if (tempext < tempNonClim && params.activTempNonClim == 1) {
                dataZones.pilotageClimZone = 0;
            } else if (n(zone.occupationPermanente) == 0) {
                dataZones.pilotageClimZone = 0;
            } else if (dataZones.temp.value <= (dataZones.consigneClimZone - hysteresisRegulCLIM)) {
                dataZones.pilotageClimZone = 0;
            } else if (currentState == 2 && dataZones.temp.value < dataZones.consigneClimZone) {
                dataZones.pilotageClimZone = 0;
            } else {
                dataZones.pilotageClimZone = 1;
            }
        } else if (resolvedSeasonIndex == 1) {
            if (tempext > tempNonChauffe && params.activTempNonChauffe == 1) {
                dataZones.pilotageClimZone = 0;
            } else if (dataZones.temp.value < consigneHorsGel) {
                dataZones.pilotageClimZone = 1;
            } else if (n(zone.occupationPermanente) == 0) {
                dataZones.pilotageClimZone = 0;
            } else if (dataZones.temp.value >= (dataZones.consigneClimZone + hysteresisRegulCLIM)) {
                dataZones.pilotageClimZone = 0;
            } else if (currentState == 2 && dataZones.temp.value > dataZones.consigneClimZone) {
                dataZones.pilotageClimZone = 0;
            } else {
                dataZones.pilotageClimZone = 1;
            }
        } else if (resolvedSeasonIndex == 2) {
            if (tempext < tempNonClim && params.activTempNonClim == 1) {
                dataZones.pilotageClimZone = 0;
            } else if (n(zone.occupationPermanente) == 0) {
                dataZones.pilotageClimZone = 0;
            } else if (dataZones.temp.value <= (dataZones.consigneClimZone - hysteresisRegulCLIM)) {
                dataZones.pilotageClimZone = 0;
            } else if (currentState == 2 && dataZones.temp.value < dataZones.consigneClimZone) {
                dataZones.pilotageClimZone = 0;
            } else {
                dataZones.pilotageClimZone = 1;
            }
        } else {
            dataZones.pilotageClimZone = 0;
        }
    } else {
        dataZones.pilotageTorZone = dataZones.statusAllumage.value;
        dataZones.pilotageClimZone = dataZones.statusAllumage.value;
    }

    dataZones.etatAmbiance = currentState;
    dataZones._saisonIndex = resolvedSeasonIndex;
    dataZones.resolution = {
        regime: {
            source: regimeSource,
            value: currentState,
            note: regimeNote,
            eventId: eventId,
            eventName: eventName
        },
        seasonality: {
            source: seasonSource,
            value: resolvedSeasonIndex,
            label: seasonIndexLabel(resolvedSeasonIndex),
            note: seasonNote,
            eventId: eventId,
            eventName: eventName
        },
        consigne: {
            source: consigneSource,
            baseTorValue: resolvedBaseSetPointTor,
            baseClimValue: resolvedBaseSetPointClim,
            appliedTorValue: dataZones.consigneTorZone,
            appliedClimValue: dataZones.consigneClimZone,
            modulation: valueModulationConsigne,
            note: consigneNote,
            eventId: eventId,
            eventName: eventName
        },
        pilotage: {
            source: forcageArretEvent == 1 ? "EVENT_STOP" : "REGULATION",
            forcedOff: forcageArretEvent == 1,
            eventId: eventId,
            eventName: eventName
        }
    };
    dataZones.priorityTrace = [
        resolutionEntry("regime", regimeSource, currentState, {
            note: regimeNote,
            eventId: eventId,
            eventName: eventName
        }),
        resolutionEntry("seasonality", seasonSource, resolvedSeasonIndex, {
            label: seasonIndexLabel(resolvedSeasonIndex),
            note: seasonNote,
            eventId: eventId,
            eventName: eventName
        }),
        resolutionEntry("consigne", consigneSource, {
            baseTorValue: resolvedBaseSetPointTor,
            baseClimValue: resolvedBaseSetPointClim,
            appliedTorValue: dataZones.consigneTorZone,
            appliedClimValue: dataZones.consigneClimZone,
            modulation: valueModulationConsigne
        }, {
            note: consigneNote,
            eventId: eventId,
            eventName: eventName
        }),
        resolutionEntry("pilotage", forcageArretEvent == 1 ? "EVENT_STOP" : "REGULATION", {
            pilotageTorZone: dataZones.pilotageTorZone,
            pilotageClimZone: dataZones.pilotageClimZone,
            forcedOff: forcageArretEvent == 1
        }, {
            eventId: eventId,
            eventName: eventName
        })
    ];
    zone.data = dataZones;
}

// Convertit une chaine de planning "HH:MM (state)" en evenements exploitables.
function parseSchedule(schedule, dayOffset = 0) {
    let events = [];
    if (!schedule || typeof schedule !== "string") {
        return events;
    }

    let parts = schedule.split(";");
    for (let z = 0; z < parts.length; z++) {
        let match = parts[z].trim().match(/(\d{1,2}):(\d{2})\s+\((\d)\)/);
        if (match) {
            let hours = parseInt(match[1], 10);
            let minutes = parseInt(match[2], 10);
            let state = parseInt(match[3], 10);
            let timeInMinutes = hours * 60 + minutes + (dayOffset * 24 * 60);
            events.push({ time: timeInMinutes, state });
        }
    }
    return events;
}

// Retourne true si l'evenement est actif au moment du calcul.
function isEventActive(event, now) {
    let start = new Date(event.startDate);
    let end = new Date(event.endDate);
    return now >= start && now < end;
}

// Teste si deux timestamps sont separes de plus que l'intervalle demande.
function compareTimestamp(timestamp1, timestamp2, intervalle) {
    const differenceInMilliseconds = Math.abs(timestamp1 - timestamp2);
    const intervallInMilliseconds = intervalle * 60 * 1000;
    if (differenceInMilliseconds > intervallInMilliseconds) {
        return true;
    }
    return false;
}

// Determine la saison par defaut quand aucune surcharge n'est definie.
function determinerPeriode(parameters) {
    // Date utilisee pour la comparaison avec les periodes configurees.
    let dateActuelle = new Date();
    let jourActuel = dateActuelle.getDate();
    let moisActuel = dateActuelle.getMonth() + 1;
    let index = 0;

    // Parse les bornes JJ-MM configurees dans params.
    let [jourDebutChauffe, moisDebutChauffe] = parameters.startPeriodChauffe.split('-').map(Number);
    let [jourFinChauffe, moisFinChauffe] = parameters.endPeriodChauffe.split('-').map(Number);
    let [jourDebutClim, moisDebutClim] = parameters.startPeriodClim.split('-').map(Number);
    let [jourFinClim, moisFinClim] = parameters.endPeriodClim.split('-').map(Number);

    // Compare une date jour/mois a une plage qui peut traverser l'annee.
    function estDansPeriode(jourDebut, moisDebut, jourFin, moisFin) {
        if (moisDebut < moisFin) {
            if (moisActuel > moisDebut && moisActuel < moisFin) {
                return true;
            }
            else if (moisActuel === moisDebut && jourActuel >= jourDebut) {
                return true;
            }
            else if (moisActuel === moisFin && jourActuel <= jourFin) {
                return true;
            }
        }
        else if (moisDebut > moisFin) {
            if (moisActuel > moisDebut || moisActuel < moisFin) {
                return true;
            }
            else if (moisActuel === moisDebut && jourActuel >= jourDebut) {
                return true;
            }
            else if (moisActuel === moisFin && jourActuel <= jourFin) {
                return true;
            }
        }
        else if (moisDebut === moisFin) {
            if (moisActuel === moisDebut && jourActuel >= jourDebut && jourActuel <= jourFin) {
                return true;
            }
        }
        return false;
    }

    // Verifie la saison chauffage puis la saison climatisation.
    if (estDansPeriode(jourDebutChauffe, moisDebutChauffe, jourFinChauffe, moisFinChauffe)) {
        index = 1;
    }
    if (estDansPeriode(jourDebutClim, moisDebutClim, jourFinClim, moisFinClim)) {
        index = 2;
    }
    return index;
}

// Convertit la valeur de l'API event vers l'index interne 0/1/2.
function normalizeEventRegime(value) {
    const regime = n(value);
    return (regime >= 1 && regime <= 3) ? regime - 1 : null;
}

// Traduit Winter / Summer vers l'index de saison utilise dans le flow.
function getSeasonIndexFromPeriodType(periodType) {
    if (periodType === null || periodType === undefined || periodType === "") {
        return null;
    }
    const normalized = String(periodType).trim().toLowerCase();
    if (normalized === "winter") {
        return 1;
    }
    if (normalized === "summer") {
        return 2;
    }
    return null;
}

// Libelle de saison utilise dans la trace fonctionnelle et le debug.
function seasonIndexLabel(index) {
    if (index === 1) return "Winter";
    if (index === 2) return "Summer";
    return "Intersaison";
}

// Reconstruit le tableau [hiver, ete] uniquement si les 6 consignes sont exploitables.
function buildConsignesArray(consignesSource) {
    if (!consignesSource || typeof consignesSource !== "object") {
        return null;
    }
    const hiver = [
        n(consignesSource.consigneHiverConfort),
        n(consignesSource.consigneHiverReduit),
        n(consignesSource.consigneHiverAbsence)
    ];
    const ete = [
        n(consignesSource.consigneEteConfort),
        n(consignesSource.consigneEteReduit),
        n(consignesSource.consigneEteAbsence)
    ];
    const allValues = hiver.concat(ete);
    for (let i = 0; i < allValues.length; i++) {
        if (typeof allValues[i] !== "number" || isNaN(allValues[i])) {
            return null;
        }
    }
    return [hiver, ete];
}

// Formate une entree de trace de priorite avec une structure homogene.
function resolutionEntry(target, source, value, extra = {}) {
    return Object.assign({ target, source, value }, extra);
}

