                // On envoie un downlink uniquement si on a dépassé l'intervalle défini
                if (materiels[i].lastSend.pilotageTorLastSend !== pilotageTorZone || compareTimestamp(Date.now(), materiels[i].lastSend.timestampLastSend, intervalRenvoi)) {
                    if (zones[keyZones].data.statusAllumage.value !== pilotageTorZone || compareTimestamp(Date.now(), materiels[i].lastSend.timestampLastSend, intervalRenvoi)) {
                        if (zones[keyZones].occupationPermanente == true || compareTimestamp(Date.now(), materiels[i].lastSend.timestampLastSend, intervalRenvoi)) {
                            let enteteHEX = "07";
                            if (materiels[i].sortie == 2) {
                                enteteHEX = "08";
                            }
                            // Création du message en héxadécimal
                            messageHex = enteteHEX + "0" + pilotageTorZone + "FF";
                            msg.payload = createMessageBase64(messageHex);
                            // Met à jour les infos "lastSend"
                            listChangeMaterielsId.push({
                                "key": i,
                                "data": {
                                    "timestampLastSend": Date.now(),
                                    "dateLastSend": getDateString(),
                                    "modeClimLastSend": "",
                                    "consigneClimLastSend": "",
                                    "pilotageClimLastSend": "",
                                    "consigneTorLastSend": "",
                                    "pilotageTorLastSend": pilotageTorZone,
                                    "downlink": messageHex,
                                    "received": false
                                }
                            });
                            if (actionMaintenance == 0) { // on envoie le message que si le mode maintenance n'est pas activé
                                node.status({ fill: "green", shape: "dot", text: "Pilotage envoyé pour (" + deveui + ") = " + pilotageTorZone });
                                node.send(msg);
                            }
                        }
                    }
                }
            }
        }
    }
}

