function createMessageBase64(hexString) {
    // convertion en base64
    const buffer = Buffer.from(hexString, 'hex'); // Convertir la chaîne hexadécimale en un buffer binaire
    const base64String = buffer.toString('base64'); // Convertir le buffer en Base64

    // Tableau à envoyer en downlink
    const data = {
        "confirmed": false,
        "fPort": 85,
        "data": base64String
    };
    return data;
}

function compareTimestamp(timestamp1, timestamp2, intervalle) {
    const differenceInMilliseconds = Math.abs(timestamp1 - timestamp2); // Différence en millisecondes
    const intervallInMilliseconds = intervalle * 60 * 1000; // intervalle en millisecondes
    if (differenceInMilliseconds > intervallInMilliseconds) {
        return true;
    }
    return false;
}

function getDateString() {
    let now = new Date();

    // Formater la date et l'heure au format "YYYY-MM-DD HH:mm:ss"
    let year = now.getFullYear();
    let month = String(now.getMonth() + 1).padStart(2, '0'); // Les mois commencent à 0
    let day = String(now.getDate()).padStart(2, '0');
    let hours = String(now.getHours()).padStart(2, '0');
    let minutes = String(now.getMinutes()).padStart(2, '0');
    let seconds = String(now.getSeconds()).padStart(2, '0');

    // Concaténer les parties pour obtenir le format final
    let date = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;

    // Retourner le résultat
    return date;
}

