// ====== CONFIGURATION DU DÉLAI DE RETRY ======
const RETRY_DELAY_MINUTES = 10;  // ✅ Délai avant relance automatique (en minutes)
const RETRY_DELAY_MS = RETRY_DELAY_MINUTES * 60 * 1000;
const RETRY_SEND_DELAY_MS = 15000;  // ✅ Délai avant d'envoyer le retry (en millisecondes, défaut:  5s)
const MAX_RETRY_ATTEMPTS = 15;  // ✅ Nombre maximum de tentatives de retry

// ====== FONCTION DE VÉRIFICATION DE RÉCEPTION (avec cooldown pour override) ======
function checkMessageConfirmation(materiel, intervalRenvoiMs, lastReceiveTimestamp) {
    const lastSend = materiel.lastSend;
    const lastReceive = materiel.lastReceive;
    const now = Date.now();

    // ✅ Sécurité:  vérifier si lastReceive existe
    if (!lastReceive || !lastReceive.timestampLastReceive) {
        return { confirmed: false, manualOverride: false, shouldRetry: false };
    }

    const isMessageMoreRecent = lastReceive.timestampLastReceive > lastSend.timestampLastSend;
    const isValueMatching = lastReceive.pilotageTorLastReceive === lastSend.pilotageTorLastSend;

    // CAS 1: Déjà confirmé + reçu différent = changement manuel du device
    if (lastSend.received && lastSend.stateConfirmed && isMessageMoreRecent && !isValueMatching) {
        // Initialiser le cooldown à la première détection du changement manuel
        if (!lastSend.overrideCooldownTimestamp) {
            lastSend.overrideCooldownTimestamp = now;
            return { confirmed: true, manualOverride: true, shouldRetry: false, inCooldown: true };
        }

        // Vérifier si le cooldown a expiré
        const timeSinceOverride = now - lastSend.overrideCooldownTimestamp;
        if (timeSinceOverride < intervalRenvoiMs) {
            // Cooldown toujours actif
            return { confirmed: true, manualOverride: true, shouldRetry: false, inCooldown: true };
        } else {
            // Cooldown expiré, relancer normalement
            lastSend.overrideCooldownTimestamp = null;
            lastSend.confirmationAttempts = 0;
            return { confirmed: false, manualOverride: true, shouldRetry: true, inCooldown: false };
        }
    }

    // CAS 2: En attente de confirmation
    if (isMessageMoreRecent && isValueMatching) {
        lastSend.received = true;
        lastSend.stateConfirmed = true;
        lastSend.confirmationAttempts = 0;
        lastSend.overrideCooldownTimestamp = null;
        return { confirmed: true, manualOverride: false, shouldRetry: false };
    }

    // CAS 3: Pas encore confirmé → relancer SI nouvel uplink OU délai de retry dépassé
    const timeSinceLastSend = now - lastSend.timestampLastSend;
    const newUplinkReceived = lastReceiveTimestamp > lastSend.timestampLastSend;
    const retryDelayExceeded = timeSinceLastSend > RETRY_DELAY_MS;

    if (lastSend.confirmationAttempts < MAX_RETRY_ATTEMPTS && (newUplinkReceived || retryDelayExceeded)) {
        lastSend.confirmationAttempts++;
        return { confirmed: false, manualOverride: false, shouldRetry: true, triggerReason: newUplinkReceived ? "newUplink" : "retryDelayExceeded" };
    }

    // CAS 4: Échec après MAX_RETRY_ATTEMPTS tentatives
    lastSend.received = false;
    lastSend.stateConfirmed = false;
    lastSend.overrideCooldownTimestamp = null;
    return { confirmed: false, manualOverride: false, shouldRetry: false };
}

