// ====== BOUCLE PRINCIPALE SUR LES MATÉRIELS ======
for (let i = 0; i < materiels.length; i++) {
    if (materiels[i].type == "MCLIMATE_16A") {
        keyZones = -1;

        // ✅ Recherche de la zone correspondante
        for (let y = 0; y < zones.length; y++) {
            if (Number(zones[y].numero) === Number(materiels[i].numero)) {
                keyZones = y;
                break;
            }
        }

        if (keyZones == -1) {
            continue;
        }

        // ✅ CONVERSION DE TYPES SÉCURISÉE
        const zoneActivationRegul = Number(zones[keyZones].activationRegul);
        const zoneOccupationPermanente = Number(zones[keyZones].occupationPermanente);
        const pilotageTorZone = Number(zones[keyZones].data.pilotageTorZone);
        const statusAllumage = Number(zones[keyZones].data.statusAllumage.value);

        let deveui = materiels[i].deveui;
        let isMsgSend = false;

        msg.url = "https://localhost:8080/api/devices/" + deveui + "/queue";

        // Objet pour tracker les infos d'envoi
        let sendInfo = {
            pilotage: { send: false, changed: false, intervalExceeded: false }
        };

        // ====== CALCUL DES CONDITIONS ======
        const now = Date.now();
        const timeDiff = now - materiels[i].lastSend.timestampLastSend;
        const timeDiffSeconds = Math.floor(timeDiff / 1000);
        const intervalMs = intervalRenvoi * 60 * 1000;

        // CONDITION 1: Pilotage changé OU intervalle dépassé
        const cond1_pilotageChanged = materiels[i].lastSend.pilotageTorLastSend !== pilotageTorZone;
        const cond1_intervalExceeded = timeDiff > intervalMs;
        const cond1_result = cond1_pilotageChanged || cond1_intervalExceeded;

        // CONDITION 2: Status différent du pilotage OU intervalle dépassé
        const cond2_statusDifferent = statusAllumage !== pilotageTorZone;
        const cond2_intervalExceeded = timeDiff > intervalMs;
        const cond2_result = (cond2_statusDifferent || cond2_intervalExceeded) && cond1_result;

        // CONDITION 3: Occupation permanente OU intervalle dépassé
        const cond3_intervalExceeded = timeDiff > intervalMs;
        const cond3_result = (zoneOccupationPermanente == 1 || cond3_intervalExceeded) && cond2_result;

        // ====== VÉRIFICATION DE RÉCEPTION (avant envoi) ======
        const intervalRenvoiMs = intervalRenvoi * 60 * 1000;
        const lastReceiveTimestamp = materiels[i].lastReceive ? materiels[i].lastReceive.timestampLastReceive : 0;
        const confirmationCheck = checkMessageConfirmation(materiels[i], intervalRenvoiMs, lastReceiveTimestamp);

        // ====== ENVOI PILOTAGE TOR (DOWNLINK) ======
        // ✅ ENVOI NORMAL (conditions satisfaites) OU RETRY (nouvel uplink/délai dépassé)
        const shouldSendForRetry = confirmationCheck.shouldRetry && !confirmationCheck.inCooldown;

        // Vérifier si c'est un retry et si le délai d'envoi du retry a expiré
        let canSendRetry = true;
        if (shouldSendForRetry) {
            // Si c'est la première détection du retry, initialiser le timestamp
            if (!materiels[i].lastSend.retryDelayTimestamp) {
                materiels[i].lastSend.retryDelayTimestamp = Date.now();
                canSendRetry = false;  // Ne pas envoyer au premier cycle
            } else {
                // Vérifier si le délai d'attente du retry a expiré
                const timeSinceRetryDetection = Date.now() - materiels[i].lastSend.retryDelayTimestamp;
                canSendRetry = timeSinceRetryDetection >= RETRY_SEND_DELAY_MS;
            }
        } else {
            // Réinitialiser le timestamp si ce n'est plus un retry
            materiels[i].lastSend.retryDelayTimestamp = null;
        }

        if (((cond1_result && cond2_result && cond3_result) || (shouldSendForRetry && canSendRetry))) {
            // Création du message en héxadécimal
            let messageHexPilotage = "C10" + pilotageTorZone + "B1";

            // Création du payload en Base64
            msg.payload = createMessageBase64(messageHexPilotage);

            // Enregistrer les infos d'envoi
            sendInfo.pilotage = {
                send: true,
                changed: cond1_pilotageChanged,
                intervalExceeded: cond1_intervalExceeded
            };

            if (actionMaintenance == 0) {
                node.send(msg);
                isMsgSend = true;

                // Met à jour les infos "lastSend"
                listChangeMaterielsId.push({
                    "key": i,
                    "data": {
                        "timestampLastSend": Date.now(),
                        "dateLastSend": getDateString(),
                        "modeClimLastSend": "",
                        "consigneClimLastSend": "",
                        "pilotageClimLastSend": "",
                        "consigneTorLastSend": "",
                        "pilotageTorLastSend": pilotageTorZone,
                        "downlink": messageHexPilotage,
                        "received": false,
                        "stateConfirmed": false,
                        "confirmationAttempts": materiels[i].lastSend.confirmationAttempts || 0,
                        "retryDelayTimestamp": null
                    }
                });

                if (shouldSendForRetry) {
                    const triggerMsg = confirmationCheck.triggerReason === "newUplink" ? "nouvel uplink" : "délai retry";
                    node.status({ fill: "green", shape: "dot", text: "🔄 Retry " + materiels[i].lastSend.confirmationAttempts + "/" + MAX_RETRY_ATTEMPTS + " (" + triggerMsg + ") pour (" + deveui + ")" });
                } else {
                    node.status({ fill: "green", shape: "dot", text: "Pilotage envoyé pour (" + deveui + ") = " + pilotageTorZone });
                }
            } else {
                node.status({ fill: "yellow", shape: "dot", text: "Mode MAINTENANCE:   Pilotage NON envoyé pour (" + deveui + ")" });
            }
        } else if (confirmationCheck.inCooldown) {
            node.status({ fill: "blue", shape: "dot", text: "⏳ Cooldown override (" + deveui + ")" });
        } else if (confirmationCheck.confirmed) {
            node.status({ fill: "blue", shape: "dot", text: "✅ Reçu confirmé (" + deveui + ")" });
        } else if (shouldSendForRetry && !canSendRetry) {
            // Afficher le délai d'attente avant l'envoi du retry
            const timeSinceRetryDetection = Date.now() - (materiels[i].lastSend.retryDelayTimestamp || Date.now());
            const remainingDelay = Math.ceil((RETRY_SEND_DELAY_MS - timeSinceRetryDetection) / 1000);
            node.status({ fill: "cyan", shape: "dot", text: "⏳ Délai avant retry " + remainingDelay + "s (" + deveui + ")" });
        } else if (confirmationCheck.shouldRetry) {
            const triggerMsg = confirmationCheck.triggerReason === "newUplink" ? "(nouvel uplink)" : "(délai retry dépassé)";
            node.status({ fill: "orange", shape: "dot", text: "🔄 Tentative " + materiels[i].lastSend.confirmationAttempts + "/" + MAX_RETRY_ATTEMPTS + " " + triggerMsg + " (" + deveui + ")" });
        }

        // ====== AFFICHAGE DEBUG POUR TOUTES LES ZONES MONITORÉES ======
        logZoneDebug(
            zones[keyZones].numero,
            zones[keyZones].data,
            {
                activationRegul: zones[keyZones].activationRegul,
                occupationPermanente: zones[keyZones].occupationPermanente
            },
            materiels[i],
            {
                pilotageTorZone: pilotageTorZone,
                consigneTorZone: zones[keyZones].data.consigneTorZone
            },
            sendInfo,
            {
                cond1: {
                    pilotageChanged: cond1_pilotageChanged,
                    intervalExceeded: cond1_intervalExceeded,
                    timeDiff: timeDiffSeconds,
                    result: cond1_result
                },
                cond2: {
                    statusDifferent: cond2_statusDifferent,
                    intervalExceeded: cond2_intervalExceeded,
                    result: cond2_result
                },
                cond3: {
                    intervalExceeded: cond3_intervalExceeded,
                    result: cond3_result
                }
            },
            confirmationCheck,
            intervalRenvoiMs
        );
    }
}

// ====== MÉMORISER LES CHANGEMENTS ======
for (let z = 0; z < listChangeMaterielsId.length; z++) {
