// ====== HELPERS LAST RECEIVE (SLC multi-sorties) ======
function getLastReceiveTimestamp(materiel) {
    if (!materiel || !materiel.lastReceive) return 0;

    // cas standard
    if (materiel.lastReceive.timestampLastReceive !== undefined) {
        return Number(materiel.lastReceive.timestampLastReceive) || 0;
    }

    // fallback
    if (materiel.lastReceive.timestamp !== undefined) {
        return Number(materiel.lastReceive.timestamp) || 0;
    }

    return 0;
}

function getLastReceivePilotage(materiel) {
    if (!materiel || !materiel.lastReceive) return undefined;

    // 1) si déjà stocké par ton flow uplink
    if (materiel.lastReceive.pilotageTorLastReceive !== undefined) {
        return Number(materiel.lastReceive.pilotageTorLastReceive);
    }

    // 2) cas "switch_X" (très courant Milesight/WS558)
    const key = "switch_" + Number(materiel.sortie);
    if (materiel.lastReceive[key] !== undefined) {
        return Number(materiel.lastReceive[key]);
    }

    // 3) fallback array/map éventuel
    if (materiel.lastReceive.switches && materiel.lastReceive.switches[Number(materiel.sortie)] !== undefined) {
        return Number(materiel.lastReceive.switches[Number(materiel.sortie)]);
    }

    return undefined;
}


// ====== FONCTION CONFIRMATION / RETRY / OVERRIDE (adaptée SLC) ======
function ensureLastSendShape(materiel) {
    if (!materiel.lastSend) materiel.lastSend = {};

    // Valeurs par défaut (ne pas écraser si déjà présent)
    if (materiel.lastSend.timestampLastSend === undefined) materiel.lastSend.timestampLastSend = 0;
    if (materiel.lastSend.dateLastSend === undefined) materiel.lastSend.dateLastSend = "";
    if (materiel.lastSend.pilotageTorLastSend === undefined) materiel.lastSend.pilotageTorLastSend = "";
    if (materiel.lastSend.downlink === undefined) materiel.lastSend.downlink = "";

    if (materiel.lastSend.received === undefined) materiel.lastSend.received = false;
    if (materiel.lastSend.stateConfirmed === undefined) materiel.lastSend.stateConfirmed = false;

    if (materiel.lastSend.confirmationAttempts === undefined) materiel.lastSend.confirmationAttempts = 0;
    if (materiel.lastSend.overrideCooldownTimestamp === undefined) materiel.lastSend.overrideCooldownTimestamp = null;
    if (materiel.lastSend.retryDelayTimestamp === undefined) materiel.lastSend.retryDelayTimestamp = null;
}

// intervalRenvoiMs sert au cooldown override (même logique que ton NKE_FP)
function checkMessageConfirmation(materiel, intervalRenvoiMs) {
    ensureLastSendShape(materiel);

    const lastSend = materiel.lastSend;
    const now = Date.now();

    const lastSendTs = Number(lastSend.timestampLastSend) || 0;
    const lastReceiveTs = getLastReceiveTimestamp(materiel);
    const receivePilotage = getLastReceivePilotage(materiel);
    const sendPilotage = (lastSend.pilotageTorLastSend === "" || lastSend.pilotageTorLastSend === undefined)
        ? undefined
        : Number(lastSend.pilotageTorLastSend);

    const isMessageMoreRecent = lastReceiveTs > lastSendTs;
    const isValueMatching = (receivePilotage !== undefined && sendPilotage !== undefined)
        ? (Number(receivePilotage) === Number(sendPilotage))
        : false;

    // CAS 1: Déjà confirmé + réception plus récente mais valeur différente => override manuel détecté
    if (lastSend.received && lastSend.stateConfirmed && isMessageMoreRecent && (receivePilotage !== undefined) && !isValueMatching) {
        if (!lastSend.overrideCooldownTimestamp) {
            lastSend.overrideCooldownTimestamp = now;
            return { confirmed: true, manualOverride: true, shouldRetry: false, inCooldown: true };
        }

        const timeSinceOverride = now - lastSend.overrideCooldownTimestamp;
        if (timeSinceOverride < intervalRenvoiMs) {
            return { confirmed: true, manualOverride: true, shouldRetry: false, inCooldown: true };
        } else {
            // cooldown terminé => on autorise un retry
            lastSend.overrideCooldownTimestamp = null;
            lastSend.confirmationAttempts = 0;
            return { confirmed: false, manualOverride: true, shouldRetry: true, inCooldown: false, triggerReason: "overrideCooldownExpired" };
        }
    }

    // CAS 2: Réception plus récente + valeur match => confirmé
    if (isMessageMoreRecent && isValueMatching) {
        lastSend.received = true;
        lastSend.stateConfirmed = true;
        lastSend.confirmationAttempts = 0;
        lastSend.overrideCooldownTimestamp = null;
        lastSend.retryDelayTimestamp = null;
        return { confirmed: true, manualOverride: false, shouldRetry: false };
    }

    // CAS 3: Non confirmé => retry si nouvel uplink OU délai retry dépassé
    const timeSinceLastSend = now - lastSendTs;
    const retryDelayExceeded = timeSinceLastSend > RETRY_DELAY_MS;

    // Si on n’a jamais eu de lastReceive, on permet quand même un retry sur délai dépassé
    const newUplinkReceived = isMessageMoreRecent;

    if (!lastSend.stateConfirmed && lastSend.confirmationAttempts < MAX_RETRY_ATTEMPTS && (newUplinkReceived || retryDelayExceeded)) {
        lastSend.confirmationAttempts++;
        return {
            confirmed: false,
            manualOverride: false,
            shouldRetry: true,
            inCooldown: false,
            triggerReason: newUplinkReceived ? "newUplink" : "retryDelayExceeded"
        };
    }

    // CAS 4: Échec après MAX_RETRY_ATTEMPTS
    if (!lastSend.stateConfirmed && lastSend.confirmationAttempts >= MAX_RETRY_ATTEMPTS) {
        lastSend.received = false;
        lastSend.stateConfirmed = false;
        lastSend.overrideCooldownTimestamp = null;
        lastSend.retryDelayTimestamp = null;
        return { confirmed: false, manualOverride: false, shouldRetry: false, inCooldown: false, failed: true };
    }

    return { confirmed: false, manualOverride: false, shouldRetry: false, inCooldown: false };
}


