// ====== BOUCLE PRINCIPALE SUR LES MATERIELS ======
for (let i = 0; i < materiels.length; i++) {
    if (materiels[i].type !== "SLC") continue;

    keyZones = -1;

    // Recherche de la zone correspondante
    for (let y = 0; y < zones.length; y++) {
        if (Number(zones[y].numero) === Number(materiels[i].numero)) {
            keyZones = y;
            break;
        }
    }
    if (keyZones === -1) continue;

    // conversions sécurisées
    const zoneActivationRegul = Number(zones[keyZones].activationRegul);
    const zoneAllumageManuel = Number(zones[keyZones].allumageManuel);
    const zoneOccupationPermanente = Number(zones[keyZones].occupationPermanente);
    const pilotageTorZone = Number(zones[keyZones].data.pilotageTorZone);
    const statusAllumage = Number(zones[keyZones].data.statusAllumage.value);

    // régul activée + auto
    if (zoneActivationRegul !== 1 || zoneAllumageManuel !== 0) continue;

    const deveui = materiels[i].deveui;
    const sortieIndex = Number(materiels[i].sortie) - 1;

    if (sortieIndex < 0 || sortieIndex > 7) continue;

    ensureLastSendShape(materiels[i]);

    // tracking debug local
    let sendInfo = {
        pilotage: { send: false, changed: false, intervalExceeded: false, retry: false }
    };

    // calcul conditions
    const now = Date.now();
    const timeDiff = now - Number(materiels[i].lastSend.timestampLastSend || 0);
    const timeDiffSeconds = Math.floor(timeDiff / 1000);
    const intervalMs = intervalRenvoi * 60 * 1000;

    const cond1_pilotageChanged = Number(materiels[i].lastSend.pilotageTorLastSend) !== pilotageTorZone;
    const cond1_intervalExceeded = timeDiff > intervalMs;
    const cond1_result = cond1_pilotageChanged || cond1_intervalExceeded;

    const cond2_statusDifferent = statusAllumage !== pilotageTorZone;
    const cond2_intervalExceeded = timeDiff > intervalMs;
    const cond2_result = (cond2_statusDifferent || cond2_intervalExceeded) && cond1_result;

    const cond3_intervalExceeded = timeDiff > intervalMs;
    const cond3_result = (zoneOccupationPermanente === 1 || cond3_intervalExceeded) && cond2_result;

    // confirmation / retry check
    const intervalRenvoiMs = intervalRenvoi * 60 * 1000;
    const confirmationCheck = checkMessageConfirmation(materiels[i], intervalRenvoiMs);

    // Normal send vs retry send
    const shouldSendNormal = (cond1_result && cond2_result && cond3_result);
    const shouldSendForRetry = confirmationCheck.shouldRetry && !confirmationCheck.inCooldown;

    // Gestion délai avant envoi retry (par materiel/sortie)
    let canSendRetry = true;
    if (shouldSendForRetry) {
        if (!materiels[i].lastSend.retryDelayTimestamp) {
            materiels[i].lastSend.retryDelayTimestamp = Date.now();
            canSendRetry = false;
        } else {
            const elapsed = Date.now() - materiels[i].lastSend.retryDelayTimestamp;
            canSendRetry = elapsed >= RETRY_SEND_DELAY_MS;
        }
    } else {
        materiels[i].lastSend.retryDelayTimestamp = null;
    }

    const includeInGroupSend = shouldSendNormal || (shouldSendForRetry && canSendRetry);

    // si on doit inclure dans le regroupement
    if (includeInGroupSend) {
        const bit = tabConvertion[sortieIndex];

        // flags debug
        sendInfo.pilotage = {
            send: true,
            changed: cond1_pilotageChanged,
            intervalExceeded: cond1_intervalExceeded,
            retry: (!shouldSendNormal && shouldSendForRetry)
        };

        // init regroupement
        if (!commandesParDevice[deveui]) {
            commandesParDevice[deveui] = {
                mask: 0,
                status: 0,
                indexMateriel: [],
                pilotages: [],
                sendTypes: [] // "normal" | "retry"
            };
        }

        // build mask/status
        commandesParDevice[deveui].mask |= bit;
        if (pilotageTorZone === 1) {
            commandesParDevice[deveui].status |= bit;
        }

        commandesParDevice[deveui].indexMateriel.push(i);
        commandesParDevice[deveui].pilotages.push(pilotageTorZone);
        commandesParDevice[deveui].sendTypes.push(shouldSendNormal ? "normal" : "retry");
    } else {
        // statuts utiles
        if (confirmationCheck.inCooldown) {
            node.status({ fill: "blue", shape: "dot", text: "Cooldown override (" + deveui + "/S" + (sortieIndex + 1) + ")" });
        } else if (confirmationCheck.confirmed) {
            node.status({ fill: "blue", shape: "dot", text: "Recu confirme (" + deveui + "/S" + (sortieIndex + 1) + ")" });
        } else if (shouldSendForRetry && !canSendRetry) {
            const elapsed = Date.now() - (materiels[i].lastSend.retryDelayTimestamp || Date.now());
            const remaining = Math.ceil((RETRY_SEND_DELAY_MS - elapsed) / 1000);
            node.status({ fill: "cyan", shape: "dot", text: "Delai avant retry " + remaining + "s (" + deveui + "/S" + (sortieIndex + 1) + ")" });
        } else if (confirmationCheck.shouldRetry) {
            const trig = confirmationCheck.triggerReason === "newUplink" ? "newUplink" : "retryDelay";
            node.status({ fill: "orange", shape: "dot", text: "Retry pending " + materiels[i].lastSend.confirmationAttempts + "/" + MAX_RETRY_ATTEMPTS + " (" + trig + ") " + deveui + "/S" + (sortieIndex + 1) });
        }
    }

    // debug par zone/devEUI
    logZoneDebug(
        zones[keyZones].numero,
        zones[keyZones].data,
        {
            activationRegul: zones[keyZones].activationRegul,
            allumageManuel: zones[keyZones].allumageManuel,
            occupationPermanente: zones[keyZones].occupationPermanente
        },
        materiels[i],
        {
            pilotageTorZone: pilotageTorZone,
            sortie: sortieIndex + 1,
            maskSwitch: tabConvertion[sortieIndex],
            statusSwitch: pilotageTorZone === 1 ? tabConvertion[sortieIndex] : 0
        },
        sendInfo,
        {
            cond1: {
                pilotageChanged: cond1_pilotageChanged,
                intervalExceeded: cond1_intervalExceeded,
                timeDiff: timeDiffSeconds,
                result: cond1_result
            },
            cond2: {
                statusDifferent: cond2_statusDifferent,
                intervalExceeded: cond2_intervalExceeded,
                result: cond2_result
            },
            cond3: {
                intervalExceeded: cond3_intervalExceeded,
                result: cond3_result
            }
        },
        confirmationCheck,
        intervalRenvoiMs
    );
}


// ====== ENVOI DES DOWNLINKS REGROUPES ======
for (let devEUI in commandesParDevice) {
    const { mask, status, indexMateriel, pilotages, sendTypes } = commandesParDevice[devEUI];
    const messageHex = "08" + mask.toString(16).padStart(2, '0') + status.toString(16).padStart(2, '0');

    // Mettre à jour les matériels concernés
    for (let j = 0; j < indexMateriel.length; j++) {
        const idx = indexMateriel[j];
        const sendType = sendTypes[j]; // normal|retry

        ensureLastSendShape(materiels[idx]);

        // Si envoi "normal", on repart propre sur attempts
        const attempts = (sendType === "normal") ? 0 : (materiels[idx].lastSend.confirmationAttempts || 0);

        materiels[idx].lastSend = {
            "timestampLastSend": Date.now(),
            "dateLastSend": getDateString(),
            "modeClimLastSend": "",
            "consigneClimLastSend": "",
            "pilotageClimLastSend": "",
            "consigneTorLastSend": "",
            "pilotageTorLastSend": pilotages[j],
            "downlink": messageHex,

            // champs confirmation/retry
            "received": false,
            "stateConfirmed": false,
            "confirmationAttempts": attempts,
            "overrideCooldownTimestamp": materiels[idx].lastSend.overrideCooldownTimestamp || null,
            "retryDelayTimestamp": null
        };
    }

    if (actionMaintenance === 0) {
        node.status({ fill: "green", shape: "dot", text: `SLC ${devEUI} -> ${messageHex} (mask=${mask}, status=${status})` });
        node.send({
            url: `https://localhost:8080/api/devices/${devEUI}/queue`,
            headers: msg.headers,
            rejectUnauthorized: false,
            payload: createMessageBase64(messageHex)
        });
    } else {
        node.status({ fill: "yellow", shape: "dot", text: `Mode MAINTENANCE: SLC ${devEUI}` });
    }
}

global.set("materiels", materiels);


// ====== FONCTIONS UTILITAIRES ======
function createMessageBase64(hexString) {
    const buffer = Buffer.from(hexString, 'hex');
    const base64String = buffer.toString('base64');
    return {
        "confirmed": false,
        "fPort": 85,
        "data": base64String
    };
}

function compareTimestamp(timestamp1, timestamp2, intervalle) {
    const differenceInMilliseconds = Math.abs(timestamp1 - timestamp2);
    const intervallInMilliseconds = intervalle * 60 * 1000;
    return differenceInMilliseconds > intervallInMilliseconds;
}

function getDateString() {
    let now = new Date();
    let year = now.getFullYear();
    let month = String(now.getMonth() + 1).padStart(2, '0');
    let day = String(now.getDate()).padStart(2, '0');
    let hours = String(now.getHours()).padStart(2, '0');
    let minutes = String(now.getMinutes()).padStart(2, '0');
    let seconds = String(now.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
