// ====== HELPERS lastSend shape ======
function ensureLastSendMClimateShape(m) {
    if (!m.lastSend) m.lastSend = {};

    if (m.lastSend.timestampLastSend === undefined) m.lastSend.timestampLastSend = 0;
    if (m.lastSend.dateLastSend === undefined) m.lastSend.dateLastSend = "";

    if (m.lastSend.pilotageClimLastSend === undefined) m.lastSend.pilotageClimLastSend = "";
    if (m.lastSend.consigneClimLastSend === undefined) m.lastSend.consigneClimLastSend = "";
    if (m.lastSend.modeClimLastSend === undefined) m.lastSend.modeClimLastSend = "";

    if (m.lastSend.downlink === undefined) m.lastSend.downlink = "";
    if (m.lastSend.received === undefined) m.lastSend.received = false;
    if (m.lastSend.stateConfirmed === undefined) m.lastSend.stateConfirmed = false;

    if (m.lastSend.confirmationAttempts === undefined) m.lastSend.confirmationAttempts = 0;
    if (m.lastSend.overrideCooldownTimestamp === undefined) m.lastSend.overrideCooldownTimestamp = null;
    if (m.lastSend.retryDelayTimestamp === undefined) m.lastSend.retryDelayTimestamp = null;
    if (m.lastSend.eventModeOverrideLastSend === undefined) m.lastSend.eventModeOverrideLastSend = false;

    // interne : quel type on attend ("consigne"|"pilotage"|"mode"| "")
    if (m.lastSend.awaitedType === undefined) m.lastSend.awaitedType = "";
