// ====== HELPERS lastReceive (adapter si besoin) ======
function getLastReceiveTimestamp(m) {
    if (!m || !m.lastReceive) return 0;
    if (m.lastReceive.timestampLastReceive !== undefined) return Number(m.lastReceive.timestampLastReceive) || 0;
    if (m.lastReceive.timestamp !== undefined) return Number(m.lastReceive.timestamp) || 0;
