}
function getLastReceiveConsigne(m) {
    if (!m || !m.lastReceive) return undefined;
    if (m.lastReceive.consigneClimLastReceive !== undefined) return Number(m.lastReceive.consigneClimLastReceive);
    if (m.lastReceive.consigne !== undefined) return Number(m.lastReceive.consigne);
