}
function getLastReceivePilotage(m) {
    if (!m || !m.lastReceive) return undefined;
    if (m.lastReceive.pilotageClimLastReceive !== undefined) return Number(m.lastReceive.pilotageClimLastReceive);
    if (m.lastReceive.pilotage !== undefined) return Number(m.lastReceive.pilotage);
