}

// ====== CONFIRMATION / RETRY / OVERRIDE (MCLIMATE_FCT) ======
function checkMessageConfirmationMClimate(materiel, intervalRenvoiMs) {
    ensureLastSendMClimateShape(materiel);

    const lastSend = materiel.lastSend;
    const now = Date.now();

    const sendTs = Number(lastSend.timestampLastSend) || 0;
    const receiveTs = getLastReceiveTimestamp(materiel);

    const isMoreRecent = receiveTs > sendTs;

    // DÃ©terminer le champ confirmÃ© (prioritÃ© pilotage > mode > consigne)
    let awaitedType = lastSend.awaitedType;

    if (!awaitedType) {
        if (lastSend.pilotageClimLastSend !== "" && lastSend.pilotageClimLastSend !== undefined) awaitedType = "pilotage";
        else if (lastSend.modeClimLastSend !== "" && lastSend.modeClimLastSend !== undefined) awaitedType = "mode";
        else if (lastSend.consigneClimLastSend !== "" && lastSend.consigneClimLastSend !== undefined) awaitedType = "consigne";
        else awaitedType = "";
        lastSend.awaitedType = awaitedType;
    }

    if (!awaitedType) {
        return { confirmed: false, shouldRetry: false, inCooldown: false, manualOverride: false, awaitedType: "" };
    }

    let sendValue, receiveValue;
    if (awaitedType === "pilotage") {
        sendValue = Number(lastSend.pilotageClimLastSend);
        receiveValue = getLastReceivePilotage(materiel);
    } else if (awaitedType === "mode") {
        sendValue = Number(lastSend.modeClimLastSend);
        receiveValue = getLastReceiveMode(materiel);
    } else {
        sendValue = Number(lastSend.consigneClimLastSend);
        receiveValue = getLastReceiveConsigne(materiel);
    }

    const hasReceiveValue = (receiveValue !== undefined && !Number.isNaN(receiveValue));
    const isMatching = (hasReceiveValue && !Number.isNaN(sendValue)) ? (Number(receiveValue) === Number(sendValue)) : false;

    // CAS 1: override manuel dÃ©tectÃ©
    if (lastSend.received && lastSend.stateConfirmed && isMoreRecent && hasReceiveValue && !isMatching) {
        if (!lastSend.overrideCooldownTimestamp) {
            lastSend.overrideCooldownTimestamp = now;
            return { confirmed: true, manualOverride: true, shouldRetry: false, inCooldown: true, awaitedType };
        }

        const elapsed = now - lastSend.overrideCooldownTimestamp;
        if (elapsed < intervalRenvoiMs) {
            return { confirmed: true, manualOverride: true, shouldRetry: false, inCooldown: true, awaitedType };
        } else {
            lastSend.overrideCooldownTimestamp = null;
            lastSend.confirmationAttempts = 0;
            return { confirmed: false, manualOverride: true, shouldRetry: true, inCooldown: false, triggerReason: "overrideCooldownExpired", awaitedType };
        }
    }

    // CAS 2: confirmÃ©
    if (isMoreRecent && isMatching) {
        lastSend.received = true;
        lastSend.stateConfirmed = true;
        lastSend.confirmationAttempts = 0;
        lastSend.overrideCooldownTimestamp = null;
        lastSend.retryDelayTimestamp = null;
        return { confirmed: true, manualOverride: false, shouldRetry: false, inCooldown: false, awaitedType };
    }

    // CAS 3: retry si nouvel uplink OU dÃ©lai dÃ©passÃ©
    const timeSinceSend = now - sendTs;
    const retryDelayExceeded = timeSinceSend > RETRY_DELAY_MS;
    const newUplinkReceived = isMoreRecent;

    if (!lastSend.stateConfirmed && lastSend.confirmationAttempts < MAX_RETRY_ATTEMPTS && (newUplinkReceived || retryDelayExceeded)) {
        lastSend.confirmationAttempts++;
        return { confirmed: false, manualOverride: false, shouldRetry: true, inCooldown: false, triggerReason: newUplinkReceived ? "newUplink" : "retryDelayExceeded", awaitedType };
    }

    // CAS 4: Ã©chec
    if (!lastSend.stateConfirmed && lastSend.confirmationAttempts >= MAX_RETRY_ATTEMPTS) {
        lastSend.received = false;
        lastSend.stateConfirmed = false;
        lastSend.overrideCooldownTimestamp = null;
        lastSend.retryDelayTimestamp = null;
        return { confirmed: false, manualOverride: false, shouldRetry: false, inCooldown: false, failed: true, awaitedType };
    }

    return { confirmed: false, manualOverride: false, shouldRetry: false, inCooldown: false, awaitedType };
}


