        resolution.seasonality &&
        resolution.seasonality.source === "EVENT";
    const eventWasForcingMode = materiels[i].lastSend.eventModeOverrideLastSend === true;

    let isMsgSend = false;
    let downlinkSend = "";

    const now = Date.now();
    const timeDiff = now - Number(materiels[i].lastSend.timestampLastSend || 0);
    const timeDiffSeconds = Math.floor(timeDiff / 1000);
    const intervalMs = intervalRenvoi * 60 * 1000;
    const intervalRenvoiMs = intervalRenvoi * 60 * 1000;

    // ====== CONDITIONS ======
    // CONSIGNE
    const consigne_changed = (materiels[i].lastSend.consigneClimLastSend !== consigneClimZone);
    const consigne_intervalExceeded = timeDiff > intervalMs;
    const consigne_statusDifferent = (Number(zones[keyZones].data.statusConsigne.value) !== consigneClimZone);
    const consigne_rangeValid = (consigneClimZone >= 5 && consigneClimZone <= 30);
    const consigne_result =
        (consigne_changed || consigne_intervalExceeded) &&
        (consigne_statusDifferent || consigne_intervalExceeded) &&
        consigne_rangeValid;

    // PILOTAGE
    const pilotage_changed = (materiels[i].lastSend.pilotageClimLastSend !== pilotageClimZone);
    const pilotage_intervalExceeded = timeDiff > intervalMs;
    const pilotage_statusDifferent = (Number(zones[keyZones].data.statusAllumage.value) !== pilotageClimZone);
    const pilotage_occupationOrInterval = (zones[keyZones].occupationPermanente == true || pilotage_intervalExceeded);
    const pilotage_result =
        (pilotage_changed || pilotage_intervalExceeded) &&
        (pilotage_statusDifferent || pilotage_intervalExceeded) &&
        pilotage_occupationOrInterval;

    // MODE
    const mode_gestionModeCLIM = (params.gestionModeCLIM == 1);
    const mode_bypassEvent = eventForcesMode || eventWasForcingMode;
    const mode_changed = (materiels[i].lastSend.modeClimLastSend !== modeClimZone);
    const mode_intervalExceeded = timeDiff > intervalMs;
    const mode_statusDifferent = (Number(zones[keyZones].data.statusMode.value) !== modeClimZone);
    const mode_result =
        (mode_gestionModeCLIM || mode_bypassEvent) &&
        (mode_changed || mode_intervalExceeded) &&
        (mode_statusDifferent || mode_intervalExceeded);

    // Si un event forcait precedemment le mode mais que l'equipement est deja
    // revenu a l'etat nominal, on purge le bypass pour retrouver le
    // comportement standard hors event.
    if (!eventForcesMode && eventWasForcingMode && !mode_changed && !mode_statusDifferent) {
        materiels[i].lastSend.eventModeOverrideLastSend = false;
    }

    // ====== CONFIRMATION / RETRY ======
    const confirmationCheck = checkMessageConfirmationMClimate(materiels[i], intervalRenvoiMs);
    const shouldSendForRetry = confirmationCheck.shouldRetry && !confirmationCheck.inCooldown;

    // dÃ©lai avant envoi retry
    let canSendRetry = true;
    if (shouldSendForRetry) {
        if (!materiels[i].lastSend.retryDelayTimestamp) {
            materiels[i].lastSend.retryDelayTimestamp = Date.now();
            canSendRetry = false;
        } else {
            const elapsed = Date.now() - materiels[i].lastSend.retryDelayTimestamp;
            canSendRetry = elapsed >= RETRY_SEND_DELAY_MS;
        }
    } else {
        materiels[i].lastSend.retryDelayTimestamp = null;
    }

    // ====== SEND INFO pour debug ======
    let sendInfo = {
        consigne: { send: false },
        pilotage: { send: false },
        mode: { send: false },
        retry: { send: false, type: "" }
    };

    // ====== ENVOIS NORMAUX ======
    if (actionMaintenance == 0) {
        if (consigne_result) {
            downlinkSend += sendConsigneRangeLock(deveui, consigneClimZone);
            isMsgSend = true;
            sendInfo.consigne.send = true;
            materiels[i].lastSend.awaitedType = "consigne";
        }

        if (pilotage_result) {
            downlinkSend += sendPilotage(deveui, pilotageClimZone);
            isMsgSend = true;
            sendInfo.pilotage.send = true;
            materiels[i].lastSend.awaitedType = "pilotage"; // prioritÃ© confirmation
        }

        if (mode_result) {
            downlinkSend += sendMode(deveui, modeClimZone);
            isMsgSend = true;
            sendInfo.mode.send = true;
            if (materiels[i].lastSend.awaitedType !== "pilotage") {
                materiels[i].lastSend.awaitedType = "mode";
            }
        }
    }

    // ====== ENVOI RETRY (si aucun envoi normal ce cycle) ======
    if (!isMsgSend && shouldSendForRetry && canSendRetry && actionMaintenance == 0) {
        const t = confirmationCheck.awaitedType;

        if (t === "consigne") {
            downlinkSend += sendConsigneRangeLock(deveui, Number(materiels[i].lastSend.consigneClimLastSend));
            isMsgSend = true;
        } else if (t === "pilotage") {
            downlinkSend += sendPilotage(deveui, Number(materiels[i].lastSend.pilotageClimLastSend));
            isMsgSend = true;
        } else if (t === "mode") {
            downlinkSend += sendMode(deveui, Number(materiels[i].lastSend.modeClimLastSend));
            isMsgSend = true;
        }

        if (isMsgSend) {
            sendInfo.retry.send = true;
            sendInfo.retry.type = t;
        }
    }

    // ====== UPDATE lastSend si envoi (normal ou retry) ======
    if (isMsgSend) {
        listChangeMaterielsId.push({
            "key": i,
            "data": {
                "timestampLastSend": Date.now(),
                "dateLastSend": getDateString(),
                "pilotageClimLastSend": pilotageClimZone,
                "consigneClimLastSend": consigneClimZone,
                "modeClimLastSend": modeClimZone,
                "consigneTorLastSend": "",
                "pilotageTorLastSend": "",
                "downlink": downlinkSend,
                "received": false,

                // confirmation/retry
                "stateConfirmed": false,
                "confirmationAttempts": (consigne_result || pilotage_result || mode_result) ? 0 : (materiels[i].lastSend.confirmationAttempts || 0),
                "overrideCooldownTimestamp": materiels[i].lastSend.overrideCooldownTimestamp || null,
                "retryDelayTimestamp": null,
                "awaitedType": materiels[i].lastSend.awaitedType || "",
                "eventModeOverrideLastSend": eventForcesMode
            }
        });

        if (actionMaintenance == 0) {
            node.status({ fill: "green", shape: "dot", text: "MCLIMATE_FCT send (" + deveui + ") " + (sendInfo.retry.send ? "RETRY " + sendInfo.retry.type : "NORMAL") });
        }
    } else {
        // Statuts utiles
        if (actionMaintenance == 0) {
            if (confirmationCheck.inCooldown) {
                node.status({ fill: "blue", shape: "dot", text: "Cooldown override (" + deveui + ")" });
            } else if (confirmationCheck.confirmed) {
                node.status({ fill: "blue", shape: "dot", text: "Recu confirme (" + deveui + ")" });
            } else if (shouldSendForRetry && !canSendRetry) {
                const elapsed = Date.now() - (materiels[i].lastSend.retryDelayTimestamp || Date.now());
                const remaining = Math.ceil((RETRY_SEND_DELAY_MS - elapsed) / 1000);
                node.status({ fill: "cyan", shape: "dot", text: "Delai avant retry " + remaining + "s (" + deveui + ")" });
            } else if (confirmationCheck.shouldRetry) {
                const trig = confirmationCheck.triggerReason === "newUplink" ? "(nouvel uplink)" : "(delai retry depasse)";
                node.status({
                    fill: "orange",
                    shape: "dot",
                    text: "Retry pending " + (materiels[i].lastSend.confirmationAttempts || 0) + "/" + MAX_RETRY_ATTEMPTS + " " + trig + " (" + deveui + ")"
                });
            }
        } else {
            if (consigne_result || pilotage_result || mode_result || shouldSendForRetry) {
                node.status({ fill: "yellow", shape: "dot", text: "Mode MAINTENANCE: MCLIMATE_FCT " + deveui });
            }
        }
    }

    // ====== DEBUG ======
    logZoneDebugMClimate(
        zones[keyZones].numero,
        zones[keyZones].data,
        { occupationPermanente: zones[keyZones].occupationPermanente },
        materiels[i],
        { pilotageClimZone, consigneClimZone, modeClimZone },
        {
            consigne: {
                changed: consigne_changed,
                intervalExceeded: consigne_intervalExceeded,
