                changed: mode_changed,
                intervalExceeded: mode_intervalExceeded,
                statusDifferent: mode_statusDifferent,
                result: mode_result
            }
        },
        sendInfo,
        confirmationCheck,
        intervalRenvoiMs
    );
}

