// ====== BOUCLE PRINCIPALE SUR LES MATÉRIELS ======
for (let i = 0; i < materiels.length; i++) {
    if (materiels[i].type == "MCLIMATE_16A_E") {
        ensureEclairageShape(materiels[i]);

        keyPlanning = -1;

        // ✅ Recherche du planning correspondant
        for (let y = 0; y < plannings_e.length; y++) {
            if (Number(plannings_e[y].id) === Number(materiels[i].plannings_e_id)) {
                keyPlanning = y;
                break;
            }
        }

        if (keyPlanning == -1) continue;

        const deveui = materiels[i].deveui;
        msg.url = "https://localhost:8080/api/devices/" + deveui + "/queue";

        // état planning
        const dayKeyToday = "day" + dayOfWeek;
        const todaySchedule = plannings_e[keyPlanning][dayKeyToday];
        const todayEvents = parseSchedule(todaySchedule, 0);

        let currentState = 0;
        for (let j = 0; j < todayEvents.length; j++) {
            const currentEvent = todayEvents[j];
            const nextEvent = todayEvents[j + 1] || { time: Infinity, state: currentEvent.state };
            if (currentTime >= currentEvent.time && currentTime < nextEvent.time) {
                currentState = currentEvent.state;
                break;
            }
        }

        // ordre inversé (présence => 0, absence => 1)
        let ordreToSend = currentState === 1 ? 0 : 1;

        // sendInfo
        let sendInfo = {
            eclairage: { send: false, changed: false, intervalExceeded: false },
            retry: { send: false, reason: "" }
        };

        // ====== CALCUL DES CONDITIONS ======
        const timeDiff = Date.now() - (materiels[i].eclairage.timestampLastSend || 0);
        const timeDiffSeconds = Math.floor(timeDiff / 1000);
        const intervalMs = intervalRenvoi * 60 * 1000;
        const intervalRenvoiMs = intervalMs;

        // CONDITION 1
        const cond1_ordreChanged = materiels[i].eclairage.ordreLastSend !== ordreToSend;
        const cond1_intervalExceeded = timeDiff > intervalMs;
        const cond1_result = cond1_ordreChanged || cond1_intervalExceeded;

        // CONDITION 2
        // ✅ on compare avec statutValue "terrain"
        const statutTerrain = (materiels[i].eclairage.statutValue !== undefined && materiels[i].eclairage.statutValue !== null)
            ? Number(materiels[i].eclairage.statutValue)
            : Number(getLastReceiveStatutValue(materiels[i])); // fallback lastReceive si dispo

        const cond2_statutDifferent = (statutTerrain !== undefined && !Number.isNaN(statutTerrain))
            ? (Number(statutTerrain) !== Number(ordreToSend))
            : true; // si pas de statut, on considère différent pour forcer l'envoi si cond1 ok

        const cond2_intervalExceeded = timeDiff > intervalMs;
        const cond2_result = (cond2_statutDifferent || cond2_intervalExceeded) && cond1_result;

        // ====== CONFIRMATION / RETRY ======
        const confirmationCheck = checkMessageConfirmationEclairage(materiels[i], intervalRenvoiMs);
        const shouldSendForRetry = confirmationCheck.shouldRetry && !confirmationCheck.inCooldown;

        // délai avant envoi retry
        let canSendRetry = true;
        if (shouldSendForRetry) {
            if (!materiels[i].eclairage.retryDelayTimestamp) {
                materiels[i].eclairage.retryDelayTimestamp = Date.now();
                canSendRetry = false;
            } else {
                const elapsed = Date.now() - materiels[i].eclairage.retryDelayTimestamp;
                canSendRetry = elapsed >= RETRY_SEND_DELAY_MS;
            }
        } else {
            materiels[i].eclairage.retryDelayTimestamp = null;
        }

        // ====== DÉCISION ENVOI NORMAL OU RETRY ======
        const shouldSendNormal = cond2_result;
        const shouldSendRetryNow = shouldSendForRetry && canSendRetry;

        if (shouldSendNormal || shouldSendRetryNow) {
            const messageHex = "C10" + ordreToSend + "B1";

            // infos sendInfo
            if (shouldSendNormal) {
                sendInfo.eclairage = {
                    send: true,
                    changed: cond1_ordreChanged,
                    intervalExceeded: cond1_intervalExceeded
                };
            } else {
                sendInfo.retry = {
                    send: true,
                    reason: confirmationCheck.triggerReason || "retry"
                };
            }

            // ✅ Ajouter à la liste des messages
            messagesList.push({
                key: i,
                devEUI: deveui,
                messageHex: messageHex,
                ordreToSend: ordreToSend,
                isRetry: (!shouldSendNormal && shouldSendRetryNow)
            });

            // ✅ Mise à jour lastSend SANS écraser lastReceive
            materiels[i].eclairage.timestampLastSend = Date.now();
            materiels[i].eclairage.dateLastSend = getDateString();
            materiels[i].eclairage.ordreLastSend = ordreToSend;
            materiels[i].eclairage.downlink = messageHex;

            materiels[i].eclairage.received = false;
            materiels[i].eclairage.stateConfirmed = false;

            // retry state
            materiels[i].eclairage.confirmationAttempts = (!shouldSendNormal && shouldSendRetryNow)
                ? (materiels[i].eclairage.confirmationAttempts || 0)
                : 0;

            materiels[i].eclairage.retryDelayTimestamp = null;
            materiels[i].eclairage.overrideCooldownTimestamp = materiels[i].eclairage.overrideCooldownTimestamp || null;
        }

        // ====== DEBUG ======
        logEclairageDebug(
            materiels[i],
            plannings_e[keyPlanning],
            { currentState, ordreToSend },
            sendInfo,
            {
                cond1: {
                    ordreChanged: cond1_ordreChanged,
                    intervalExceeded: cond1_intervalExceeded,
                    timeDiff: timeDiffSeconds,
                    result: cond1_result
                },
                cond2: {
                    statutDifferent: cond2_statutDifferent,
                    intervalExceeded: cond2_intervalExceeded,
                    result: cond2_result
                },
                eventCount: todayEvents.length
            },
            confirmationCheck,
            intervalRenvoiMs,
            todaySchedule,
            todayEvents
        );
    }
}


// ====== ENVOI DES DOWNLINKS ======
for (let j = 0; j < messagesList.length; j++) {
    const item = messagesList[j];

    if (gestionEclairage.deactivateGestionEclairage == 0) {
