// ====== FONCTIONS UTILITAIRES ======
function createMessageBase64(hexString) {
    const buffer = Buffer.from(hexString, 'hex');
    return {
        confirmed: false,
        fPort: 85,
        data: buffer.toString('base64')
    };
}

function getDateString() {
    let now = new Date();
    let year = now.getFullYear();
    let month = String(now.getMonth() + 1).padStart(2, '0');
    let day = String(now.getDate()).padStart(2, '0');
    let hours = String(now.getHours()).padStart(2, '0');
    let minutes = String(now.getMinutes()).padStart(2, '0');
    let seconds = String(now.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

// Fonction pour parser un planning
function parseSchedule(schedule, dayOffset = 0) {
    let events = [];
    if (!schedule || typeof schedule !== "string") return events;

    const parts = schedule.split(";");
    for (let z = 0; z < parts.length; z++) {
        const match = parts[z].trim().match(/(\d{1,2}):(\d{2})\s+\((\d)\)/);
        if (match) {
            const hours = parseInt(match[1], 10);
            const minutes = parseInt(match[2], 10);
            const state = parseInt(match[3], 10);
            const timeInMinutes = hours * 60 + minutes + (dayOffset * 24 * 60);
            events.push({ time: timeInMinutes, state });
        }
    }
    return events;
}

