// ====== SHAPE / LASTRECEIVE (selon TA structure eclairage.lastReceive) ======
function ensureEclairageShape(m) {
    if (!m.eclairage) m.eclairage = {};

    // lastSend (tes champs)
    if (m.eclairage.timestampLastSend === undefined) m.eclairage.timestampLastSend = 0;
    if (m.eclairage.dateLastSend === undefined) m.eclairage.dateLastSend = "";
    if (m.eclairage.ordreLastSend === undefined) m.eclairage.ordreLastSend = -1;
    if (m.eclairage.downlink === undefined) m.eclairage.downlink = "";
    if (m.eclairage.received === undefined) m.eclairage.received = false;
    if (m.eclairage.stateConfirmed === undefined) m.eclairage.stateConfirmed = false;

    // retry state
    if (m.eclairage.confirmationAttempts === undefined) m.eclairage.confirmationAttempts = 0;
    if (m.eclairage.overrideCooldownTimestamp === undefined) m.eclairage.overrideCooldownTimestamp = null;
    if (m.eclairage.retryDelayTimestamp === undefined) m.eclairage.retryDelayTimestamp = null;

    // lastReceive imbriqué (uplink)
    if (!m.eclairage.lastReceive) {
        m.eclairage.lastReceive = {
            "timestampLastReceive": 0,
            "dateLastReceive": "1970-01-01 00:00:00",
            "statutValue": null,
            "lastPayload": "",
            "lastUpdate": ""
        };
    } else {
        if (m.eclairage.lastReceive.timestampLastReceive === undefined) m.eclairage.lastReceive.timestampLastReceive = 0;
        if (m.eclairage.lastReceive.dateLastReceive === undefined) m.eclairage.lastReceive.dateLastReceive = "1970-01-01 00:00:00";
        if (m.eclairage.lastReceive.statutValue === undefined) m.eclairage.lastReceive.statutValue = null;
        if (m.eclairage.lastReceive.lastPayload === undefined) m.eclairage.lastReceive.lastPayload = "";
        if (m.eclairage.lastReceive.lastUpdate === undefined) m.eclairage.lastReceive.lastUpdate = "";
    }
}

function getEclairageLastReceiveTimestamp(m) {
    if (!m?.eclairage?.lastReceive) return 0;
    return Number(m.eclairage.lastReceive.timestampLastReceive) || 0;
}

function getEclairageLastReceiveStatutValue(m) {
    if (!m?.eclairage?.lastReceive) return undefined;
    const v = m.eclairage.lastReceive.statutValue;
    if (v === null || v === undefined) return undefined;
    return Number(v);
}


// ====== CONFIRMATION / RETRY / OVERRIDE ======
function checkMessageConfirmationEclairage(materiel, intervalRenvoiMs) {
    ensureEclairageShape(materiel);

    const lastSend = materiel.eclairage;
    const now = Date.now();

    const sendTs = Number(lastSend.timestampLastSend) || 0;
    const recvTs = getEclairageLastReceiveTimestamp(materiel);
    const recvValue = getEclairageLastReceiveStatutValue(materiel);

    // Sécurité: pas de lastReceive exploitable
    if (!recvTs) {
        return { confirmed: false, manualOverride: false, shouldRetry: false, inCooldown: false };
    }

    const isMoreRecent = recvTs > sendTs;
    const isMatching = (recvValue !== undefined)
        ? (Number(recvValue) === Number(lastSend.ordreLastSend))
        : false;

    // CAS 1: override manuel détecté (déjà confirmé, puis reçu différent)
    if (lastSend.received && lastSend.stateConfirmed && isMoreRecent && !isMatching) {
        if (!lastSend.overrideCooldownTimestamp) {
            lastSend.overrideCooldownTimestamp = now;
            return { confirmed: true, manualOverride: true, shouldRetry: false, inCooldown: true };
        }

        const elapsed = now - lastSend.overrideCooldownTimestamp;
        if (elapsed < intervalRenvoiMs) {
            return { confirmed: true, manualOverride: true, shouldRetry: false, inCooldown: true };
        } else {
            lastSend.overrideCooldownTimestamp = null;
            lastSend.confirmationAttempts = 0;
            return {
                confirmed: false,
                manualOverride: true,
                shouldRetry: true,
                inCooldown: false,
                triggerReason: "overrideCooldownExpired"
            };
        }
    }

    // CAS 2: confirmé (uplink + valeur match)
    if (isMoreRecent && isMatching) {
        lastSend.received = true;
        lastSend.stateConfirmed = true;
        lastSend.confirmationAttempts = 0;
        lastSend.overrideCooldownTimestamp = null;
        lastSend.retryDelayTimestamp = null;
        return { confirmed: true, manualOverride: false, shouldRetry: false, inCooldown: false };
    }

    // CAS 3: retry si nouvel uplink OU délai retry dépassé
    const timeSinceLastSend = now - sendTs;
    const newUplinkReceived = recvTs > sendTs;
    const retryDelayExceeded = timeSinceLastSend > RETRY_DELAY_MS;

    if (lastSend.confirmationAttempts < MAX_RETRY_ATTEMPTS && (newUplinkReceived || retryDelayExceeded)) {
        lastSend.confirmationAttempts++;
        return {
            confirmed: false,
            manualOverride: false,
            shouldRetry: true,
            inCooldown: false,
            triggerReason: newUplinkReceived ? "newUplink" : "retryDelayExceeded"
        };
    }

    // CAS 4: échec
    lastSend.received = false;
    lastSend.stateConfirmed = false;
    lastSend.overrideCooldownTimestamp = null;
    lastSend.retryDelayTimestamp = null;
    return { confirmed: false, manualOverride: false, shouldRetry: false, inCooldown: false, failed: true };
}


