║   Age:          ${String(ageSend).padStart(5, ' ')}s | Date: ${materielData.eclairage.dateLastSend}
║   OrdreLastSend:${String(materielData.eclairage.ordreLastSend).padStart(2, ' ')}
║   Interval:     ${String(intervalRenvoi).padStart(3, ' ')} min
║   Downlink:     ${materielData.eclairage.downlink !== "" ? materielData.eclairage.downlink : "Aucun"}
║   Received:     ${materielData.eclairage.received ? "✅" : "❌"} | StateConfirmed: ${materielData.eclairage.stateConfirmed ? "✅" : "❌"}
║   Attempts:     ${String(materielData.eclairage.confirmationAttempts).padStart(2, ' ')}/${MAX_RETRY_ATTEMPTS}
`;
    node.error(debugMsg2);

    // PART 2b lastReceive
    let debugMsg2b = `
║
║ 📥 LASTRECEIVE (eclairage.lastReceive):
`;
    if (lrTs) {
        debugMsg2b += `
║   Age:          ${String(ageRecv).padStart(5, ' ')}s | Timestamp: ${lrTs}
║   Date:         ${materielData.eclairage.lastReceive.dateLastReceive || "N/A"}
║   StatutValue:  ${lrVal !== undefined ? String(lrVal).padStart(2, ' ') : "N/A"}
║   Receive > Send:${lrTs > (materielData.eclairage.timestampLastSend || 0) ? "✅" : "❌"}
║   Match:        ${(lrVal !== undefined && lrVal === materielData.eclairage.ordreLastSend) ? "✅" : "❌"}
║   lastUpdate:   ${materielData.eclairage.lastReceive.lastUpdate || ""}
`;
    } else {
        debugMsg2b += `
║   Aucune réception enregistrée
`;
    }
    node.error(debugMsg2b);

    // PART 3 conditions
    let debugMsg3 = `
╠════════════════════════════════════════════════════════════════════╣
║ 🔗 CONDITIONS:
║ COND1 [Ordre changé OU Intervalle dépassé]
║ ├─ Ordre changé:        ${String(conditions.cond1.ordreChanged).padStart(5, ' ')}
║ ├─ Interval dépassé:    ${String(conditions.cond1.intervalExceeded).padStart(5, ' ')}
║ └─ RESULT:              ${conditions.cond1.result ? "✅ PASSE" : "❌ BLOQUÉE"}
`;
    node.error(debugMsg3);

    // PART 4 décisions + retry
    let debugMsg4 = `
╠════════════════════════════════════════════════════════════════════╣
║ 📤 DÉCISION:
║   Send normal: ${sendInfo.eclairage.send ? "✅" : "❌"}
║   Send retry:  ${sendInfo.retry.send ? "✅" : "❌"} (${sendInfo.retry.reason || "N/A"})
║
║ 📬 CONFIRM / RETRY:
`;
    if (confirmationCheck?.inCooldown) {
        const elapsed = Date.now() - (materielData.eclairage.overrideCooldownTimestamp || Date.now());
        const remaining = Math.ceil((intervalRenvoiMs - elapsed) / 1000);
        debugMsg4 += `║   ⏳ Cooldown override (~${remaining}s)\n`;
    } else if (confirmationCheck?.confirmed) {
        debugMsg4 += `║   ✅ Confirmé (match uplink)\n`;
    } else if (confirmationCheck?.shouldRetry) {
        debugMsg4 += `║   🔄 ShouldRetry (${confirmationCheck.triggerReason}) attempts=${materielData.eclairage.confirmationAttempts}/${MAX_RETRY_ATTEMPTS}\n`;
    } else if (confirmationCheck?.failed) {
        debugMsg4 += `║   ❌ Échec (MAX attempts)\n`;
    } else {
        debugMsg4 += `║   ⏸️  Pas de retry\n`;
    }

    debugMsg4 += `
║
║ 🔧 CONTEXTE:
║   Gestion éclairage: ${gestionEclairage.deactivateGestionEclairage === 0 ? "❌ Désactivée (ENVOI ACTIF)" : "🔒 Activée (BLOQUÉ)"}
║   Sortie valide:     ${sortie >= 0 && sortie <= 7 ? "✅ OUI" : "❌ NON"}
╚════════════════════════════════════════════════════════════════════╝`;

    node.error(debugMsg4);
}


// ====== BOUCLE PRINCIPALE SUR LES MATÉRIELS ======
for (let i = 0; i < materiels.length; i++) {
    let m = materiels[i];
    if (m.type !== "SLC_E") continue;

    ensureEclairageShape(m);

    let planningIndex = plannings_e.findIndex(p => p.id == m.plannings_e_id);
    if (planningIndex === -1) continue;

    let planning = plannings_e[planningIndex];
    let dayKeyToday = "day" + dayOfWeek;
    let todaySchedule = planning[dayKeyToday];
    let todayEvents = parseSchedule(todaySchedule);

    // état courant
    let currentState = 0;
    for (let j = 0; j < todayEvents.length; j++) {
        let e = todayEvents[j];
        let eNext = todayEvents[j + 1] || { time: Infinity, state: e.state };
        if (currentTime >= e.time && currentTime < eNext.time) {
            currentState = e.state;
            break;
        }
    }

    // ordre inversé (comme ton code)
    let ordreToSend = currentState === 1 ? 0 : 1;

    // ====== CALCUL CONDITIONS ======
    const timeDiff = Date.now() - (m.eclairage.timestampLastSend || 0);
    const timeDiffSeconds = Math.floor(timeDiff / 1000);
    const intervalMs = intervalRenvoi * 60 * 1000;
    const intervalRenvoiMs = intervalMs;

    const cond1_ordreChanged = m.eclairage.ordreLastSend !== ordreToSend;
    const cond1_intervalExceeded = timeDiff > intervalMs;
    const cond1_result = cond1_ordreChanged || cond1_intervalExceeded;

    // ====== CONFIRMATION / RETRY ======
    const confirmationCheck = checkMessageConfirmationEclairage(m, intervalRenvoiMs);
    const shouldSendForRetry = confirmationCheck.shouldRetry && !confirmationCheck.inCooldown;

    // délai avant envoi retry
    let canSendRetry = true;
    if (shouldSendForRetry) {
        if (!m.eclairage.retryDelayTimestamp) {
            m.eclairage.retryDelayTimestamp = Date.now();
            canSendRetry = false;
        } else {
            const elapsed = Date.now() - m.eclairage.retryDelayTimestamp;
            canSendRetry = elapsed >= RETRY_SEND_DELAY_MS;
        }
    } else {
        m.eclairage.retryDelayTimestamp = null;
    }

    // sendInfo (normal + retry)
    let sendInfo = {
        eclairage: { send: false, changed: false, intervalExceeded: false },
        retry: { send: false, reason: "" }
    };

    // ====== Décision d'envoi : NORMAL ou RETRY ======
    const shouldSendNormal = cond1_result;
    const shouldSendRetryNow = shouldSendForRetry && canSendRetry;

    if (shouldSendNormal || shouldSendRetryNow) {
        let devEUI = m.deveui;
        if (!commandesParDevice[devEUI]) {
            commandesParDevice[devEUI] = { mask: 0, status: 0, indexMateriel: [], ordres: [], isRetry: [] };
        }

        const sortie = m.sortie - 1;
        if (sortie < 0 || sortie >= 8) continue;

        let bit = tabConvertion[sortie];
        commandesParDevice[devEUI].mask |= bit;

        if (ordreToSend === 1) commandesParDevice[devEUI].status |= bit;

        commandesParDevice[devEUI].indexMateriel.push(i);
        commandesParDevice[devEUI].ordres.push(ordreToSend);

        // flag retry par item (si pas d'envoi normal et que c'est bien un retry)
        const isRetryItem = (!shouldSendNormal && shouldSendRetryNow);
        commandesParDevice[devEUI].isRetry.push(isRetryItem);

        if (shouldSendNormal) {
            sendInfo.eclairage = { send: true, changed: cond1_ordreChanged, intervalExceeded: cond1_intervalExceeded };
        } else {
            sendInfo.retry = { send: true, reason: confirmationCheck.triggerReason || "retry" };
        }
    }

    // ====== DEBUG ======
    logEclairageDebug(
        m,
        planning,
        { currentState, ordreToSend },
        sendInfo,
        {
            cond1: {
                ordreChanged: cond1_ordreChanged,
                intervalExceeded: cond1_intervalExceeded,
                timeDiff: timeDiffSeconds,
                result: cond1_result
            }
        },
        confirmationCheck,
        intervalRenvoiMs,
        todaySchedule,
        todayEvents
    );
}


// ====== ENVOI DES DOWNLINKS REGROUPÉS ======
for (let dev in commandesParDevice) {
    let { mask, status, indexMateriel, ordres, isRetry } = commandesParDevice[dev];

    let hex = `08${mask.toString(16).padStart(2, '0')}${status.toString(16).padStart(2, '0')}`;
    let base64 = createMessageBase64(hex);

    // Mettre à jour les matériels
    for (let j = 0; j < indexMateriel.length; j++) {
        let i = indexMateriel[j];
        ensureEclairageShape(materiels[i]);

        const wasRetry = !!isRetry[j];

        // ✅ on ne touche pas à eclairage.lastReceive (uplink)
        materiels[i].eclairage.timestampLastSend = Date.now();
        materiels[i].eclairage.dateLastSend = getDateString();
        materiels[i].eclairage.ordreLastSend = ordres[j];
        materiels[i].eclairage.downlink = hex;

        materiels[i].eclairage.received = false;
        materiels[i].eclairage.stateConfirmed = false;

        // retry state
        materiels[i].eclairage.confirmationAttempts = wasRetry
            ? (materiels[i].eclairage.confirmationAttempts || 0)
            : 0;

        materiels[i].eclairage.retryDelayTimestamp = null;
        materiels[i].eclairage.overrideCooldownTimestamp = materiels[i].eclairage.overrideCooldownTimestamp || null;
    }

    if (gestionEclairage.deactivateGestionEclairage == 0) {
        node.status({ fill: "green", shape: "dot", text: `SLC_E ${dev} -> ${hex}` });
        setTimeout(() => node.status({}), 5000);

        node.send({
            url: `https://localhost:8080/api/devices/${dev}/queue`,
            headers: msg.headers,
            rejectUnauthorized: false,
            payload: base64
        });
    } else {
        node.status({ fill: "yellow", shape: "dot", text: `Mode MAINTENANCE: SLC_E ${dev}` });
    }
}

global.set("materiels", materiels);


// --- Fonctions utilitaires ---
function createMessageBase64(hexString) {
    const buffer = Buffer.from(hexString, 'hex');
    return {
        confirmed: false,
        fPort: 85,
        data: buffer.toString('base64')
    };
}

function getDateString() {
    let now = new Date();
    let year = now.getFullYear();
    let month = String(now.getMonth() + 1).padStart(2, '0');
    let day = String(now.getDate()).padStart(2, '0');
    let hours = String(now.getHours()).padStart(2, '0');
    let minutes = String(now.getMinutes()).padStart(2, '0');
    let seconds = String(now.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

function parseSchedule(schedule) {
    let events = [];
    if (!schedule || typeof schedule !== "string") return events;

    let parts = schedule.split(";");
    for (let part of parts) {
        let match = part.trim().match(/(\d{1,2}):(\d{2})\s+\((\d)\)/);
        if (match) {
            let h = parseInt(match[1], 10);
            let m = parseInt(match[2], 10);
            let state = parseInt(match[3], 10);
            events.push({ time: h * 60 + m, state });
        }
    }
    return events;
}

