let zones = global.get("zones");
let materiels = global.get("materiels");
let nbMaxSaveDataRead = global.get("nbMaxSaveDataRead");
let addressIP = flow.get("addressIPCoolinkhub01");
msg.filename = "coolinkhub01.json";
let dns = global.get("dns");
let newObject;
let keyZones = -1;
let addressRead = 0;
let dataToSend = [];
// Pour le mode COOLAUTOMATION 0=Cool / 1=Heat / 2=Auto / 3=Dry / 4=Haux / 5=Fan
// Pour le mode Semautomation 0=Auto / 1=Heat / 2=Cool / 3=Ventilation
let tabConversionModeCOOL_SEM = flow.get("tabConversionModeCOOL_SEM");
let tabConversionModeSEM_COOL = flow.get("tabConversionModeSEM_COOL");

let tabReadValueCoolautomation = ["mode", "ventilation", "consigne", "allumage", "filter", "ailette", "temperature"];

for (let x = 0; x < materiels.length; x++) {
    addressRead = msg.modbusRequest.address;
    if (materiels[x].type == 'COOLINKHUB' && materiels[x].ip == addressIP && materiels[x].address == addressRead) {
        keyZones = -1;
        for (let y = 0; y < zones.length; y++) {
            if (zones[y].numero == materiels[x].numero) {
                keyZones = y;
            }
        }
        if (keyZones != -1) {
            // 0=Mode Clim / 1=Vitesse Ventilation / 2=Consigne / 3=allumage / 4=Filter Sign / 5=Rotation Ailette / 6=Temp. ambiante
            if (msg.payload[0] <= 5) {
                zones[keyZones].data.statusMode.value = tabConversionModeCOOL_SEM[msg.payload[0]];
            } else {
                zones[keyZones].data.statusMode.value = 0;
            }
            zones[keyZones].data.statusMode.timestamp = Date.now();
            zones[keyZones].data.statusMode.date = getDateString();
            zones[keyZones].data.statusConsigne.value = msg.payload[2] / 10;
            zones[keyZones].data.statusConsigne.timestamp = Date.now();
            zones[keyZones].data.statusConsigne.date = getDateString();
            zones[keyZones].data.statusAllumage.value = msg.payload[3];
            zones[keyZones].data.statusAllumage.timestamp = Date.now();
            zones[keyZones].data.statusAllumage.date = getDateString();
            if (zones[keyZones].sourceTemp == 1) { // cas où la source de température est coolautomation
                zones[keyZones].data.temp.value = msg.payload[6] / 10;
                zones[keyZones].data.temp.timestamp = Date.now();
                zones[keyZones].data.temp.date = getDateString();
            }
        }

        // Constuction de l'IP extérieure
        let ip1Match = dns.match(/^(\d+\.\d+\.\d+)/);
        let ip1Result = ip1Match ? ip1Match[1] : "Aucune correspondance";
        let ip2Match = addressIP.match(/(\d+):(\d+)$/);
        let ip2Result = ip2Match ? `${ip2Match[1]}:${ip2Match[2]}` : "Aucune correspondance";
        let materielIP = ip1Result + '.' + ip2Result;

        // Enregistrement des données dans materiels
        newObject = {
            "timestamp": Date.now(),
            "date": getDateString(),
            "ip": materielIP,
            "num_zone": materiels[x].numero,
            "unitId": 1,
            "register": materiels[x].address,
            "key": x,
            "mode": msg.payload[0],
            "ventilation": msg.payload[1],
            "consigne": msg.payload[2] / 10,
            "allumage": msg.payload[3],
            "filterSign": msg.payload[4],
            "ailette": msg.payload[5],
            "temp": msg.payload[6] / 10
        };

        // Ajout des donnnées au tableau
        for (let j = 0; j < tabReadValueCoolautomation.length; j++) {
            let register = Number(addressRead) + j;
            let value = msg.payload[j];
            if (j == 2 || j == 6) {
                value = msg.payload[j] / 10;
            }
            dataToSend.push({
                "timestamp": Date.now(),
                "date": getDateString(),
                "ip": materielIP,
                "num_zone": materiels[x].numero,
                "unitId": 1,
                "register": register,
                "type": tabReadValueCoolautomation[j],
                "value": value,
            });
        }
        break;
    }
}

