    if (mat.type === "THZ" && mat.host === addressIP) {

        // Recherche de la zone associée
        let keyZones = -1;
        for (let y = 0; y < zones.length; y++) {
            if (zones[y].numero == mat.numero) {
                keyZones = y;
                break;
            }
        }

        // On ne lit que si la zone correspondante existe
        if (keyZones === -1) {
            continue;
