if (Array.isArray(msg.payload)) {
    values = msg.payload;
} else if (msg.payload && Array.isArray(msg.payload.data)) {
    values = msg.payload.data;
} else {
    node.error("Format de msg.payload inattendu pour la réponse Modbus", msg);
    return null;
}

if (!values.length) {
    node.error("msg.payload ne contient aucune valeur Modbus", msg);
    return null;
}

let rawValue = values[0];
let register = Number(msg.modbusRequest.address);
let unitId =
    (typeof msg.modbusRequest.unitId !== "undefined") ? msg.modbusRequest.unitId :
        (typeof msg.modbusRequest.unitid !== "undefined") ? msg.modbusRequest.unitid : 1;

let ts = Date.now();
let dateStr = getDateString();

// ---------- 1) Trouver le bon matériel THZ + datapoint ----------
let mat = null;
let datapoint = null;

for (let i = 0; i < materiels.length; i++) {
    let m = materiels[i];

    if (m.type !== "THZ" || !Array.isArray(m.datapoints)) continue;

    for (let d = 0; d < m.datapoints.length; d++) {
        let dp = m.datapoints[d];
        if (!dp || dp.protocol !== "modbus" || !dp.config) continue;

        let dpSlave = Number(dp.config.slave ?? 1);
        let dpReg = Number(dp.config.register);

        if (dpSlave === unitId && dpReg === register) {
            mat = m;
            datapoint = dp;
            break;
        }
    }

    if (mat && datapoint) break;
}

if (!mat || !datapoint) {
    node.warn("Aucun THZ/datapoint correspondant trouvé pour unitId=" + unitId + " register=" + register);
    return null;
}

