let keyZones = -1;
for (let y = 0; y < zones.length; y++) {
    if (zones[y].numero == mat.numero) {
        keyZones = y;
        break;
    }
}

if (keyZones === -1) {
    node.warn("Aucune zone associée au matériel THZ numero=" + mat.numero);
    return null;
}

let z = zones[keyZones];
if (!z.data) z.data = {};

