let host = mat.host || "";  // ex: "192.168.0.77:10001"
let ip1Match = dns.match(/^(\d+\.\d+\.\d+)/); // ex "10.1.210.150" -> "10.1.210"
let ip1Result = ip1Match ? ip1Match[1] : "Aucune correspondance";

let ip2Match = host.match(/(\d+):(\d+)$/);    // "192.168.0.77:10001" -> "77:10001"
let ip2Result = ip2Match ? `${ip2Match[1]}:${ip2Match[2]}` : host;

let materielIP = ip1Result + "." + ip2Result;

