let value = rawValue / divisor;

// Mapping pour le champ "type" dans le log
let typeName = "valeur";
switch (datapointType) {
    case "Tcons":
        typeName = "consigne";
        break;
    case "Tamb":
        typeName = "temperature";
        break;
    case "Regul":
        typeName = "regulation";
        break;
    case "ouvertV2V":
        typeName = "ouvertV2V";
        break;
    default:
        typeName = datapointType || "valeur";
        break;
}

