if (datapointType === "Tcons") {
    if (!z.data.statusConsigne) z.data.statusConsigne = {};
    if (!z.data.statusAllumage) z.data.statusAllumage = {};

    z.data.statusConsigne.value = value;
    z.data.statusConsigne.timestamp = ts;
    z.data.statusConsigne.date = dateStr;

    if (z.data.consigneTorZone !== undefined) {
        z.data.statusAllumage.value = z.data.consigneTorZone;
    }
    z.data.statusAllumage.timestamp = ts;
    z.data.statusAllumage.date = dateStr;

} else if (datapointType === "Tamb") {
    if (z.sourceTemp == 3) {
        if (!z.data.temp) z.data.temp = {};
        z.data.temp.value = value;
        z.data.temp.timestamp = ts;
        z.data.temp.date = dateStr;
    }
}

// Tous les datapoints (y compris nouveaux) sont stockés brut dans zones[x].data[datapointType]
