        let register = Number(regulDp.config.register);

        let consigneTorZone = Number(zones[keyZones].data.consigneTorZone);
        node.warn("THZ SEND – PREP envoi Regul zone=" + zones[keyZones].numero +
            " consigneTorZone=" + consigneTorZone +
            " unitid=" + unitid + " register=" + register);

        let msgOut = {
            payload: {
                value: Math.floor(consigneTorZone * 100),
                fc: 6,
                unitid: unitid,
                address: register,
                quantity: 1
            }
        };

        if (actionMaintenance == 0) {
            node.warn("THZ SEND – ENVOI Modbus");
            node.send(msgOut);
        } else {
            node.warn("THZ SEND – PAS D’ENVOI (maintenance active)");
        }
    }
}

