        if (zones[keyZones].activationRegul !== 1) {
            node.warn(zones[keyZones].activationRegul);
            node.warn("THZ SEND – regul désactivée pour zone=" + zones[keyZones].numero);
            continue;
        }

        // Cherche le datapoint Regul
        let regulDp = null;
        if (Array.isArray(mat.datapoints)) {
            for (let d = 0; d < mat.datapoints.length; d++) {
                let dp = mat.datapoints[d];
                if (!dp || dp.protocol !== "modbus" || !dp.config) continue;

