function performModbusRead() {
    // ✅ Afficher message de démarrage UNIQUEMENT si debug activé
    if (DEBUG_CONFIG.ENABLED && DEBUG_CONFIG.MODE !== "none") {
        node.warn(`[DEBUG] Démarrage lecture UC300_01 - Mode: ${DEBUG_CONFIG.MODE}`);
    }

    // ✅ Compter d'abord le nombre total de matériels INTESIS
    let totalIntesisCount = 0;
    for (let x = 0; x < materiels.length; x++) {
        if (materiels[x].type == 'INTESIS' && materiels[x].ip == addressIP) {
            totalIntesisCount++;
        }
    }

    if (totalIntesisCount === 0) {
        node.status({
            fill: "red",
            shape: "ring",
            text: "❌ Aucun matériel INTESIS UC300_01 trouvé"
        });

        // ✅ Afficher erreur UNIQUEMENT si debug activé
        if (DEBUG_CONFIG.ENABLED && DEBUG_CONFIG.MODE !== "none") {
            node.error("Aucun matériel INTESIS trouvé pour l'IP: " + addressIP);
        }
        return;
    }

    const messageModbus = {
        "fc": 3,                // Fonction 3 = Lecture registres
        "unitid": 1,            // ID par défaut
        "address": 0,           // Commence à adresse 0
        "quantity": 6           // Lit 6 registres
    };

    // ✅ BOUCLER SUR TOUS LES MATÉRIELS (PAS DE RETURN!)
    for (let x = 0; x < materiels.length; x++) {
        if (materiels[x].type == 'INTESIS' && materiels[x].ip == addressIP) {
            keyZones = -1;

            // ✅ Recherche de la zone correspondante
            for (let y = 0; y < zones.length; y++) {
                if (Number(zones[y].numero) === Number(materiels[x].numero)) {
                    keyZones = y;
                    break;  // ✅ Sortir de la boucle de zone
                }
            }

            // ✅ Si zone trouvée, envoyer la lecture
            if (keyZones != -1) {
                readCount++;  // ✅ Incrémenter le compteur

                // ✅ Ajouter la zone à la liste
                zonesLues.push({
                    numero: materiels[x].numero,
                    unitid: materiels[x].address
                });

                messageModbus.unitid = materiels[x].address;
                messageModbus.timestamp = Date.now();
                messageModbus.ip = addressIP;

                msg.payload = messageModbus;
                msg.topic = "modbusRead";

                // ✅ Log de démarrage de la lecture (avec filtre debug)
                logReadDebug(materiels[x], true, "", readCount, totalIntesisCount);

                node.status({
                    fill: "blue",
                    shape: "dot",
                    text: `📖 Lecture ${readCount}/${totalIntesisCount} UC300_01 - Zone ${materiels[x].numero} (UnitID: ${materiels[x].address})`
                });

                node.send(msg);
                // ✅ PAS DE RETURN - CONTINUER LA BOUCLE!  
            }
        }
    }

    // ✅ Afficher le résumé final UNIQUEMENT si debug activé ET au moins une zone trouvée
    if (readCount > 0) {
        // Créer une liste formatée des zones
        let zonesStr = zonesLues.map(z => `Zone ${z.numero} (UnitID: ${z.unitid})`).join(" | ");

        // ✅ Afficher message UNIQUEMENT si debug activé
        if (DEBUG_CONFIG.ENABLED && DEBUG_CONFIG.MODE !== "none") {
            node.warn(`[Lectures lancées] Total:  ${readCount} matériel(s) UC300_01 | ${zonesStr}`);
        }
    } else {
        // ✅ Afficher message d'aucune zone UNIQUEMENT si debug activé
        if (DEBUG_CONFIG.ENABLED && DEBUG_CONFIG.MODE !== "none") {
            node.warn("[Lectures] Aucune zone trouvée pour UC300_01");
        }
    }
}

