let eventRestoreStateFile = flow.get("eventRestoreStateFileCoolmaster02") || "/snapshot_intersaison_coolmaster02.json";
let eventRestoreStateChanged = false;
const DEBUG_ENABLED = false;
const DEBUG_FILTER = {
