                            : !eventForcesMode && eventWasForcingMode && currentSeasonIndex === 0
                                ? 0
                            : modeClimZone;
                    const modeLastSendExpired = compareTimestamp(Date.now(), lastSend.timestampLastSend, intervalRenvoi);
                    const mustResendMode =
                        mustHandleEventModeTransition ||
                        lastSend.modeClimLastSend !== modeCommandValue ||
                        modeLastSendExpired;

                    if (mustResendMode) {
                        if (
                            mustHandleEventModeTransition ||
                            statusMode !== modeCommandValue ||
                            modeLastSendExpired
                        ) {
                            const modePayloadValue = tabConversionModeSEM_COOL[modeCommandValue];

                            // 0=Mode Clim / 1=Vitesse Ventilation / 2=Consigne / 3=allumage / 4=Filter Sign / 5=Rotation Ailette / 6=Temp. ambiante
                            msg.payload = {
                                value: modePayloadValue,
                                fc: 6,
                                unitid: 1,
                                address: materiels[i].address + 0,
                                quantity: 1
                            };

                            if (actionMaintenance == 0) {
                                debugSend(zone, materiels[i], "mode", modeCommandValue, {
                                    reason: getModeReason(restorePreEventSnapshot, eventForcesMode, eventWasForcingMode, currentSeasonIndex, lastSend.modeClimLastSend, modeCommandValue, modeLastSendExpired),
                                    statusValue: statusMode,
                                    rawValue: modeCommandValue,
                                    payloadValue: modePayloadValue,
                                    computedModeValue: modeClimZone,
                                    snapshotModeBeforeEvent: snapshotModeBeforeEvent,
                                    seasonIndex: currentSeasonIndex,
                                    seasonalitySource: resolution.seasonality ? resolution.seasonality.source : null,
                                    eventWasForcingMode: eventWasForcingMode
                                });
                                isMsgSend = true;
                                node.send([msg, null]);
                            } else {
                                debugBlocked(zone, materiels[i], "mode", modeCommandValue, "MAINTENANCE");
                            }
                        } else {
                            debugSkipped(zone, materiels[i], "mode", modeCommandValue, {
                                reason: "STATUS_ALREADY_ALIGNED",
                                statusValue: statusMode,
                                lastSendValue: lastSend.modeClimLastSend,
                                computedModeValue: modeClimZone,
                                seasonIndex: currentSeasonIndex,
                                seasonalitySource: resolution.seasonality ? resolution.seasonality.source : null,
                                eventWasForcingMode: eventWasForcingMode
                            });
                        }
                    } else {
                        debugSkipped(zone, materiels[i], "mode", modeCommandValue, {
                            reason: "LAST_SEND_ALREADY_ALIGNED",
                            statusValue: statusMode,
                            lastSendValue: lastSend.modeClimLastSend,
                            computedModeValue: modeClimZone,
                            seasonIndex: currentSeasonIndex,
                            seasonalitySource: resolution.seasonality ? resolution.seasonality.source : null,
                            eventWasForcingMode: eventWasForcingMode
                        });
                    }
                } else {
                    debugSkipped(zone, materiels[i], "mode", modeClimZone, {
                        reason: "GESTION_MODE_DISABLED",
                        statusValue: statusMode,
                        lastSendValue: lastSend.modeClimLastSend,
                        seasonalitySource: resolution.seasonality ? resolution.seasonality.source : null,
                        eventWasForcingMode: eventWasForcingMode
                    });
                }

                const restoreSnapshotSatisfied =
                    restorePreEventSnapshot &&
                    actionMaintenance == 0 &&
                    (snapshotModeBeforeEvent === null || statusMode === (snapshotModeBeforeEvent !== null ? snapshotModeBeforeEvent : modeClimZone)) &&
                    (snapshotConsigneBeforeEvent === null || statusConsigne === consigneCommandValue);

                if (restoreSnapshotSatisfied && eventRestoreState[restoreKey]) {
                    delete eventRestoreState[restoreKey];
                    eventRestoreStateChanged = true;
                }

                if (isMsgSend) {
                    listChangeMaterielsId.push({
                        key: i,
                        data: {
                            timestampLastSend: Date.now(),
                            dateLastSend: getDateString(),
                            modeClimLastSend: restorePreEventSnapshot && snapshotModeBeforeEvent !== null
                                ? snapshotModeBeforeEvent
                                : !eventForcesMode && eventWasForcingMode && currentSeasonIndex === 0
                                    ? 0
                                    : modeClimZone,
                            consigneClimLastSend: consigneCommandValue,
                            pilotageClimLastSend: pilotageClimZone,
                            eventModeOverrideLastSend: eventForcesMode,
                            consigneTorLastSend: "",
                            pilotageTorLastSend: "",
                            downlink: "",
                            received: false
                        }
                    });
                }
            }
        }
    }
}

for (let z = 0; z < listChangeMaterielsId.length; z++) {
    let key = listChangeMaterielsId[z].key;
    materiels[key].lastSend = listChangeMaterielsId[z].data;
