function getPilotageReason(lastValue, nextValue, intervalExpired) {
    if (lastValue !== nextValue) {
        return "LAST_SEND_CHANGED";
    }
    if (intervalExpired) {
        return "INTERVAL_RENVOI";
    }
    return "UNKNOWN";
}

function getConsigneReason(restorePreEventSnapshot, lastValue, nextValue, intervalExpired) {
    if (restorePreEventSnapshot) {
        return "EVENT_INTERSEASON_RESTORE";
    }
    if (lastValue !== nextValue) {
        return "LAST_SEND_CHANGED";
    }
    if (intervalExpired) {
        return "INTERVAL_RENVOI";
    }
    return "UNKNOWN";
}

function getModeReason(restorePreEventSnapshot, eventForcesMode, eventWasForcingMode, seasonIndex, lastValue, nextValue, intervalExpired) {
    if (eventForcesMode) {
        return "EVENT_SEASONALITY_ACTIVE";
    }
    if (restorePreEventSnapshot) {
        return "EVENT_INTERSEASON_RESTORE";
    }
    if (!eventForcesMode && eventWasForcingMode) {
        if (seasonIndex === 0) {
            return "EVENT_SEASONALITY_ENDED_TO_AUTO";
        }
        return "EVENT_SEASONALITY_ENDED";
    }
    if (lastValue !== nextValue) {
        return "LAST_SEND_CHANGED";
    }
    if (intervalExpired) {
        return "INTERVAL_RENVOI";
    }
    return "UNKNOWN";
}

function pickSnapshotValue(...values) {
    for (let i = 0; i < values.length; i++) {
        const value = Number(values[i]);
        if (!Number.isNaN(value)) {
            return value;
        }
    }
    return null;
}

function buildRestoreKey(materiel, zone) {
    const ip = materiel && materiel.ip ? String(materiel.ip) : "noip";
    const address = materiel && materiel.address !== undefined ? String(materiel.address) : "noaddress";
    const zoneId = zone && zone.id !== undefined ? String(zone.id) : "nozone";
    return `${ip}:${address}:${zoneId}`;
}

function shouldDebugZone(zone, materiel) {
    if (!DEBUG_ENABLED) {
        return false;
    }

    const mode = (DEBUG_FILTER.by || "").toLowerCase();
    const values = Array.isArray(DEBUG_FILTER.values) ? DEBUG_FILTER.values : null;
    const rx = DEBUG_FILTER.regex ? new RegExp(DEBUG_FILTER.regex, "i") : null;

    if (!values && !rx) {
        return true;
    }

    switch (mode) {
        case "numero":
            return values ? values.indexOf(Number(zone.numero)) !== -1 : true;
        case "zoneid":
            return values ? values.indexOf(Number(zone.id)) !== -1 : true;
        case "nom":
            if (rx) {
                return rx.test(String(zone.nom || ""));
            }
            if (values) {
                return values.indexOf(String(zone.nom || "")) !== -1;
            }
            return true;
        case "address":
            return values ? values.indexOf(Number(materiel.address)) !== -1 : true;
        default:
            return true;
    }
}

let zones = global.get("zones");
let materiels = global.get("materiels");
let params = global.get("params");
let intervalRenvoi = flow.get("intervalRenvoiCOOL");
let addressIP = flow.get("addressIPCoolinkhub01");
let actionMaintenance = global.get("actionMaintenance");
let eventRestoreState = flow.get("eventRestoreStateCoolinkhub01") || {};
let eventRestoreStateFile = flow.get("eventRestoreStateFileCoolinkhub01") || "/snapshot_intersaison_coolinkhub01.json";
let eventRestoreStateChanged = false;
const DEBUG_ENABLED = false;
const DEBUG_FILTER = {
    by: "numero", // "numero" | "zoneId" | "nom" | "address"
    values: null,
    regex: null
};

// Pour le mode COOLAUTOMATION 0=Cool / 1=Heat / 2=Auto / 3=Dry / 4=Haux / 5=Fan
// Pour Semautomation 0=Auto / 1=Heat / 2=Cool / 3=Ventilation
let tabConversionModeCOOL_SEM = flow.get("tabConversionModeCOOL_SEM");
let tabConversionModeSEM_COOL = flow.get("tabConversionModeSEM_COOL");

let listChangeMaterielsId = [];
let keyZones = -1;
let isMsgSend = false;

for (let i = 0; i < materiels.length; i++) {
    if (materiels[i].type == "COOLINKHUB" && materiels[i].ip == addressIP) {
        keyZones = -1;

        for (let y = 0; y < zones.length; y++) {
            if (zones[y].numero == materiels[i].numero) {
                keyZones = y;
            }
        }

        if (keyZones != -1) {
            const zone = zones[keyZones];
            const data = zone.data || {};
            const resolution = data.resolution || {};
            const lastSend = materiels[i].lastSend || {};
            const restoreKey = buildRestoreKey(materiels[i], zone);
            let restoreState = eventRestoreState[restoreKey] || null;

            // Si la saisonnalite est imposee par un evenement, le mode doit etre
            // pris en compte jusqu'au noeud d'envoi. La sortie d'evenement doit
            // aussi etre forcee pour remettre l'equipement dans son mode normal.
            // Le mode maintenance continue, lui, a bloquer les emissions.
            const eventForcesMode =
                resolution.seasonality &&
                resolution.seasonality.source === "EVENT";
            const eventWasForcingMode = restoreState !== null;
            const enteringEventOverride = eventForcesMode && !eventWasForcingMode;
            const mustHandleEventModeTransition = eventForcesMode || eventWasForcingMode;

            // on teste si la regul est activee pour cette zone
            if (zone.activationRegul == true) {
                const pilotageClimZone = Number(data.pilotageClimZone);
                const consigneClimZone = Number(data.consigneClimZone);
                const modeClimZone = Number(data.modeClimZone);
                const currentSeasonIndex = Number(data._saisonIndex);
                const statusAllumage = data.statusAllumage ? data.statusAllumage.value : undefined;
                const statusConsigne = data.statusConsigne ? Number(data.statusConsigne.value) : undefined;
                const statusMode = data.statusMode ? Number(data.statusMode.value) : undefined;
                if (enteringEventOverride) {
                    restoreState = {
                        zoneId: zone.id,
                        zoneNumero: zone.numero,
                        materialAddress: materiels[i].address,
                        addressIP: materiels[i].ip,
                        capturedAt: Date.now(),
                        preEventModeValue: pickSnapshotValue(lastSend.modeClimLastSend, statusMode),
                        preEventConsigneValue: pickSnapshotValue(lastSend.consigneClimLastSend, statusConsigne)
                    };
                    eventRestoreState[restoreKey] = restoreState;
                    eventRestoreStateChanged = true;
                }

                const snapshotModeBeforeEvent = restoreState ? pickSnapshotValue(restoreState.preEventModeValue) : null;
                const snapshotConsigneBeforeEvent = restoreState ? pickSnapshotValue(restoreState.preEventConsigneValue) : null;
                const restorePreEventSnapshot =
                    !eventForcesMode &&
                    eventWasForcingMode &&
                    currentSeasonIndex === 0 &&
                    (snapshotModeBeforeEvent !== null || snapshotConsigneBeforeEvent !== null);
                const consigneCommandValue =
                    restorePreEventSnapshot && snapshotConsigneBeforeEvent !== null
                        ? snapshotConsigneBeforeEvent
                        : consigneClimZone;

                isMsgSend = false;

                if (zone.allumageManuel == false) {
                    // On envoie un ordre uniquement si celui-ci vient de changer ou si on a depasse l'intervalle defini
                    const pilotageLastSendExpired = compareTimestamp(Date.now(), lastSend.timestampLastSend, intervalRenvoi);
                    if (
                        lastSend.pilotageClimLastSend !== pilotageClimZone ||
                        pilotageLastSendExpired
                    ) {
                        if (
                            statusAllumage !== pilotageClimZone ||
                            pilotageLastSendExpired
                        ) {
                            if (
                                zone.occupationPermanente == true ||
                                pilotageLastSendExpired
                            ) {
                                // 0=Mode Clim / 1=Vitesse Ventilation / 2=Consigne / 3=allumage / 4=Filter Sign / 5=Rotation Ailette / 6=Temp. ambiante
                                msg.payload = {
                                    value: pilotageClimZone,
                                    fc: 6,
                                    unitid: 1,
                                    address: materiels[i].address + 3,
                                    quantity: 1
                                };

                                if (actionMaintenance == 0) {
                                    debugSend(zone, materiels[i], "pilotage", pilotageClimZone, {
                                        reason: getPilotageReason(lastSend.pilotageClimLastSend, pilotageClimZone, pilotageLastSendExpired),
                                        statusValue: statusAllumage,
                                        rawValue: pilotageClimZone,
                                        payloadValue: pilotageClimZone,
                                        eventSeasonalitySource: resolution.seasonality ? resolution.seasonality.source : null
                                    });
                                    isMsgSend = true;
                                    node.send([msg, null]);
                                } else {
                                    debugBlocked(zone, materiels[i], "pilotage", pilotageClimZone, "MAINTENANCE");
                                }
                            }
                        }
                    }
                }

                // La consigne n'est pas forcee par la source EVENT :
                // si elle change, le comportement existant suffit.
                const consigneLastSendExpired = compareTimestamp(Date.now(), lastSend.timestampLastSend, intervalRenvoi);
                const mustResendConsigne =
                    restorePreEventSnapshot ||
                    lastSend.consigneClimLastSend !== consigneCommandValue ||
                    consigneLastSendExpired;
                if (
                    mustResendConsigne
                ) {
                    if (
                        restorePreEventSnapshot ||
                        statusConsigne !== consigneCommandValue ||
                        consigneLastSendExpired
                    ) {
                        // 0=Mode Clim / 1=Vitesse Ventilation / 2=Consigne / 3=allumage / 4=Filter Sign / 5=Rotation Ailette / 6=Temp. ambiante
                        let valueToSend = Math.floor(consigneCommandValue * 10);
                        if (consigneCommandValue < 16) {
                            valueToSend = 160;
                        }

                        msg.payload = {
                            value: valueToSend,
                            fc: 6,
                            unitid: 1,
                            address: materiels[i].address + 2,
                            quantity: 1
                        };

                        if (actionMaintenance == 0) {
                            debugSend(zone, materiels[i], "consigne", consigneCommandValue, {
                                reason: getConsigneReason(restorePreEventSnapshot, lastSend.consigneClimLastSend, consigneCommandValue, consigneLastSendExpired),
                                equipmentValue: statusConsigne,
                                rawValue: consigneCommandValue,
                                payloadValue: valueToSend,
                                computedConsigneValue: consigneClimZone,
                                snapshotConsigneBeforeEvent: snapshotConsigneBeforeEvent,
                                eventConsigneSource: resolution.consigne ? resolution.consigne.source : null
                            });
                            isMsgSend = true;
                            node.send([msg, null]);
                        } else {
                            debugBlocked(zone, materiels[i], "consigne", consigneCommandValue, "MAINTENANCE");
                        }
                    }
                }

                // Le mode est force a l'envoi si la saisonnalite retenue vient d'un evenement.
                // La transition de sortie d'evenement est egalement forcee pour renvoyer
                // l'equipement vers son mode normal.
                if (params.gestionModeCLIM == 1 || mustHandleEventModeTransition) {
                    const modeCommandValue =
                        restorePreEventSnapshot && snapshotModeBeforeEvent !== null
                            ? snapshotModeBeforeEvent
                            : !eventForcesMode && eventWasForcingMode && currentSeasonIndex === 0
                                ? 0
                            : modeClimZone;
                    const modeLastSendExpired = compareTimestamp(Date.now(), lastSend.timestampLastSend, intervalRenvoi);
                    const mustResendMode =
                        mustHandleEventModeTransition ||
                        lastSend.modeClimLastSend !== modeCommandValue ||
                        modeLastSendExpired;

                    if (mustResendMode) {
                        if (
                            mustHandleEventModeTransition ||
                            statusMode !== modeCommandValue ||
                            modeLastSendExpired
                        ) {
                            const modePayloadValue = tabConversionModeSEM_COOL[modeCommandValue];

                            // 0=Mode Clim / 1=Vitesse Ventilation / 2=Consigne / 3=allumage / 4=Filter Sign / 5=Rotation Ailette / 6=Temp. ambiante
                            msg.payload = {
                                value: modePayloadValue,
                                fc: 6,
                                unitid: 1,
                                address: materiels[i].address + 0,
                                quantity: 1
                            };

                            if (actionMaintenance == 0) {
                                debugSend(zone, materiels[i], "mode", modeCommandValue, {
                                    reason: getModeReason(restorePreEventSnapshot, eventForcesMode, eventWasForcingMode, currentSeasonIndex, lastSend.modeClimLastSend, modeCommandValue, modeLastSendExpired),
                                    statusValue: statusMode,
                                    rawValue: modeCommandValue,
                                    payloadValue: modePayloadValue,
                                    computedModeValue: modeClimZone,
                                    snapshotModeBeforeEvent: snapshotModeBeforeEvent,
                                    seasonIndex: currentSeasonIndex,
                                    seasonalitySource: resolution.seasonality ? resolution.seasonality.source : null,
                                    eventWasForcingMode: eventWasForcingMode
                                });
                                isMsgSend = true;
                                node.send([msg, null]);
                            } else {
                                debugBlocked(zone, materiels[i], "mode", modeCommandValue, "MAINTENANCE");
                            }
                        } else {
                            debugSkipped(zone, materiels[i], "mode", modeCommandValue, {
                                reason: "STATUS_ALREADY_ALIGNED",
                                statusValue: statusMode,
                                lastSendValue: lastSend.modeClimLastSend,
                                computedModeValue: modeClimZone,
                                seasonIndex: currentSeasonIndex,
                                seasonalitySource: resolution.seasonality ? resolution.seasonality.source : null,
                                eventWasForcingMode: eventWasForcingMode
                            });
                        }
                    } else {
                        debugSkipped(zone, materiels[i], "mode", modeCommandValue, {
                            reason: "LAST_SEND_ALREADY_ALIGNED",
                            statusValue: statusMode,
                            lastSendValue: lastSend.modeClimLastSend,
                            computedModeValue: modeClimZone,
                            seasonIndex: currentSeasonIndex,
                            seasonalitySource: resolution.seasonality ? resolution.seasonality.source : null,
                            eventWasForcingMode: eventWasForcingMode
                        });
                    }
                } else {
                    debugSkipped(zone, materiels[i], "mode", modeClimZone, {
                        reason: "GESTION_MODE_DISABLED",
                        statusValue: statusMode,
                        lastSendValue: lastSend.modeClimLastSend,
                        seasonalitySource: resolution.seasonality ? resolution.seasonality.source : null,
                        eventWasForcingMode: eventWasForcingMode
                    });
                }

                const restoreSnapshotSatisfied =
                    restorePreEventSnapshot &&
                    actionMaintenance == 0 &&
                    (snapshotModeBeforeEvent === null || statusMode === (snapshotModeBeforeEvent !== null ? snapshotModeBeforeEvent : modeClimZone)) &&
                    (snapshotConsigneBeforeEvent === null || statusConsigne === consigneCommandValue);

                if (restoreSnapshotSatisfied && eventRestoreState[restoreKey]) {
                    delete eventRestoreState[restoreKey];
                    eventRestoreStateChanged = true;
                }

                if (isMsgSend) {
                    listChangeMaterielsId.push({
                        key: i,
                        data: {
                            timestampLastSend: Date.now(),
                            dateLastSend: getDateString(),
                            modeClimLastSend: restorePreEventSnapshot && snapshotModeBeforeEvent !== null
                                ? snapshotModeBeforeEvent
                                : !eventForcesMode && eventWasForcingMode && currentSeasonIndex === 0
                                    ? 0
                                    : modeClimZone,
                            consigneClimLastSend: consigneCommandValue,
                            pilotageClimLastSend: pilotageClimZone,
                            eventModeOverrideLastSend: eventForcesMode,
                            consigneTorLastSend: "",
                            pilotageTorLastSend: "",
                            downlink: "",
                            received: false
                        }
                    });
                }
            }
        }
    }
}

