function logZoneDebug(zoneNum, materielData, calculatedValues, sendInfo, conditions, intervalRenvoiMin) {
    if (!DEBUG_CONFIG.ENABLED) return;
    if (DEBUG_CONFIG.MODE === "none") return;
    if (DEBUG_CONFIG.MODE === "zones" && !DEBUG_CONFIG.ZONES.includes(Number(zoneNum))) return;

    const last = (materielData && materielData.lastSend) ? materielData.lastSend : {};
    const sinceSec = last.timestampLastSend ? Math.floor((Date.now() - last.timestampLastSend) / 1000) : "n/a";

    let debugMsg = `
