for (let i = 0; i < materiels.length; i++) {
    if (materiels[i].type == "INTESIS" && materiels[i].ip == addressIP) {
        let keyZones = -1;
        for (let y = 0; y < zones.length; y++) {
            if (zones[y].numero == materiels[i].numero) {
                keyZones = y;
                break;
            }
        }
        if (keyZones === -1) continue;
        if (zones[keyZones].activationRegul != true) continue;

        let pilotageClimZone = Number(zones[keyZones].data.pilotageClimZone);
        let consigneClimZone = Number(zones[keyZones].data.consigneClimZone);
        let modeClimZone = Number(zones[keyZones].data.modeClimZone);

        let statusAllumage = Number(zones[keyZones].data.statusAllumage.value);
        let statusConsigne = Number(zones[keyZones].data.statusConsigne.value);
        let statusMode = Number(zones[keyZones].data.statusMode.value);
        let temp = Number(zones[keyZones].data.temp.value);
        let resolution = zones[keyZones].data.resolution || {};
        let eventModeBypass = resolution.seasonality && resolution.seasonality.source === "EVENT";

        materiels[i].lastSend = materiels[i].lastSend || {};
        if (materiels[i].lastSend.timestampLastSend === undefined) materiels[i].lastSend.timestampLastSend = 0;
        if (materiels[i].lastSend.pilotageClimLastSend === undefined) materiels[i].lastSend.pilotageClimLastSend = statusAllumage;
        if (materiels[i].lastSend.consigneClimLastSend === undefined) materiels[i].lastSend.consigneClimLastSend = statusConsigne;
        if (materiels[i].lastSend.modeClimLastSend === undefined) materiels[i].lastSend.modeClimLastSend = modeClimZone;
        if (materiels[i].lastSend.fanSpeedLastSend === undefined) materiels[i].lastSend.fanSpeedLastSend = 0;

        let sendInfo = {
            pilotage: { send: false },
            consigne: { send: false },
            mode: { send: false },
            ventilation: { send: false }
        };

        const nowTs = Date.now();
        const lastTs = Number(materiels[i].lastSend.timestampLastSend) || 0;
        const isTransitionToAbsent = (pilotageClimZone === 0 && Number(materiels[i].lastSend.pilotageClimLastSend) === 1);

        if (zones[keyZones].allumageManuel == false) {
            if (materiels[i].lastSend.pilotageClimLastSend !== pilotageClimZone || compareTimestamp(nowTs, lastTs, intervalRenvoi)) {
                if (statusAllumage !== pilotageClimZone || compareTimestamp(nowTs, lastTs, intervalRenvoi)) {
                    if (zones[keyZones].occupationPermanente == true || compareTimestamp(nowTs, lastTs, intervalRenvoi)) {
                        sendInfo.pilotage.send = true;
                        messagesList.push({
                            key: i,
                            unitid: materiels[i].address,
                            type: "pilotage",
                            modbusRegister: 0,
                            modbusValue: pilotageClimZone,
                            fc: 6,
                            quantity: 1,
                            oldValue: materiels[i].lastSend.pilotageClimLastSend
                        });
                    }
                }
            }
        }

        if (materiels[i].lastSend.consigneClimLastSend !== consigneClimZone || compareTimestamp(nowTs, lastTs, intervalRenvoi)) {
            if (statusConsigne !== consigneClimZone || compareTimestamp(nowTs, lastTs, intervalRenvoi)) {
                let valueToSend = consigneClimZone;
                if (consigneClimZone < 16) valueToSend = 16;

                sendInfo.consigne.send = true;
                messagesList.push({
                    key: i,
                    unitid: materiels[i].address,
                    type: "consigne",
                    modbusRegister: 4,
                    modbusValue: valueToSend,
                    fc: 6,
                    quantity: 1,
                    oldValue: materiels[i].lastSend.consigneClimLastSend
                });
            }
        }

        if ((params.gestionModeCLIM == 1 || eventModeBypass)) {
            if (materiels[i].lastSend.modeClimLastSend !== modeClimZone || compareTimestamp(nowTs, lastTs, intervalRenvoi)) {
                if (statusMode !== modeClimZone || compareTimestamp(nowTs, lastTs, intervalRenvoi)) {
                    sendInfo.mode.send = true;
                    messagesList.push({
                        key: i,
                        unitid: materiels[i].address,
                        type: "mode",
                        modbusRegister: 1,
                        modbusValue: tabModeClimSEM_INTESIS[modeClimZone],
                        fc: 6,
                        quantity: 1,
                        oldValue: materiels[i].lastSend.modeClimLastSend,
                        semValue: modeClimZone
                    });
                }
            }
        }

        if (pilotageClimZone === 1 && !isTransitionToAbsent) {
            const FAN_AUTO_VALUE = 0;

            if (materiels[i].lastSend.fanSpeedLastSend !== FAN_AUTO_VALUE || compareTimestamp(nowTs, lastTs, intervalRenvoi)) {
                sendInfo.ventilation.send = true;
                messagesList.push({
                    key: i,
                    unitid: materiels[i].address,
                    type: "ventilation",
                    modbusRegister: 2,
                    modbusValue: FAN_AUTO_VALUE,
                    fc: 6,
                    quantity: 1,
                    oldValue: materiels[i].lastSend.fanSpeedLastSend
                });
            }
        }

        logZoneDebug(
            zones[keyZones].numero,
            materiels[i],
            {
                statusAllumage,
                statusMode,
                statusConsigne,
                temp,
                pilotageClimZone,
                consigneClimZone,
                modeClimZone
            },
            sendInfo,
            {
                zoneActivationRegul: zones[keyZones].activationRegul == true,
                zoneAllumageManuel: zones[keyZones].allumageManuel == true,
                zoneOccupationPermanente: zones[keyZones].occupationPermanente == true,
                eventModeBypass
            },
            intervalRenvoi
        );
    }
}

for (let j = 0; j < messagesList.length; j++) {
    const m = messagesList[j];
    const key = m.key;

    msg.payload = {
        value: m.modbusValue,
        fc: m.fc,
        unitid: m.unitid,
        address: m.modbusRegister,
        quantity: m.quantity
    };

    if (actionMaintenance == 0) {
        node.status({
            fill: "green",
            shape: "dot",
            text: `INTESIS UnitID:${m.unitid} ${m.type.toUpperCase()} Reg:${m.modbusRegister} (${m.oldValue}→${m.modbusValue})`
        });

        node.send(msg);

        if (m.type === "pilotage") {
            materiels[key].lastSend.pilotageClimLastSend = m.modbusValue;
        } else if (m.type === "consigne") {
            materiels[key].lastSend.consigneClimLastSend = m.modbusValue;
        } else if (m.type === "mode") {
            materiels[key].lastSend.modeClimLastSend = m.semValue;
        } else if (m.type === "ventilation") {
            materiels[key].lastSend.fanSpeedLastSend = m.modbusValue;
        }

        materiels[key].lastSend.timestampLastSend = Date.now();
        materiels[key].lastSend.dateLastSend = getDateString();
        materiels[key].lastSend.received = false;
    } else {
        node.status({
            fill: "yellow",
            shape: "dot",
            text: `MAINTENANCE: INTESIS UnitID:${m.unitid} ${m.type.toUpperCase()} NON envoyé`
        });
    }
}

