function compareTimestamp(timestamp1, timestamp2, intervalle) {
    const differenceInMilliseconds = Math.abs(timestamp1 - timestamp2);
    const intervallInMilliseconds = intervalle * 60 * 1000;
    return differenceInMilliseconds > intervallInMilliseconds;
}

