                const cond2_consigneDifferent = statusConsigne !== consigneClimZone;
                const cond2_consigneIntervalExceeded = timeDiff > intervalMs;
                const cond2_consigneResult = (cond2_consigneDifferent || cond2_consigneIntervalExceeded) && cond1_consigneResult;

