                        fc: 6,
                        quantity: 1,
                        oldValue: materiels[i].lastSend.consigneClimLastSend
                    });
                }

                const cond1_modeChanged = materiels[i].lastSend.modeClimLastSend !== modeClimZone;
                const cond1_modeIntervalExceeded = timeDiff > intervalMs;
                const cond1_modeResult = cond1_modeChanged || cond1_modeIntervalExceeded;

                const cond2_modeDifferent = statusMode !== modeClimZone;
                const cond2_modeIntervalExceeded = timeDiff > intervalMs;
                const cond2_modeResult = (cond2_modeDifferent || cond2_modeIntervalExceeded) && cond1_modeResult;

