        node.warn({
            message: "✅ Données valides reçues",
            formatDetected: formatDetected,
            dataLength: readData.length,
            data: JSON.stringify(readData),
            unitidReceived: msg.modbusRequest?.unitid || msg.unitId || msg.queueUnitId
        });
    }
}

// ====== TRAITEMENT SI DONNÉES VALIDES ======
if (hasValidData && msg.modbusRequest) {
    const requestTimestamp = msg.modbusRequest?.timestamp || Date.now();
    const unitidFromRequest = msg.modbusRequest?.unitid || msg.unitId || msg.queueUnitId;

    let processingSuccess = false;

    for (let x = 0; x < materiels.length; x++) {
        const addressRead = unitidFromRequest;

        if (materiels[x].type == 'INTESIS' &&
            materiels[x].ip == addressIP &&
            Number(materiels[x].address) == Number(addressRead)) {

            keyZones = -1;

            // ✅ Recherche de la zone
            for (let y = 0; y < zones.length; y++) {
                if (Number(zones[y].numero) === Number(materiels[x].numero)) {
                    keyZones = y;
                    break;  // ✅ Sortir une fois trouvée
                }
            }

            if (keyZones != -1) {
                processingSuccess = true;

                // Registre Modbus pour INTESIS : 
                // 0=Allumage / 1=Mode Clim / 2=Vitesse Ventilation / 3=Rotation Ailette / 4=Consigne / 5=Temp.  ambiante
                if (readData[1] <= 4) {
                    zones[keyZones].data.statusMode.value = tabModeClimINTESIS_SEM[readData[1]];
                } else {
                    zones[keyZones].data.statusMode.value = 0;
                }
                zones[keyZones].data.statusMode.timestamp = Date.now();
                zones[keyZones].data.statusMode.date = getDateString();

                zones[keyZones].data.statusConsigne.value = readData[4];
                zones[keyZones].data.statusConsigne.timestamp = Date.now();
                zones[keyZones].data.statusConsigne.date = getDateString();

                zones[keyZones].data.statusAllumage.value = readData[0];
                zones[keyZones].data.statusAllumage.timestamp = Date.now();
                zones[keyZones].data.statusAllumage.date = getDateString();

                // Cas où la source de température est INTESIS
                if (zones[keyZones].sourceTemp == 2) {
                    zones[keyZones].data.temp.value = readData[5];
                    zones[keyZones].data.temp.timestamp = Date.now();
                    zones[keyZones].data.temp.date = getDateString();
                }

                // Construction de l'IP extérieure
                const ip1Match = dns.match(/^(\d+\.\d+\.\d+)/);
                const ip1Result = ip1Match ? ip1Match[1] : "N/A";
                const ip2Match = addressIP.match(/(\d+):(\d+)$/);
                const ip2Result = ip2Match ? `${ip2Match[1]}: ${ip2Match[2]}` : "N/A";
                const materielIP = ip1Result + '.' + ip2Result;

                // Enregistrement des données dans materiels
                newObject = {
                    "timestamp": Date.now(),
                    "date": getDateString(),
                    "ip": materielIP,
                    "num_zone": materiels[x].numero,
                    "unitId": materiels[x].address,
                    "register": 0,
                    "key": x,
                    "mode": tabModeClimINTESIS_SEM[readData[1]],
                    "ventilation": readData[2],
                    "consigne": readData[4],
                    "allumage": readData[0],
                    "ailette": readData[3],
                    "temp": readData[5]
                };

                // Ajout des données au tableau
                dataToSend = [];
                for (let j = 0; j < tabReadValueIntesis.length; j++) {
                    dataToSend.push({
                        "timestamp": Date.now(),
                        "date": getDateString(),
                        "ip": materielIP,
                        "num_zone": materiels[x].numero,
                        "unitId": materiels[x].address,
                        "register": j,
                        "type": tabReadValueIntesis[j],
                        "value": readData[j]
                    });
                }

                // Log de succès (avec filtre debug)
                logRegisterDebug(
                    materiels[x],
                    {
                        allumage: readData[0],
                        mode: readData[1],
                        ventilation: readData[2],
                        ailette: readData[3],
                        consigne: (readData[4]).toFixed(1),
                        temperature: (readData[5]).toFixed(1)
                    },
                    requestTimestamp,
                    formatDetected
                );

                node.status({
                    fill: "green",
                    shape: "dot",
                    text: `✅ Lecture INTESIS UC300_02 réussie - UnitID: ${materiels[x].address} - Zone ${materiels[x].numero} - ${(readData[5]).toFixed(1)}°C`
                });

                break;
            }
        }
    }

    // Gestion des erreurs
    if (!processingSuccess) {
        node.status({
            fill: "red",
            shape: "ring",
            text: "❌ Lecture INTESIS UC300_02 échouée - Zone/UnitID non trouvé"
        });

        // ✅ Afficher erreur UNIQUEMENT si debug activé
        if (DEBUG_CONFIG.ENABLED && DEBUG_CONFIG.MODE !== "none") {
            node.warn({
                message: "❌ Zone ou matériel non trouvé pour cette UnitID",
                unitidFromRequest: unitidFromRequest,
                addressIP: addressIP,
                dataReceived: JSON.stringify(readData)
            });
        }
    }
} else {
    // Pas de données valides
    node.status({
        fill: "orange",
        shape: "ring",
        text: "⚠️  Pas de données valides reçues"
    });

    // ✅ Afficher erreur UNIQUEMENT si debug activé
    if (DEBUG_CONFIG.ENABLED && DEBUG_CONFIG.MODE !== "none") {
        logDebugMessage("⚠️  Pas de données valides reçues pour traitement");
    }
}

// ✅ Exporter les sorties
global.set("zones", zones);
global.set("materiels", materiels);

msg.filename = "intesisUC300_02.json";
msg.payload = dataToSend;
msg.topic = "registerData";
msg.mac = global.get("mac");
msg.siteId = global.get("siteId");
msg.file = { "format": "utf8", "encoding": "utf8" };
msg.newData = newObject;

return msg;

