function getDateString() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, "0");
    const day = String(now.getDate()).padStart(2, "0");
    const hours = String(now.getHours()).padStart(2, "0");
    const minutes = String(now.getMinutes()).padStart(2, "0");
    const seconds = String(now.getSeconds()).padStart(2, "0");
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

function compareTimestamp(timestamp1, timestamp2, intervalle) {
    const differenceInMilliseconds = Math.abs(timestamp1 - timestamp2);
    const intervallInMilliseconds = intervalle * 60 * 1000;
    return differenceInMilliseconds > intervallInMilliseconds;
}

for (let i = 0; i < materiels.length; i++) {
    if (materiels[i].type == "INTESIS" && materiels[i].ip == addressIP) {
        keyZones = -1;

        for (let y = 0; y < zones.length; y++) {
            if (Number(zones[y].numero) === Number(materiels[i].numero)) {
                keyZones = y;
                break;
            }
        }

        if (keyZones != -1) {
            const zoneActivationRegul = Number(zones[keyZones].activationRegul);
            const zoneAllumageManuel = Number(zones[keyZones].allumageManuel);
            const zoneOccupationPermanente = Number(zones[keyZones].occupationPermanente);
            const resolution = zones[keyZones].data.resolution || {};
            const eventModeBypass = resolution.seasonality && resolution.seasonality.source === "EVENT";

            if (zoneActivationRegul === 1) {
                const pilotageClimZone = Number(zones[keyZones].data.pilotageClimZone);
                const consigneClimZone = Number(zones[keyZones].data.consigneClimZone);
                const modeClimZone = Number(zones[keyZones].data.modeClimZone);
                const statusAllumage = Number(zones[keyZones].data.statusAllumage.value);
                const statusConsigne = Number(zones[keyZones].data.statusConsigne.value);
                const statusMode = Number(zones[keyZones].data.statusMode.value);
                const temp = Number(zones[keyZones].data.temp.value);
                const unitid = materiels[i].address;

                if (materiels[i].lastSend && materiels[i].lastSend.fanSpeedLastSend === undefined) {
                    materiels[i].lastSend.fanSpeedLastSend = 0;
                }

                let sendInfo = {
                    pilotage: { send: false },
                    consigne: { send: false },
                    mode: { send: false },
                    ventilation: { send: false }
                };

                const now = Date.now();
                const timeDiff = now - materiels[i].lastSend.timestampLastSend;
                const intervalMs = intervalRenvoi * 60 * 1000;
                const isTransitionToAbsent =
                    (pilotageClimZone === 0 && Number(materiels[i].lastSend.pilotageClimLastSend) === 1);

                if (zoneAllumageManuel === 0) {
                    const cond1_pilotageChanged = materiels[i].lastSend.pilotageClimLastSend !== pilotageClimZone;
                    const cond1_intervalExceeded = timeDiff > intervalMs;
                    const cond1_result = cond1_pilotageChanged || cond1_intervalExceeded;

                    const cond2_statusDifferent = statusAllumage !== pilotageClimZone;
                    const cond2_intervalExceeded = timeDiff > intervalMs;
                    const cond2_result = (cond2_statusDifferent || cond2_intervalExceeded) && cond1_result;

                    const cond3_intervalExceeded = timeDiff > intervalMs;
                    const cond3_pilotageResult = (zoneOccupationPermanente == 1 || cond3_intervalExceeded) && cond2_result;

                    if (cond3_pilotageResult) {
                        sendInfo.pilotage = { send: true };
                        messagesList.push({
                            key: i,
                            unitid,
                            type: "pilotage",
                            modbusRegister: 0,
                            modbusValue: pilotageClimZone,
                            fc: 6,
                            quantity: 1,
                            oldValue: materiels[i].lastSend.pilotageClimLastSend
                        });
                    }
                }

                const cond1_consigneChanged = materiels[i].lastSend.consigneClimLastSend !== consigneClimZone;
                const cond1_consigneIntervalExceeded = timeDiff > intervalMs;
                const cond1_consigneResult = cond1_consigneChanged || cond1_consigneIntervalExceeded;

                const cond2_consigneDifferent = statusConsigne !== consigneClimZone;
                const cond2_consigneIntervalExceeded = timeDiff > intervalMs;
                const cond2_consigneResult = (cond2_consigneDifferent || cond2_consigneIntervalExceeded) && cond1_consigneResult;

                if (cond2_consigneResult) {
                    sendInfo.consigne = { send: true };
                    let valueToSend = Math.floor(consigneClimZone);
                    if (consigneClimZone < 16) {
                        valueToSend = 16;
                    }

                    messagesList.push({
                        key: i,
                        unitid,
                        type: "consigne",
                        modbusRegister: 4,
                        modbusValue: valueToSend,
                        fc: 6,
                        quantity: 1,
                        oldValue: materiels[i].lastSend.consigneClimLastSend
                    });
                }

                const cond1_modeChanged = materiels[i].lastSend.modeClimLastSend !== modeClimZone;
                const cond1_modeIntervalExceeded = timeDiff > intervalMs;
                const cond1_modeResult = cond1_modeChanged || cond1_modeIntervalExceeded;

                const cond2_modeDifferent = statusMode !== modeClimZone;
                const cond2_modeIntervalExceeded = timeDiff > intervalMs;
                const cond2_modeResult = (cond2_modeDifferent || cond2_modeIntervalExceeded) && cond1_modeResult;

                if ((params.gestionModeCLIM == 1 || eventModeBypass) && cond2_modeResult) {
                    sendInfo.mode = { send: true };
                    messagesList.push({
                        key: i,
                        unitid,
                        type: "mode",
                        modbusRegister: 1,
                        modbusValue: tabModeClimSEM_INTESIS[modeClimZone],
                        fc: 6,
                        quantity: 1,
                        oldValue: materiels[i].lastSend.modeClimLastSend,
                        semValue: modeClimZone
                    });
                }

                if (pilotageClimZone === 1 && !isTransitionToAbsent) {
                    const FAN_AUTO_VALUE = 0;
                    const cond1_fanChanged = (materiels[i].lastSend.fanSpeedLastSend !== FAN_AUTO_VALUE);
                    const cond2_fanIntervalExceeded = (timeDiff > intervalMs);
                    const cond_fanResult = cond1_fanChanged || cond2_fanIntervalExceeded;

                    if (cond_fanResult) {
                        sendInfo.ventilation = { send: true };
                        messagesList.push({
                            key: i,
                            unitid,
                            type: "ventilation",
                            modbusRegister: 2,
                            modbusValue: FAN_AUTO_VALUE,
                            fc: 6,
                            quantity: 1,
                            oldValue: materiels[i].lastSend.fanSpeedLastSend
                        });
                    }
                }

                logZoneDebug(
                    zones[keyZones].numero,
                    materiels[i],
                    {
                        statusAllumage,
                        statusMode,
                        statusConsigne,
                        temp,
                        pilotageClimZone,
                        consigneClimZone,
                        modeClimZone
                    },
                    sendInfo,
                    {
                        zoneActivationRegul,
                        zoneAllumageManuel,
                        zoneOccupationPermanente,
                        eventModeBypass
                    }
                );
            }
        }
    }
}

for (let j = 0; j < messagesList.length; j++) {
