        msg.payload = modbusMsg;
        node.send(msg);

        if (msg_item.type === "pilotage") {
            materiels[key].lastSend.pilotageClimLastSend = msg_item.modbusValue;
        } else if (msg_item.type === "consigne") {
            materiels[key].lastSend.consigneClimLastSend = msg_item.modbusValue;
        } else if (msg_item.type === "mode") {
            materiels[key].lastSend.modeClimLastSend = msg_item.semValue;
        } else if (msg_item.type === "ventilation") {
            materiels[key].lastSend.fanSpeedLastSend = msg_item.modbusValue;
        }

        materiels[key].lastSend.timestampLastSend = Date.now();
        materiels[key].lastSend.dateLastSend = getDateString();
    } else {
        node.status({
            fill: "yellow",
            shape: "dot",
            text: `Mode MAINTENANCE: INTESIS UC300_02 UnitID: ${msg_item.unitid} ${msg_item.type.toUpperCase()} NON envoyé`
        });
    }
}

