function getDateString() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, "0");
    const day = String(now.getDate()).padStart(2, "0");
    const hours = String(now.getHours()).padStart(2, "0");
    const minutes = String(now.getMinutes()).padStart(2, "0");
    const seconds = String(now.getSeconds()).padStart(2, "0");
    return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}

function compareTimestamp(timestamp1, timestamp2, intervalle) {
    const differenceInMilliseconds = Math.abs(timestamp1 - timestamp2);
    const intervallInMilliseconds = intervalle * 60 * 1000;
    return differenceInMilliseconds > intervallInMilliseconds;
}

for (let i = 0; i < materiels.length; i++) {
    if (materiels[i].type == "INTESIS" && materiels[i].ip == addressIP) {
        keyZones = -1;

        for (let y = 0; y < zones.length; y++) {
