                const timeDiff = now - materiels[i].lastSend.timestampLastSend;
                const intervalMs = intervalRenvoi * 60 * 1000;
                const isTransitionToAbsent =
                    (pilotageClimZone === 0 && Number(materiels[i].lastSend.pilotageClimLastSend) === 1);

                if (zoneAllumageManuel === 0) {
